window.__PC_DECK_LAST__ = [{"no": 1, "id": 1119, "type": "single", "select": 1, "question": "A developer creates an AI coding assistant for a known workflow with repeatable steps. \n\nWhich design approach is appropriate?", "imageMissing": false, "options": [{"key": "A", "text": "Allow unlimited autonomous exploration"}, {"key": "B", "text": "Use a fixed sequence of prompts"}, {"key": "C", "text": "Remove all workflow instructions"}, {"key": "D", "text": "Use random decision paths"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use a fixed sequence of prompts\n\nChuỗi prompt cố định phù hợp bước đã biết và lặp lại: dễ kiểm tra đầu vào/đầu ra từng bước mà không cần agent tự tìm đường.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Allow unlimited autonomous exploration**: Tự khám phá vô hạn thêm chi phí và rủi ro không cần cho quy trình đã biết.\n- **Remove all workflow instructions**: Bỏ hướng dẫn làm mất hợp đồng từng bước.\n- **Use random decision paths**: Đường đi ngẫu nhiên phá tính lặp lại cần thiết.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}]}, {"no": 2, "id": 1120, "type": "single", "select": 1, "question": "A team wants stable automated pull request review results from Claude Code. \n\nWhich method best supports automation?", "imageMissing": false, "options": [{"key": "A", "text": "Use stricter markdown parsing rules"}, {"key": "B", "text": "Use JSON output with a defined schema"}, {"key": "C", "text": "Split responses using headings"}, {"key": "D", "text": "Post the entire response for manual review"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use JSON output with a defined schema\n\nJSON theo schema cố định cho CI đọc field và validate tự động, thay vì đoán bố cục câu chữ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Split responses using headings**: Heading chỉ định dạng văn bản, không ràng buộc kiểu dữ liệu.\n- **Use stricter markdown parsing rules**: Parser Markdown chặt vẫn dễ hỏng khi câu chữ đổi.\n- **Post the entire response for manual review**: Review toàn response thủ công không đáp ứng tự động hóa.\n\n**Tham khảo:**\n\n- [Structured outputs](https://platform.claude.com/docs/en/build-with-claude/structured-outputs)\n- [Claude Code CLI reference](https://code.claude.com/docs/en/cli-reference)", "references": [{"title": "Structured outputs", "url": "https://platform.claude.com/docs/en/build-with-claude/structured-outputs"}, {"title": "Claude Code CLI reference", "url": "https://code.claude.com/docs/en/cli-reference"}]}, {"no": 3, "id": 1121, "type": "single", "select": 1, "question": "A team needs to update every file ending with `.fixture.json` across a monorepo. Searching for the word “fixture” creates noisy results and misses sparse files. \n\nWhich tool-use strategy should be adopted?", "imageMissing": false, "options": [{"key": "A", "text": "Use Bash commands and paste the entire directory listing."}, {"key": "B", "text": "Use Glob patterns like `**/*.fixture.json` and then Read matching files."}, {"key": "C", "text": "Use Grep for \"fixture\" and infer matching files."}, {"key": "D", "text": "Read all possible files before searching."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use Glob patterns like `**/*.fixture.json` and then Read matching files.\n\nGlob khớp hậu tố đường dẫn nên tìm được cả file ít nội dung; Read sau đó chỉ đọc ứng viên đúng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Use Bash commands and paste the entire directory listing.**: Pasting cả listing tốn context và không khoanh chính xác hậu tố.\n- **Read all possible files before searching.**: Đọc mọi file trước làm tăng công và nhiễu không cần thiết.\n- **Use Grep for \"fixture\" and infer matching files.**: Grep tìm nội dung, không bảo đảm tên file có hậu tố mong muốn.\n\n**Tham khảo:**\n\n- [Claude Code best practices](https://code.claude.com/docs/en/best-practices)", "references": [{"title": "Claude Code best practices", "url": "https://code.claude.com/docs/en/best-practices"}]}, {"no": 4, "id": 1122, "type": "single", "select": 1, "question": "**Scenario**: \n\nDeveloper Productivity with Claude Your CI job invokes Claude Code successfully and posts a single pull request summary comment. \n\nThe team now wants automated inline comments for each finding, but the integration frequently breaks because Claude sometimes adds prose, changes field names, or formats findings as markdown. \n\nWhat change best supports reliable automation?", "imageMissing": false, "options": [{"key": "A", "text": "Run Claude Code with `--output-format json` and `--json-schema`, then map validated findings to inline PR comments."}, {"key": "B", "text": "Parse Claude's markdown bullets with regular expressions."}, {"key": "C", "text": "Store previous comments and ask Claude to rewrite them into records."}, {"key": "D", "text": "Strengthen the prompt to demand valid JSON only."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Run Claude Code with `--output-format json` and `--json-schema`, then map validated findings to inline PR comments.\n\nOutput JSON cùng JSON Schema ổn định hợp đồng findings để validate trước khi ánh xạ sang inline comments; vẫn phải kiểm tra line/path hợp lệ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Parse Claude's markdown bullets with regular expressions.**: Regex Markdown phụ thuộc bố cục thay đổi.\n- **Strengthen the prompt to demand valid JSON only.**: Chỉ prompt đòi JSON không ràng buộc field như schema.\n- **Store previous comments and ask Claude to rewrite them into records.**: Viết lại comment cũ không bảo đảm record mới đúng schema.\n\n**Tham khảo:**\n\n- [Claude Code CLI reference](https://code.claude.com/docs/en/cli-reference)\n- [Structured outputs](https://platform.claude.com/docs/en/build-with-claude/structured-outputs)", "references": [{"title": "Claude Code CLI reference", "url": "https://code.claude.com/docs/en/cli-reference"}, {"title": "Structured outputs", "url": "https://platform.claude.com/docs/en/build-with-claude/structured-outputs"}]}, {"no": 5, "id": 1123, "type": "single", "select": 1, "question": "**Scenario**: \n\nMulti-Agent Research System The document analysis subagent receives coordinator-selected PDFs and reports from an approved catalog, but it has a generic URL retrieval tool. \n\nIt sometimes follows links inside documents to: l blogs l login pages l duplicate HTML summaries and then cites those pages instead of the approved sources. \n\nWhat change best addresses this?", "imageMissing": false, "options": [{"key": "A", "text": "Give the document analysis subagent web search tools too, so it can independently confirm whether linked pages are relevant."}, {"key": "B", "text": "Keep fetch_url available, but add prompt instructions warning the subagent never to open links found inside documents."}, {"key": "C", "text": "Allow fetch_url for any link, then have synthesis discard citations whose domains are not in the approved catalog."}, {"key": "D", "text": "Replace fetch_url with a load_document tool that accepts catalog document IDs or approved URLs and validates before fetching."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Replace fetch_url with a load_document tool that accepts catalog document IDs or approved URLs and validates before fetching.\n\nload_document kiểm tra ID/URL trong catalog tại biên truy cập, nên tài liệu không thể tự mở rộng nguồn được phép qua link nhúng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Keep fetch_url available, but add prompt instructions warning the subagent never to open links found inside documents.**: Cảnh báo trong prompt không cưỡng chế giới hạn URL ở công cụ.\n- **Give the document analysis subagent web search tools too, so it can independently confirm whether linked pages are relevant.**: Thêm search mở rộng nguồn thay vì chặn nguồn ngoài catalog.\n- **Allow fetch_url for any link, then have synthesis discard citations whose domains are not in the approved catalog.**: Lọc cuối quá muộn vì agent đã truy cập và dựa vào nguồn sai.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}]}, {"no": 6, "id": 1124, "type": "single", "select": 1, "question": "A coordinator launches subagents to analyze API handlers, database writes, and scheduled jobs. \n\nFinal architecture reports often attach claims to incorrect files or omit line ranges. \n\nWhat improves handoff reliability?", "imageMissing": false, "options": [{"key": "A", "text": "Require structured handoff records with paths, symbols, line ranges, and evidence snippets."}, {"key": "B", "text": "Concatenate complete transcripts"}, {"key": "C", "text": "Ask the synthesizer to reconstruct locations."}, {"key": "D", "text": "Use regex parsing on summaries."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Require structured handoff records with paths, symbols, line ranges, and evidence snippets.\n\nHandoff có path, symbol, dòng và trích dẫn giữ liên kết claim→evidence, giúp synthesizer kiểm tra thay vì tái dựng vị trí.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Concatenate complete transcripts**: Transcript dài khó tìm bằng chứng và vẫn có thể gắn nhầm.\n- **Use regex parsing on summaries.**: Regex summary không phục hồi evidence bị bỏ mất.\n- **Ask the synthesizer to reconstruct locations.**: Tự dựng location từ suy đoán tạo citation không kiểm chứng.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}, {"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 7, "id": 1125, "type": "single", "select": 1, "question": "**Scenario**: \n\nStructured Data Extraction Your QA pipeline flags mistakes in supplier contracts. \n\nAnalysts accept many findings about missing renewal clauses but reject most findings involving informal pricing language. \n\nCurrent logs store only: l Document ID l Field name l Confidence l Finding text \n\nWhat change should you make first?", "imageMissing": false, "options": [{"key": "A", "text": "Increase QA confidence threshold globally."}, {"key": "B", "text": "Add a structured detected_pattern field to each QA finding, then analyze acceptance rates by pattern and document type."}, {"key": "C", "text": "Store only analyst decisions."}, {"key": "D", "text": "Tell Claude to report only findings analysts accept."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add a structured detected_pattern field to each QA finding, then analyze acceptance rates by pattern and document type.\n\ndetected_pattern bổ sung chiều phân loại lỗi, cho biết pattern giá nào hay bị bác trong từng loại hợp đồng trước khi thay threshold.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Increase QA confidence threshold globally.**: Tăng threshold chung có thể loại cả findings đúng ở nhóm khác.\n- **Store only analyst decisions.**: Chỉ quyết định người review làm mất context pattern gây lỗi.\n- **Tell Claude to report only findings analysts accept.**: Yêu cầu chỉ báo điều được chấp nhận không định nghĩa tiêu chí đo được.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 8, "id": 1126, "type": "single", "select": 1, "question": "A multi-agent system uses a coordinator and specialized researchers. \n\nHow should required MCP server configuration be shared across a team repository?", "imageMissing": false, "options": [{"key": "A", "text": "Ask every user to recreate servers manually"}, {"key": "B", "text": "Store all servers in personal user configuration"}, {"key": "C", "text": "Combine all integrations into one MCP server"}, {"key": "D", "text": "Place required shared servers in project-scoped .mcp.json"}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Place required shared servers in project-scoped .mcp.json\n\nmcp.json cấp project chia sẻ cấu hình server cần thiết qua repository; credential riêng vẫn phải được quản lý đúng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Ask every user to recreate servers manually**: Tái tạo thủ công dễ lệch giữa thành viên.\n- **Store all servers in personal user configuration**: User config riêng không tự đi cùng repository.\n- **Combine all integrations into one MCP server**: Gộp server không giải quyết scope phân phối config.\n\n**Tham khảo:**\n\n- [Claude Code MCP configuration](https://code.claude.com/docs/en/mcp)", "references": [{"title": "Claude Code MCP configuration", "url": "https://code.claude.com/docs/en/mcp"}]}, {"no": 9, "id": 1127, "type": "single", "select": 1, "question": "A customer support agent alternates unpredictably between `get_customer` and `lookup_order` when handling mixed requests. \n\nThe MCP tool catalog only contains short autogenerated descriptions. \n\nWhat change should you make first to improve tool selection reliability?", "imageMissing": false, "options": [{"key": "A", "text": "Update the system prompt to tell Claude to think carefully before selecting tools."}, {"key": "B", "text": "Add a keyword router that maps phrases like “order” or “refund” to one tool."}, {"key": "C", "text": "Consolidate get_customer and lookup_order into one broad lookup tool."}, {"key": "D", "text": "Rewrite each MCP tool description to specify purpose, accepted identifiers, returned fields, edge cases, and boundaries."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Rewrite each MCP tool description to specify purpose, accepted identifiers, returned fields, edge cases, and boundaries.\n\nMô tả rõ mục đích, identifier, output và ranh giới giúp phân biệt lookup khách với đơn, sửa đúng thiếu thông tin của catalog.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Update the system prompt to tell Claude to think carefully before selecting tools.**: “Think carefully” không bổ sung ý nghĩa khác nhau giữa tool.\n- **Add a keyword router that maps phrases like “order” or “refund” to one tool.**: Keyword router đơn giản dễ sai với mixed requests và identifier.\n- **Consolidate get_customer and lookup_order into one broad lookup tool.**: Gộp tool rộng che mất ranh giới và tăng mơ hồ tham số.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}]}, {"no": 10, "id": 1128, "type": "single", "select": 1, "question": "Your Claude application's content policy specifies categories of content it should not produce under any circumstance. \n\nThe application currently has no mechanism to enforce this policy, and content matching these categories is appearing in the application's output. \n\nHow would you enforce the content policy?", "imageMissing": false, "options": [{"key": "A", "text": "Add deterministic output filtering that checks responses against the content policy before they reach users."}, {"key": "B", "text": "Remove the content policy entirely and let any output reach users during normal operation, accepting whatever content the application produces in response to incoming traffic."}, {"key": "C", "text": "Move enforcement to users by asking them to report content policy violations after the violating content has already reached them in the application's responses."}, {"key": "D", "text": "Enhance the system prompt to contain explicit instructions for the categories to avoid, complete with examples of each category. Treat the strengthened prompt as the primary enforcement mechanism for the application's content policy across all responses."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add deterministic output filtering that checks responses against the content policy before they reach users.\n\nĐặt bộ lọc ở đầu ra ứng dụng để kiểm tra và chặn nội dung vi phạm trước khi gửi. Prompt hỗ trợ hành vi nhưng không thay thế bước chặn; vẫn phải kiểm thử độ bao phủ của bộ lọc.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Enhance the system prompt to contain explicit instructions for the categories to avoid, complete with examples of each category. Treat the strengthened prompt as the primary enforcement mechanism for the application's content policy across all responses.**: Chỉ tăng hướng dẫn trong prompt không đủ để cưỡng chế quy tắc đầu ra.\n- **Remove the content policy entirely and let any output reach users during normal operation, accepting whatever content the application produces in response to incoming traffic.**: Bỏ chính sách là bỏ yêu cầu.\n- **Move enforcement to users by asking them to report content policy violations after the violating content has already reached them in the application's responses.**: Người dùng báo cáo thì nội dung vi phạm đã được gửi đi.\n\n**Tham khảo:**\n\n- [platform.claude.com — mitigate-jailbreaks](%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks%5C%22)", "references": [{"title": "platform.claude.com — mitigate-jailbreaks", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks%5C%22"}]}, {"no": 11, "id": 1129, "type": "single", "select": 1, "question": "A debugging agent investigates unfamiliar systems where the correct solution is unknown at the beginning. \n\nWhich strategy should it use?", "imageMissing": false, "options": [{"key": "A", "text": "Use adaptive planning based on discoveries"}, {"key": "B", "text": "Ignore intermediate findings"}, {"key": "C", "text": "Always restart from the beginning"}, {"key": "D", "text": "Follow a completely fixed workflow"}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use adaptive planning based on discoveries\n\nKế hoạch thích ứng cập nhật theo bằng chứng debug, vì bước tiếp theo chưa biết trước khi tìm nguyên nhân.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Follow a completely fixed workflow**: Workflow hoàn toàn cố định không đáp ứng nhánh điều tra mới.\n- **Ignore intermediate findings**: Bỏ kết quả trung gian khiến điều tra không tích lũy bằng chứng.\n- **Always restart from the beginning**: Luôn bắt đầu lại mất tiến độ và lặp kiểm tra.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}]}, {"no": 12, "id": 1130, "type": "single", "select": 1, "question": "An engineer asks Claude to add a caching layer around a legacy authorization module. \n\nThe system has multiple tenants, audit logging, and inconsistent invalidation behavior. \n\nWhat should happen before modifying files?", "imageMissing": false, "options": [{"key": "A", "text": "Ask targeted questions about invariants, invalidation, audit requirements, and failure modes."}, {"key": "B", "text": "Implement a simple cache wrapper and iterate later."}, {"key": "C", "text": "Provide performance goals and let Claude infer rules."}, {"key": "D", "text": "Copy caching patterns from another module."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Ask targeted questions about invariants, invalidation, audit requirements, and failure modes.\n\nCache authorization phải giữ tenant isolation, audit và invalidation; câu hỏi nhắm làm rõ bất biến trước khi bọc cache có thể cấp quyền sai.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Implement a simple cache wrapper and iterate later.**: Wrapper đơn giản có thể giữ quyền đã bị thu hồi hoặc rò tenant.\n- **Provide performance goals and let Claude infer rules.**: Chỉ performance goal không định nghĩa tính đúng đắn bảo mật.\n- **Copy caching patterns from another module.**: Pattern module khác có thể dùng key/invalidation khác.\n\n**Tham khảo:**\n\n- [Claude Code best practices](https://code.claude.com/docs/en/best-practices)", "references": [{"title": "Claude Code best practices", "url": "https://code.claude.com/docs/en/best-practices"}]}, {"no": 13, "id": 1294, "type": "single", "select": 1, "question": "Your team's Claude agent has accumulated several customizations that bypass the SDK's defaults, including custom history management, retry logic, and error handling. \n\nA new team member has proposed reverting all the customizations to maintain the codebase more easily. \n\nThe tech lead disagrees and says each customization was added for a reason. \n\nHow would you advise the team?", "imageMissing": false, "options": [{"key": "A", "text": "Decide on each customization individually based on its original reason and the SDK's current capabilities."}, {"key": "B", "text": "Revert all customizations to the SDK's defaults to standardize the codebase."}, {"key": "C", "text": "Keep all customizations, trusting that the tech lead's original reasoning is still valid."}, {"key": "D", "text": "Migrate the agent off the SDK and rebuild it with a custom loop."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Decide on each customization individually based on its original reason and the SDK's current capabilities.\n\nĐánh giá từng tùy biến theo vấn đề ban đầu và khả năng SDK hiện tại. Chỉ giữ khi nhu cầu vẫn còn và cơ chế mặc định chưa đáp ứng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Migrate the agent off the SDK and rebuild it with a custom loop.**: Viết lại toàn bộ thêm phức tạp trước khi đánh giá nhu cầu.\n- **Revert all customizations to the SDK's defaults to standardize the codebase.**: Bỏ hết có thể làm mất hành vi cần thiết.\n- **Keep all customizations, trusting that the tech lead's original reasoning is still valid.**: Giữ hết bỏ qua yêu cầu đã đổi và cải tiến của SDK.\n\n**Tham khảo:**\n\n- [code.claude.com — overview](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22)", "references": [{"title": "code.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22"}]}, {"no": 14, "id": 1131, "type": "single", "select": 1, "question": "A developer creates a multi-agent workflow where one agent researches documentation and another writes implementation plans. \n\nHow should information flow between agents be handled?", "imageMissing": false, "options": [{"key": "A", "text": "Assume all agents share the same conversation context"}, {"key": "B", "text": "Pass required findings through the coordinator"}, {"key": "C", "text": "Remove the coordinator role"}, {"key": "D", "text": "Allow each agent to access every previous message"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Pass required findings through the coordinator\n\nCoordinator truyền findings cần thiết một cách có cấu trúc vì subagent thường có context riêng, không mặc nhiên thấy mọi hội thoại.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Assume all agents share the same conversation context**: Giả định chung context dễ mất thông tin chưa được chuyển.\n- **Allow each agent to access every previous message**: Truy cập mọi message không cần thiết và tăng nhiễu/quyền.\n- **Remove the coordinator role**: Bỏ coordinator không tạo hợp đồng trao đổi findings.\n\n**Tham khảo:**\n\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 15, "id": 1132, "type": "single", "select": 1, "question": "A structured extraction system divides documents into sections and sends them to extraction subagents. \n\nOne subagent temporarily loses access to its source system. \n\nThe current implementation either returns an empty successful extraction or aborts the entire document. \n\nWhat should you change?", "imageMissing": false, "options": [{"key": "A", "text": "Retry the failed section until it succeeds before returning anything."}, {"key": "B", "text": "Terminate the entire document workflow whenever any subagent fails."}, {"key": "C", "text": "Return an empty extraction object for the failed section."}, {"key": "D", "text": "Have subagents report unresolved failures with attempted section, failure type, partial fields, and recovery suggestions."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Have subagents report unresolved failures with attempted section, failure type, partial fields, and recovery suggestions.\n\nBáo lỗi có section, loại lỗi, trường đã lấy và gợi ý phục hồi phân biệt thiếu dữ liệu thật với không đọc được nguồn, đồng thời giữ phần thành công.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Return an empty extraction object for the failed section.**: Empty success che giấu mất nguồn như thể không có dữ liệu.\n- **Terminate the entire document workflow whenever any subagent fails.**: Một section lỗi không luôn cần hủy mọi section thành công.\n- **Retry the failed section until it succeeds before returning anything.**: Retry vô hạn không có giới hạn chi phí hay cơ chế trả lỗi.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}, {"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}]}, {"no": 16, "id": 1133, "type": "single", "select": 1, "question": "A multi-agent research system occasionally generates reports while the synthesis agent is still incomplete, resulting in missing or unverifiable citations. \n\nWhat change prevents invalid reports?", "imageMissing": false, "options": [{"key": "A", "text": "Generate reports immediately and remove invalid citations afterward."}, {"key": "B", "text": "Tell the report agent to refuse incomplete synthesis."}, {"key": "C", "text": "Block report-generation tasks until synthesis returns a structured citation manifest and success status."}, {"key": "D", "text": "Check whether synthesis messages contain words like “complete.”"}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Block report-generation tasks until synthesis returns a structured citation manifest and success status.\n\nGate dựa success status và citation manifest chặn chạy report trước khi synthesis hoàn tất, cưỡng chế phụ thuộc bằng state thay vì câu chữ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Generate reports immediately and remove invalid citations afterward.**: Xóa citation sau không phục hồi evidence và có thể đã xuất báo cáo sai.\n- **Tell the report agent to refuse incomplete synthesis.**: Prompt từ chối không bằng kiểm tra điều kiện ở scheduler.\n- **Check whether synthesis messages contain words like “complete.”**: Từ “complete” có thể xuất hiện trong thông điệp chưa hoàn tất.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)\n- [Structured outputs](https://platform.claude.com/docs/en/build-with-claude/structured-outputs)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}, {"title": "Structured outputs", "url": "https://platform.claude.com/docs/en/build-with-claude/structured-outputs"}]}, {"no": 17, "id": 1134, "type": "single", "select": 1, "question": "A migration assistant sometimes starts dependency analysis before collecting required package manager and framework versions. \n\nWhat change most reliably enforces the correct first step?", "imageMissing": false, "options": [{"key": "A", "text": "Detect whether Claude mentions metadata completion in natural language."}, {"key": "B", "text": "Force the metadata extraction tool with tool_choice for the first request."}, {"key": "C", "text": "Set tool_choice to any for the first request."}, {"key": "D", "text": "Strengthen the system prompt requiring metadata extraction first."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Force the metadata extraction tool with tool_choice for the first request.\n\nÉp chọn tool trích metadata bằng tool_choice là cơ chế khóa nguồn muốn nói: trên model hỗ trợ, chỉ định tên tool ràng buộc lựa chọn đầu tiên trực tiếp hơn prompt. Nhưng điều này có điều kiện: tài liệu hiện hành liệt kê model và cấu hình thinking từ chối ép tool. Cần kiểm tra model thực tế và chặn phân tích phụ thuộc trong điều phối cho đến khi đủ metadata.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Detect whether Claude mentions metadata completion in natural language.**: Nhắc đã xong bằng ngôn ngữ tự nhiên không chứng minh đã đủ metadata.\n- **Set tool_choice to any for the first request.**: Chọn any buộc gọi một tool khi được hỗ trợ, nhưng không chỉ định tool metadata.\n- **Strengthen the system prompt requiring metadata extraction first.**: Prompt mạnh hơn nêu thứ tự nhưng không cưỡng chế điều kiện trước trực tiếp như chốt điều phối có kiểm tra.\n\n**Cần xem lại:** Đề thiếu model và cấu hình thinking. Ép tool_choice không được hỗ trợ trên một số model/cấu hình hiện tại, nên khóa nguồn không đúng vô điều kiện. Giữ nguyên khóa và cần nêu môi trường hỗ trợ hoặc viết lại theo chốt metadata xác định.\n\n**Tham khảo:**\n\n- [Define tools and control tool choice](%5C%22https%3A//platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools%5C%22)", "references": [{"title": "Define tools and control tool choice", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools%5C%22"}]}, {"no": 18, "id": 1135, "type": "single", "select": 1, "question": "A team wants Claude-generated pull request reviews to integrate with existing development systems. \n\nWhat output approach should be selected?", "imageMissing": false, "options": [{"key": "A", "text": "Long markdown explanations only"}, {"key": "B", "text": "Free-form text responses"}, {"key": "C", "text": "Structured JSON with validation rules"}, {"key": "D", "text": "Unformatted comments"}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Structured JSON with validation rules\n\nJSON có validation rules tạo hợp đồng máy đọc được để tích hợp findings mà không suy cấu trúc từ văn bản.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Free-form text responses**: Free-form text thay field/bố cục khó parse ổn định.\n- **Long markdown explanations only**: Markdown dài ưu tiên đọc thủ công, không schema dữ liệu.\n- **Unformatted comments**: Comment không format không ràng buộc kiểu hay field bắt buộc.\n\n**Tham khảo:**\n\n- [Structured outputs](https://platform.claude.com/docs/en/build-with-claude/structured-outputs)", "references": [{"title": "Structured outputs", "url": "https://platform.claude.com/docs/en/build-with-claude/structured-outputs"}]}, {"no": 19, "id": 1136, "type": "single", "select": 1, "question": "A new Claude model release includes performance improvements for several reasoning tasks but has changed the format of its responses to system prompts that use multi-section instructions. \n\nYour application uses multi-section system prompts heavily. \n\nInitial evaluation on the application's actual workload shows the new model performs 8 percent better on reasoning tasks but produces malformed output on roughly 3 percent of requests because of the format change. \n\nThe team is debating whether to upgrade. \n\nHow would you decide?", "imageMissing": false, "options": [{"key": "A", "text": "Upgrade and add a downstream validation step that catches the 3 percent malformed output before it reaches users, treating the validation step as the team's mitigation for the format change."}, {"key": "B", "text": "Adapt the application's system prompt to the new model's format expectations and re-evaluate, then upgrade only if the adapted prompt eliminates the malformed output while preserving the reasoning improvements."}, {"key": "C", "text": "Upgrade immediately, because the 8 percent reasoning improvement outweighs the 3 percent malformed output rate across the application's typical request distribution."}, {"key": "D", "text": "Stay on the previous model permanently to avoid the malformed output rate and any future format changes that subsequent model releases might introduce in the application."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Adapt the application's system prompt to the new model's format expectations and re-evaluate, then upgrade only if the adapted prompt eliminates the malformed output while preserving the reasoning improvements.\n\nPhải xử lý lỗi định dạng trong lần nâng cấp: sửa prompt, chạy lại tập đánh giá đại diện và kiểm tra đồng thời tính hợp lệ lẫn chất lượng suy luận.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Upgrade and add a downstream validation step that catches the 3 percent malformed output before it reaches users, treating the validation step as the team's mitigation for the format change.**: Chỉ chặn đầu ra chưa sửa sự không tương thích giữa model và prompt.\n- **Stay on the previous model permanently to avoid the malformed output rate and any future format changes that subsequent model releases might introduce in the application.**: Giữ model cũ mãi bỏ qua cải tiến mà không đánh giá.\n- **Upgrade immediately, because the 8 percent reasoning improvement outweighs the 3 percent malformed output rate across the application's typical request distribution.**: Suy luận tốt hơn không làm dữ liệu sai định dạng trở nên hợp lệ.\n\n**Tham khảo:**\n\n- [platform.claude.com — develop-tests](%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22)", "references": [{"title": "platform.claude.com — develop-tests", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22"}]}, {"no": 20, "id": 1137, "type": "single", "select": 1, "question": "A developer wants Claude to return API responses that can be directly consumed by another application. \n\nWhich technique should be used?", "imageMissing": false, "options": [{"key": "A", "text": "Ask Claude for longer explanations"}, {"key": "B", "text": "Request formatted paragraphs"}, {"key": "C", "text": "Allow unrestricted responses"}, {"key": "D", "text": "Use structured output with defined fieldscorrect"}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use structured output with defined fieldscorrect\n\nDùng structured output có các trường xác định: ứng dụng khác cần tên, kiểu và giá trị bắt buộc dự đoán được thay vì đoạn văn theo phong cách. Phản hồi ràng buộc schema và kiểm tra ở điểm tiếp nhận làm giao diện đáng tin cậy. Nội dung được chọn trong nguồn có lỗi chép cần duyệt, không tự sửa lựa chọn.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Request formatted paragraphs**: Đoạn văn được định dạng cải thiện trình bày nhưng chưa xác lập trường và kiểu cho máy.\n- **Ask Claude for longer explanations**: Giải thích dài hơn thêm văn bản thay vì hợp đồng dữ liệu.\n- **Allow unrestricted responses**: Phản hồi không giới hạn cho phép dạng mà ứng dụng nhận không hiểu.\n\n**Cần xem lại:** Lựa chọn được chọn chứa từ lỗi fieldscorrect. Có thể nhận ra ý structured output, nhưng cần đối chiếu bản gốc và sửa lựa chọn bằng thay đổi biên tập rõ ràng.\n\n**Tham khảo:**\n\n- [Structured outputs](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/structured-outputs%5C%22)", "references": [{"title": "Structured outputs", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/structured-outputs%5C%22"}]}, {"no": 21, "id": 1301, "type": "single", "select": 1, "question": "A teammate is debugging a Claude application whose system prompt has grown to several hundred lines and now contains overlapping, contradictory, and obsolete instructions. \n\nHow would you advise the teammate?", "imageMissing": false, "options": [{"key": "A", "text": "Split the prompt across multiple system prompts so the model sees a smaller portion at any given time."}, {"key": "B", "text": "Audit the prompt for overlap, contradiction, and obsolete content, then refactor so each instruction is clear, current, and non-redundant."}, {"key": "C", "text": "Add more explicit instructions so the most recent rules dominate the model's interpretation of the prompt during each request."}, {"key": "D", "text": "Tighten only the contradictory rules first, treating the overlap and obsolete content as lower-priority work the team can address later."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Audit the prompt for overlap, contradiction, and obsolete content, then refactor so each instruction is clear, current, and non-redundant.\n\nRà toàn bộ hướng dẫn, bỏ quy tắc cũ và quy tắc xung đột. Một đặc tả nhất quán dễ thực hiện và đánh giá hơn danh sách ngoại lệ chồng chất.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Add more explicit instructions so the most recent rules dominate the model's interpretation of the prompt during each request.**: Thêm hướng dẫn có thể làm mâu thuẫn chồng thêm.\n- **Tighten only the contradictory rules first, treating the overlap and obsolete content as lower-priority work the team can address later.**: Chỉ sửa xung đột vẫn để nguyên các nguyên nhân đã nêu khác.\n- **Split the prompt across multiple system prompts so the model sees a smaller portion at any given time.**: Chia nội dung mâu thuẫn sang nhiều message không giải quyết mâu thuẫn.\n\n**Tham khảo:**\n\n- [platform.claude.com — claude-prompting-best-practices](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices%5C%22)", "references": [{"title": "platform.claude.com — claude-prompting-best-practices", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices%5C%22"}]}, {"no": 22, "id": 1138, "type": "single", "select": 1, "question": "Multiple backend problems are returned to an agent as the same message: “Operation failed.” \n\nProblems include invalid order IDs, temporary service timeouts, expired tokens, and policy restrictions. \n\nWhat change most improves recovery behavior?", "imageMissing": false, "options": [{"key": "A", "text": "Retry every failed tool call twice before escalation."}, {"key": "B", "text": "Map failures to customer sentiment levels."}, {"key": "C", "text": "Return structured MCP errors with categories, retryability, and user-safe details."}, {"key": "D", "text": "Keep generic failures and let Claude infer retryability."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Return structured MCP errors with categories, retryability, and user-safe details.\n\nError có category, retryability và chi tiết an toàn giúp phân biệt ID sai, token hết hạn, timeout và policy block để chọn phục hồi đúng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Retry every failed tool call twice before escalation.**: Retry mọi lỗi hai lần lãng phí với ID sai hoặc policy từ chối.\n- **Keep generic failures and let Claude infer retryability.**: Thông điệp chung không cung cấp căn cứ quyết định retry.\n- **Map failures to customer sentiment levels.**: Sentiment không mô tả nguyên nhân kỹ thuật hoặc khả năng retry.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}]}, {"no": 23, "id": 1139, "type": "single", "select": 1, "question": "**Scenario**: \n\nMulti-Agent Research System You are building a multi-agent research system using the Claude Agent SDK. \n\nA coordinator agent delegates to specialized subagents: one searches the web, one analyzes documents, one synthesizes findings, and one generates reports. \n\nYour coordinator's document-analysis subagent depends on an internal library-catalog MCP server. \n\nIt works in your local Claude Code session, but two teammates who cloned the repository cannot access the catalog tools, so their runs fall back to weaker web searches. \n\nSeparately, one researcher is testing an experimental notes server that should not affect the team. \n\nWhat should you change?", "imageMissing": false, "options": [{"key": "A", "text": "Place both servers in each user's ~/.claude.json, and rely on onboarding scripts to synchronize changes across machines."}, {"key": "B", "text": "Move the required catalog server into project-scoped .mcp.json, and keep the experimental notes server in user-scoped ~/.claude.json."}, {"key": "C", "text": "Combine the catalog and notes integrations into one MCP server, and expose only role-specific tools to subagents."}, {"key": "D", "text": "Document per-user claude mcp add commands in README, and ask each researcher to recreate both servers locally."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Move the required catalog server into project-scoped .mcp.json, and keep the experimental notes server in user-scoped ~/.claude.json.\n\nCatalog bắt buộc ở .mcp.json project đi cùng repo, còn server ghi chú thử nghiệm ở user scope không ảnh hưởng cả nhóm.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Document per-user claude mcp add commands in README, and ask each researcher to recreate both servers locally.**: Hướng dẫn thủ công cho cả hai server vẫn dễ thiếu config và phát tán thử nghiệm.\n- **Place both servers in each user's ~/.claude.json, and rely on onboarding scripts to synchronize changes across machines.**: Đồng bộ user config trộn tùy chọn cá nhân với phụ thuộc project.\n- **Combine the catalog and notes integrations into one MCP server, and expose only role-specific tools to subagents.**: Gộp server không giải quyết phân phối scope và cô lập thử nghiệm.\n\n**Tham khảo:**\n\n- [Claude Code MCP configuration](https://code.claude.com/docs/en/mcp)", "references": [{"title": "Claude Code MCP configuration", "url": "https://code.claude.com/docs/en/mcp"}]}, {"no": 24, "id": 1140, "type": "single", "select": 1, "question": "**Scenario**: \n\nDeveloper Productivity with Claude A Claude-powered helper updates legacy configuration files to a new format. \n\nInitial generations look reasonable, but repeated runs keep breaking different corner cases: l Missing optional sections l Duplicate keys l Large files with thousands of entries Developers have been sending prompts like \"fix the migration bugs\" and receiving inconsistent improvements. \n\nWhat refinement approach should they use next?", "imageMissing": false, "options": [{"key": "A", "text": "Ask Claude to reread the entire legacy codebase and rewrite the migration helper from scratch after each failed run."}, {"key": "B", "text": "Remove the most difficult corner-case checks temporarily so Claude can stabilize the happy-path migration behavior first."}, {"key": "C", "text": "Tell Claude the output is still wrong, request a more careful implementation, and continue until reviewers approve it."}, {"key": "D", "text": "Share the failing test names, inputs, expected versus actual outputs, and stack traces, then iterate on minimal fixes."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Share the failing test names, inputs, expected versus actual outputs, and stack traces, then iterate on minimal fixes.\n\nInput lỗi, expected/actual và stack trace giúp tái hiện chính xác regression rồi sửa nhỏ; “fix bugs” chung không chỉ rõ điều kiện hỏng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Ask Claude to reread the entire legacy codebase and rewrite the migration helper from scratch after each failed run.**: Viết lại mọi lần tăng phạm vi hồi quy và bỏ nguyên nhân cụ thể.\n- **Remove the most difficult corner-case checks temporarily so Claude can stabilize the happy-path migration behavior first.**: Bỏ edge checks chỉ giấu lỗi đang cần xử lý.\n- **Tell Claude the output is still wrong, request a more careful implementation, and continue until reviewers approve it.**: “Careful” không thay evidence tái hiện.\n\n**Tham khảo:**\n\n- [Claude Code best practices](https://code.claude.com/docs/en/best-practices)", "references": [{"title": "Claude Code best practices", "url": "https://code.claude.com/docs/en/best-practices"}]}, {"no": 25, "id": 1141, "type": "single", "select": 1, "question": "Supplier contract extraction returns null values for effective dates and renewal terms even though information exists in cover letters, footnotes, and table captions. \n\nWhat change most improves accuracy?", "imageMissing": false, "options": [{"key": "A", "text": "Retry until all metadata fields contain values."}, {"key": "B", "text": "Add targeted few-shot examples showing extraction from varied document sections."}, {"key": "C", "text": "Tell Claude null values are unacceptable for supplier contracts."}, {"key": "D", "text": "Make fields required and non-null."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add targeted few-shot examples showing extraction from varied document sections.\n\nVí dụ lấy thông tin từ cover letter, footnote và caption dạy pattern vị trí khác nhau, giải quyết việc extractor chỉ chú ý phần chính.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Retry until all metadata fields contain values.**: Retry không đổi hướng chú ý và có thể lặp thiếu dữ liệu.\n- **Make fields required and non-null.**: Non-null bắt buộc có thể ép đoán thay vì tìm đúng nguồn.\n- **Tell Claude null values are unacceptable for supplier contracts.**: Cấm null không chỉ vị trí cần đọc và tăng nguy cơ bịa.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}]}, {"no": 26, "id": 1142, "type": "single", "select": 1, "question": "A legacy subscription service has cancellation behavior distributed across command-line scripts, web handlers, and scheduled jobs. \n\nPrevious direct edits often targeted the wrong abstraction. \n\nWhich workflow should be recommended first?", "imageMissing": false, "options": [{"key": "A", "text": "Start separate direct sessions for each module and combine changes later."}, {"key": "B", "text": "Use plan mode to map relevant flows and compare implementation points before modifications."}, {"key": "C", "text": "Directly edit and rely on test failures to guide corrections."}, {"key": "D", "text": "Read every repository file before implementing changes."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use plan mode to map relevant flows and compare implementation points before modifications.\n\nPlan mode khoanh flow cancellation qua script, web và job, so sánh điểm sửa trước khi thay đổi nhầm tầng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Read every repository file before implementing changes.**: Đọc mọi file không cần thiết khi có thể tìm flow liên quan.\n- **Directly edit and rely on test failures to guide corrections.**: Sửa trước rồi chờ test không thay phân tích ownership.\n- **Start separate direct sessions for each module and combine changes later.**: Các session rời có thể bỏ liên kết hành vi giữa module.\n\n**Tham khảo:**\n\n- [Claude Code best practices](https://code.claude.com/docs/en/best-practices)", "references": [{"title": "Claude Code best practices", "url": "https://code.claude.com/docs/en/best-practices"}]}, {"no": 27, "id": 1143, "type": "single", "select": 1, "question": "A team builds an application where Claude must classify customer requests into predefined categories. \n\nWhich approach provides the most consistent results?", "imageMissing": false, "options": [{"key": "A", "text": "Remove category definitions from the prompt"}, {"key": "B", "text": "Ask Claude to create new categories when needed"}, {"key": "C", "text": "Provide examples of each category and expected classifications"}, {"key": "D", "text": "Use a random classification approach."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Provide examples of each category and expected classifications\n\nVí dụ từng category cùng expected label làm rõ ranh giới phân loại, nhất là trường hợp dễ nhầm.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Ask Claude to create new categories when needed**: Tự thêm category phá tập nhãn downstream đã quy định.\n- **Use a random classification approach.**: Ngẫu nhiên không giữ nhất quán cùng input.\n- **Remove category definitions from the prompt**: Bỏ định nghĩa category làm mất ranh giới quyết định.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}]}, {"no": 28, "id": 1144, "type": "single", "select": 1, "question": "**Scenario**: \n\nCustomer Support Resolution Agent You are building a customer support resolution agent using the Claude Agent SDK. \n\nThe agent handles high- ambiguity requests like returns, billing disputes, and account issues. \n\nIt has access to backend systems through MCP tools (get_customer, lookup_order, process_refund, escalate_to_human). \n\nYour target is 80%+ first-contact resolution while knowing when to escalate. \n\nDuring billing disputes, the agent creates condensed case notes before responding or escalating. \n\nHuman reviewers report that notes sometimes say things like \"refund approved\" or \"customer was promised free return shipping,\" but they cannot tell whether each claim came from the customer, an order record, a policy document, or the agent's inference. In several escalations, customer allegations were treated as verified backend facts. \n\nWhat change would most effectively reduce this reliability risk?", "imageMissing": false, "options": [{"key": "A", "text": "Require summaries and handoffs to carry structured claim-source mappings with source type, excerpt or tool field, timestamp, and verification status."}, {"key": "B", "text": "Store complete raw transcripts and tool outputs only, relying on human reviewers to reconstruct sources when disputes arise."}, {"key": "C", "text": "Ask the agent to include only high-confidence claims in final responses, omitting uncertain details from summaries and escalations."}, {"key": "D", "text": "Compress each case into a shorter narrative summary and instruct reviewers to ask follow-up questions when provenance seems unclear."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Require summaries and handoffs to carry structured claim-source mappings with source type, excerpt or tool field, timestamp, and verification status.\n\nClaim-source mapping giữ phân biệt lời khách, field backend, policy và suy luận, kèm thời gian và verification để không biến cáo buộc thành sự kiện đã xác minh.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Compress each case into a shorter narrative summary and instruct reviewers to ask follow-up questions when provenance seems unclear.**: Summary ngắn hơn có thể làm mất provenance thêm.\n- **Store complete raw transcripts and tool outputs only, relying on human reviewers to reconstruct sources when disputes arise.**: Chỉ raw transcript bắt người review tái dựng mọi quan hệ nguồn.\n- **Ask the agent to include only high-confidence claims in final responses, omitting uncertain details from summaries and escalations.**: Confidence cao không chứng minh nguồn hay trạng thái xác minh.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 29, "id": 1145, "type": "single", "select": 1, "question": "A research system creates coherent reports, but coverage gaps remain. \n\nFor example, AI regulation reports have strong EU coverage but weak Asia-Pacific coverage. \n\nWhat change improves completeness?", "imageMissing": false, "options": [{"key": "A", "text": "Increase coordinator iteration count to a fixed number."}, {"key": "B", "text": "Add a coordinator review loop that checks coverage, delegates follow-ups, and reruns synthesis."}, {"key": "C", "text": "Repeat broad assignments twice."}, {"key": "D", "text": "Hide unsupported sections."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add a coordinator review loop that checks coverage, delegates follow-ups, and reruns synthesis.\n\nCoordinator kiểm tra coverage theo vùng, giao nghiên cứu bổ sung rồi synthesis lại để lấp khoảng trống APAC có mục tiêu.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Repeat broad assignments twice.**: Lặp assignment rộng có thể lặp chính thiên lệch EU.\n- **Hide unsupported sections.**: Ẩn section thiếu làm báo cáo trông đủ nhưng mất yêu cầu.\n- **Increase coordinator iteration count to a fixed number.**: Số vòng cố định không kiểm tra coverage thực.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}, {"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 30, "id": 1146, "type": "single", "select": 1, "question": "A developer wants Claude to review code and return only actionable issues. \n\nWhat prompt design is most effective?", "imageMissing": false, "options": [{"key": "A", "text": "Request every possible improvement"}, {"key": "B", "text": "Avoid describing expected output"}, {"key": "C", "text": "Ask for unlimited suggestions"}, {"key": "D", "text": "Define what qualifies as an issue and provide examples."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Define what qualifies as an issue and provide examples.\n\nĐịnh nghĩa issue và ví dụ actionable giúp tách bug có tác động khỏi sở thích chỉnh style, giảm findings không cần hành động.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Request every possible improvement**: Mọi cải tiến mở rộng phạm vi sang nhiều gợi ý không cần thiết.\n- **Ask for unlimited suggestions**: Unlimited suggestions khuyến khích số lượng thay chất lượng.\n- **Avoid describing expected output**: Thiếu output expectation khiến findings khó dùng nhất quán.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}]}, {"no": 31, "id": 1147, "type": "single", "select": 1, "question": "**Scenario**: \n\nCustomer Support Resolution Agent Production logs show: l get_customer returns ISO 8601 timestamps and numeric loyalty tiers. l lookup_order returns Unix timestamps and numeric status codes. \n\nThe agent sometimes miscomputes return windows or mislabels order status. \n\nYou cannot modify upstream MCP servers. \n\nWhat change best addresses the reliability issue?", "imageMissing": false, "options": [{"key": "A", "text": "Modify the final customer response parser."}, {"key": "B", "text": "Add a PostToolUse hook that converts tool results into canonical dates, status labels, and tier fields before Claude sees it."}, {"key": "C", "text": "Escalate all cases with mixed timestamp formats."}, {"key": "D", "text": "Add system instructions telling Claude to remember each tool's format"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add a PostToolUse hook that converts tool results into canonical dates, status labels, and tier fields before Claude sees it.\n\nPostToolUse có thể chuẩn hóa kết quả MCP trước model qua cơ chế output được hỗ trợ, giúp so thời gian và status theo một schema. Không chỉ format câu trả lời cuối.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Escalate all cases with mixed timestamp formats.**: Escalate mọi mixed format lãng phí khi adapter xử lý được.\n- **Add system instructions telling Claude to remember each tool's format**: Yêu cầu nhớ format vẫn để model tự đổi dữ liệu dễ sai.\n- **Modify the final customer response parser.**: Parser cuối quá muộn vì tính cửa sổ hoàn trả đã dùng sai dữ liệu.\n\n**Tham khảo:**\n\n- [Claude Code hooks reference](https://code.claude.com/docs/en/hooks)", "references": [{"title": "Claude Code hooks reference", "url": "https://code.claude.com/docs/en/hooks"}]}, {"no": 32, "id": 1148, "type": "single", "select": 1, "question": "A multi-agent research system assigns high confidence to most report claims, but customer audits find citation mismatches concentrated in regulatory topics and newly added source types. \n\nWhat review strategy should be implemented before further reducing reviewer coverage?", "imageMissing": false, "options": [{"key": "A", "text": "Randomly sample high-confidence claims across topic, source type, and report section, then track errors by category."}, {"key": "B", "text": "Auto-publish high-confidence reports and investigate only customer defects."}, {"key": "C", "text": "Review only claims with low confidence scores."}, {"key": "D", "text": "Use one aggregate accuracy metric and reduce review after reaching the target."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Randomly sample high-confidence claims across topic, source type, and report section, then track errors by category.\n\nSample ngẫu nhiên có phân tầng trong nhóm confidence cao đo calibration và lộ lỗi theo chủ đề/nguồn, tránh chỉ review nơi model tự nhận yếu.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Review only claims with low confidence scores.**: Chỉ low confidence bỏ lỗi tự tin cao mà audit đang phát hiện.\n- **Use one aggregate accuracy metric and reduce review after reaching the target.**: Accuracy chung che nhóm regulatory hay nguồn mới có lỗi.\n- **Auto-publish high-confidence reports and investigate only customer defects.**: Đợi khách báo lỗi đẩy kiểm chứng sang hậu xuất bản.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 33, "id": 1149, "type": "single", "select": 1, "question": "**Scenario**: \n\nStructured Data Extraction A labeled validation run reports: l 97.2% aggregate extraction accuracy l coverage across NDAs, invoices, insurance forms, and purchase orders Leadership wants to bypass human review for any record where Claude returns high confidence, but pilot complaints suggest errors cluster in specific document families and fields. \n\nWhat should you do before reducing reviewer coverage?", "imageMissing": false, "options": [{"key": "A", "text": "Use the 97.2% aggregate accuracy to auto-approve all high-confidence outputs, monitoring user complaints for emerging regressions."}, {"key": "B", "text": "Randomly review a fixed percentage of every extraction category, regardless of document type, field, or prior validation performance."}, {"key": "C", "text": "Raise the global confidence threshold until the aggregate validation accuracy reaches 99%, then disable review for remaining outputs."}, {"key": "D", "text": "Analyze accuracy by document type and extracted field, then automate only segments meeting validated thresholds while routing others to review."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Analyze accuracy by document type and extracted field, then automate only segments meeting validated thresholds while routing others to review.\n\nPhân tích theo loại tài liệu và field phát hiện nhóm yếu bị accuracy chung che; chỉ tự động hóa phân đoạn đã đạt ngưỡng kiểm chứng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Randomly review a fixed percentage of every extraction category, regardless of document type, field, or prior validation performance.**: Tỷ lệ review giống nhau không ưu tiên vùng lỗi cao.\n- **Raise the global confidence threshold until the aggregate validation accuracy reaches 99%, then disable review for remaining outputs.**: Threshold confidence chung không bảo đảm calibration từng nhóm.\n- **Use the 97.2% aggregate accuracy to auto-approve all high-confidence outputs, monitoring user complaints for emerging regressions.**: 97,2% chung không chứng minh record confidence cao luôn đúng.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 34, "id": 1150, "type": "single", "select": 1, "question": "**Scenario**: \n\nStructured Data Extraction You are building a structured data extraction system using Claude. \n\nThe system extracts information from unstructured documents, validates output using JSON schemas, and maintains high accuracy. \n\nIt must handle edge cases gracefully and integrate with downstream systems. \n\nYour QA prompt reviews a 90-page vendor onboarding packet and its extracted records in one call. \n\nIt catches detailed field errors in the first few forms, but misses mismatched tax IDs in middle attachments and contradicts itself about required signatures. \n\nWhich review architecture would best improve reliability?", "imageMissing": false, "options": [{"key": "A", "text": "Run three full-packet reviews and accept only issues reported by at least two reviewers."}, {"key": "B", "text": "Increase max_tokens and add stronger instructions to be exhaustive while reviewing the entire packet once."}, {"key": "C", "text": "Ask the same extraction instance to critique its own output using extended thinking before returning final records."}, {"key": "D", "text": "Run focused review passes on each packet section, then run a separate consistency pass across cross- section fields."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Run focused review passes on each packet section, then run a separate consistency pass across cross- section fields.\n\nReview từng phần giảm tải chú ý; lượt consistency riêng kiểm tra tax ID và chữ ký xuyên phần, giữ cả chi tiết lẫn quan hệ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Run three full-packet reviews and accept only issues reported by at least two reviewers.**: Ba lượt toàn bộ vẫn có thể cùng bỏ sót vùng giữa.\n- **Ask the same extraction instance to critique its own output using extended thinking before returning final records.**: Self-critique cùng instance có thể lặp giả định sai của extraction.\n- **Increase max_tokens and add stronger instructions to be exhaustive while reviewing the entire packet once.**: max_tokens tăng độ dài output, không tự sửa kiến trúc review quá rộng.\n\n**Tham khảo:**\n\n- [Effective context engineering](https://www.anthropic.com/research/effective-context-engineering-for-ai-agents)\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Effective context engineering", "url": "https://www.anthropic.com/research/effective-context-engineering-for-ai-agents"}, {"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 35, "id": 1151, "type": "single", "select": 1, "question": "**Scenario**: \n\nStructured Data Extraction You are building a structured data extraction system using Claude. \n\nThe system extracts information from unstructured documents, validates output using JSON schemas, and maintains high accuracy. \n\nProduction review shows inconsistent routing: \n\n- documents with unreadable required values and unfamiliar layouts sometimes flow into downstream systems, \n- while routine invoices missing optional purchase-order numbers are sent for manual review. \n\nThe extraction schema already permits nullable fields for data that is absent from the source. \n\nWhat change would most effectively improve routing decisions?", "imageMissing": false, "options": [{"key": "A", "text": "Escalate documents based on frustrated wording, urgent language, or negative sentiment detected in the source text."}, {"key": "B", "text": "Route documents to reviewers whenever the model reports confidence below a single global threshold after extraction."}, {"key": "C", "text": "Add explicit human-review criteria with few-shot examples distinguishing absent optional fields, unreadable required fields, and unsupported document types."}, {"key": "D", "text": "Require retries until all schema fields are populated, then escalate only documents still containing null values"}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add explicit human-review criteria with few-shot examples distinguishing absent optional fields, unreadable required fields, and unsupported document types.\n\nTiêu chí review và ví dụ phân biệt optional absent, required unreadable và loại lạ giúp routing theo ý nghĩa lỗi, không chỉ null hoặc confidence.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Require retries until all schema fields are populated, then escalate only documents still containing null values**: Lấp mọi field có thể ép bịa giá trị optional không có.\n- **Escalate documents based on frustrated wording, urgent language, or negative sentiment detected in the source text.**: Sentiment không quyết định dữ liệu có đọc được và đủ bắt buộc.\n- **Route documents to reviewers whenever the model reports confidence below a single global threshold after extraction.**: Một threshold chung không biểu diễn rủi ro khác nhau của field và loại tài liệu.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}, {"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 36, "id": 1315, "type": "single", "select": 1, "question": "A team wants to build a production billing pipeline's core logic entirely around a platform capability currently labeled Beta in Anthropic's feature-availability table. \n\nA tech lead raises a concern before approving the design. \n\nWhat is the most accurate basis for that concern?", "imageMissing": false, "options": [{"key": "A", "text": "Beta features cannot be used together with prompt caching or batch processing, which would prevent the pipeline from scaling cost-effectively."}, {"key": "B", "text": "Beta features are capped at 200k tokens of context regardless of the underlying model, which would limit the pipeline's document processing."}, {"key": "C", "text": "Beta features are billed at a 50% premium compared to generally available features, making them unsuitable for cost-sensitive billing pipelines."}, {"key": "D", "text": "Beta features may change significantly or be discontinued based on feedback and are not guaranteed for ongoing production use, unlike GA features."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Beta features may change significantly or be discontinued based on feedback and are not guaranteed for ongoing production use, unlike GA features.\n\nTính năng beta có vòng đời kém ổn định hơn tính năng GA. Cần đánh giá rủi ro thay đổi hoặc ngừng cung cấp trước khi dùng làm nền tảng duy nhất của quy trình quan trọng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Beta features are billed at a 50% premium compared to generally available features, making them unsuitable for cost-sensitive billing pipelines.**: Không có quy tắc chung mọi beta đều cộng giá 50%.\n- **Beta features cannot be used together with prompt caching or batch processing, which would prevent the pipeline from scaling cost-effectively.**: Nhãn beta không mặc nhiên cấm cache hoặc batch.\n- **Beta features are capped at 200k tokens of context regardless of the underlying model, which would limit the pipeline's document processing.**: Nhãn beta không áp trần context 200k cho mọi tính năng.\n\n**Tham khảo:**\n\n- [platform.claude.com — overview](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/overview%5C%22)", "references": [{"title": "platform.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/overview%5C%22"}]}, {"no": 37, "id": 1152, "type": "single", "select": 1, "question": "A development team uses Claude Agent SDK for different workflows. \n\nDependency reviews follow fixed rules, while debugging unknown systems requires exploration. \n\nWhich decomposition strategy is best?", "imageMissing": false, "options": [{"key": "A", "text": "Use dynamic planning for every workflow"}, {"key": "B", "text": "Use one large prompt for all tasks"}, {"key": "C", "text": "Use prompt chains for stable tasks and adaptive planning for investigations"}, {"key": "D", "text": "Use fixed steps for every workflow"}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use prompt chains for stable tasks and adaptive planning for investigations\n\nPrompt chain cho checklist ổn định, planning thích ứng cho điều tra chưa biết đường đi; chọn theo mức bất định tác vụ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Use fixed steps for every workflow**: Fixed steps cho mọi việc làm điều tra lãng phí hoặc bỏ nhánh mới.\n- **Use dynamic planning for every workflow**: Dynamic cho mọi việc làm rubric ổn định bị trôi không cần thiết.\n- **Use one large prompt for all tasks**: Prompt lớn không tách điều kiện kiểm tra và phụ thuộc từng bước.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}]}, {"no": 38, "id": 1153, "type": "single", "select": 1, "question": "A development team uses Claude Agent SDK with multiple subagents to analyze a legacy payment system. \n\nHow should the coordinator improve reliability when passing discovery results to a planning subagent?", "imageMissing": false, "options": [{"key": "A", "text": "Maintain shared state and include relevant findings in later prompts"}, {"key": "B", "text": "Allow subagents to communicate directly without coordination"}, {"key": "C", "text": "Ask the planner to infer missing dependencies from file names"}, {"key": "D", "text": "Replace specialized subagents with one general-purpose subagent"}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Maintain shared state and include relevant findings in later prompts\n\nShared state có findings liên quan được đưa rõ vào prompt planner giữ bằng chứng discovery giữa context riêng của subagent.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Replace specialized subagents with one general-purpose subagent**: Một generalist không tự giải quyết mất thông tin handoff.\n- **Ask the planner to infer missing dependencies from file names**: Tên file không đủ chứng minh dependency thực.\n- **Allow subagents to communicate directly without coordination**: Trao đổi không điều phối có thể thiếu phiên bản và nguồn findings thống nhất.\n\n**Tham khảo:**\n\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 39, "id": 1154, "type": "single", "select": 1, "question": "**Scenario**: \n\nDeveloper Productivity with Claude You are building developer productivity tools using the Claude Agent SDK. \n\nThe agent helps engineers explore unfamiliar codebases, understand legacy systems, generate boilerplate code, and automate repetitive tasks. \n\nDependency license reviews follow a stable rubric with known checks, while production bug investigations in unfamiliar services vary based on discovered call paths, logs, and failing tests. \n\nThe current single-pass prompt misses checklist items during reviews and wastes effort during investigations. \n\nWhich decomposition strategy is most appropriate?", "imageMissing": false, "options": [{"key": "A", "text": "Use the same fixed sequential checklist for both workflows, requiring every investigation to complete every predefined step."}, {"key": "B", "text": "Use a fixed prompt chain for stable review rubrics, and let the agent adapt subtasks during open-ended investigations."}, {"key": "C", "text": "Use one large prompt for both request types, asking the agent to reason carefully before using any tools."}, {"key": "D", "text": "Use dynamic task planning for every workflow, allowing the agent to redefine review criteria as it discovers code patterns."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use a fixed prompt chain for stable review rubrics, and let the agent adapt subtasks during open-ended investigations.\n\nReview license cần fixed chain theo rubric, còn bug cần điều chỉnh bước theo logs/call path/test; decomposition theo bản chất tác vụ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Use the same fixed sequential checklist for both workflows, requiring every investigation to complete every predefined step.**: Checklist cứng cho mọi bug có thể làm bước không liên quan.\n- **Use dynamic task planning for every workflow, allowing the agent to redefine review criteria as it discovers code patterns.**: Cho tự đổi review criteria làm mất chuẩn license chung.\n- **Use one large prompt for both request types, asking the agent to reason carefully before using any tools.**: Reason carefully trong prompt lớn không tạo gate checklist hay planning thích ứng.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}]}, {"no": 40, "id": 1155, "type": "single", "select": 1, "question": "A CI pipeline needs Claude Code findings to create automated pull request comments. \n\nWhich approach provides the most reliable integration?", "imageMissing": false, "options": [{"key": "A", "text": "Rewrite previous comments into structured records"}, {"key": "B", "text": "Parse markdown output with regular expressions"}, {"key": "C", "text": "Use JSON output with JSON schema validation"}, {"key": "D", "text": "Ask Claude to always return JSON in the prompt"}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use JSON output with JSON schema validation\n\nJSON schema validation giữ finding theo cấu trúc CI dự kiến trước khi tạo comment, giảm lỗi parsing.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Parse markdown output with regular expressions**: Regex Markdown phụ thuộc bố cục văn bản dễ đổi.\n- **Ask Claude to always return JSON in the prompt**: Prompt JSON-only không cưỡng chế đủ field/type như schema.\n- **Rewrite previous comments into structured records**: Chuyển comment cũ không bảo đảm findings mới đúng contract.\n\n**Tham khảo:**\n\n- [Claude Code CLI reference](https://code.claude.com/docs/en/cli-reference)\n- [Structured outputs](https://platform.claude.com/docs/en/build-with-claude/structured-outputs)", "references": [{"title": "Claude Code CLI reference", "url": "https://code.claude.com/docs/en/cli-reference"}, {"title": "Structured outputs", "url": "https://platform.claude.com/docs/en/build-with-claude/structured-outputs"}]}, {"no": 41, "id": 1156, "type": "single", "select": 1, "question": "A customer support agent using Claude Agent SDK receives multiple possible customer profiles when users provide common names and partial addresses. \n\nThe agent sometimes selects a profile based on recent activity or name similarity, causing incorrect refunds and privacy disclosures. \n\nWhat change best improves reliability without unnecessarily routing routine cases to humans?", "imageMissing": false, "options": [{"key": "A", "text": "Rank matching customers by recent activity and continue with the highest ranked profile when confidence exceeds a threshold."}, {"key": "B", "text": "Treat multiple customer matches as unresolved identity and request a disambiguating identifier before any order or refund operations."}, {"key": "C", "text": "Call lookup_order for each matching customer profile, then select the account whose order details best match the message."}, {"key": "D", "text": "Escalate every request with duplicate customer records to a human agent before performing any lookup_order calls."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Treat multiple customer matches as unresolved identity and request a disambiguating identifier before any order or refund operations.\n\nNhiều hồ sơ là identity unresolved; hỏi identifier phân biệt trước truy xuất đơn hoặc hoàn tiền giúp tránh lộ dữ liệu mà không đẩy mọi case cho người.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Rank matching customers by recent activity and continue with the highest ranked profile when confidence exceeds a threshold.**: Hoạt động gần đây không chứng minh đó là người đang yêu cầu.\n- **Call lookup_order for each matching customer profile, then select the account whose order details best match the message.**: Tra đơn mọi hồ sơ tăng truy cập dữ liệu trước khi xác minh chủ thể.\n- **Escalate every request with duplicate customer records to a human agent before performing any lookup_order calls.**: Escalate tất cả bỏ qua khả năng hỏi identifier đơn giản.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}]}, {"no": 42, "id": 1157, "type": "single", "select": 1, "question": "A research report contains two credible studies with different productivity statistics. \n\nThe synthesis agent chooses the larger number as the definitive result. \n\nWhat change improves reliability?", "imageMissing": false, "options": [{"key": "A", "text": "Average the two statistics."}, {"key": "B", "text": "Select the larger study and remove the smaller one."}, {"key": "C", "text": "Search until another source confirms one statistic"}, {"key": "D", "text": "Preserve both statistics with source attribution, methodology notes, and conflict annotation"}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Preserve both statistics with source attribution, methodology notes, and conflict annotation\n\nGiữ cả hai số cùng phương pháp và nguồn cho thấy khác biệt đo lường; không chọn số lớn vì hợp câu chuyện.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Search until another source confirms one statistic**: Tìm đến khi khớp một số là confirmation bias.\n- **Select the larger study and remove the smaller one.**: Cỡ mẫu lớn không tự chứng minh phù hợp cùng câu hỏi hay phương pháp.\n- **Average the two statistics.**: Trung bình hai metric khác định nghĩa có thể vô nghĩa.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 43, "id": 1158, "type": "single", "select": 1, "question": "A structured extraction QA system produces valid JSON, but reviewer findings are inconsistent and difficult to act on. \n\nWhat should improve consistency?", "imageMissing": false, "options": [{"key": "A", "text": "Require every schema field to be non-null"}, {"key": "B", "text": "Add examples showing complete actionable findings"}, {"key": "C", "text": "Use regular expressions to repair missing details"}, {"key": "D", "text": "Request only concise high-confidence responses"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add examples showing complete actionable findings\n\nVí dụ finding đầy đủ minh họa evidence, vị trí và hành động cần sửa; JSON hợp lệ chỉ kiểm tra hình thức chứ không tính actionable.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Require every schema field to be non-null**: Non-null ép có dữ liệu không tồn tại và không thêm logic finding.\n- **Use regular expressions to repair missing details**: Regex không bổ sung bằng chứng thực bị thiếu.\n- **Request only concise high-confidence responses**: Ngắn và tự tin không xác định nội dung cần để hành động.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)\n- [Structured outputs](https://platform.claude.com/docs/en/build-with-claude/structured-outputs)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}, {"title": "Structured outputs", "url": "https://platform.claude.com/docs/en/build-with-claude/structured-outputs"}]}, {"no": 44, "id": 1159, "type": "single", "select": 1, "question": "You are setting up a Claude application that requires API keys for several external services. \n\nWhat is the best way to store the keys?", "imageMissing": false, "options": [{"key": "A", "text": "Store the keys in a secrets manager or environment-specific configuration that is not checked into source code, and load them at runtime."}, {"key": "B", "text": "Use a single shared key across all external services, so any developer working on the application can find the keys easily during development."}, {"key": "C", "text": "Put the keys in the application's configuration file and check the configuration file into the team's repository alongside the rest of the source code."}, {"key": "D", "text": "Email the keys to each developer as needed and have each developer paste the keys into their local environment when they begin working on the application's code."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Store the keys in a secrets manager or environment-specific configuration that is not checked into source code, and load them at runtime.\n\nSecrets manager hoặc config môi trường ngoài version control giảm phát tán key, cho phép cấp/rotate theo môi trường rồi load runtime.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Email the keys to each developer as needed and have each developer paste the keys into their local environment when they begin working on the application's code.**: Email nhân bản key khó thu hồi và audit.\n- **Use a single shared key across all external services, so any developer working on the application can find the keys easily during development.**: Một key chung không phù hợp ranh giới service/quyền và làm rộng tác động lộ key.\n- **Put the keys in the application's configuration file and check the configuration file into the team's repository alongside the rest of the source code.**: Commit key khiến lịch sử repo lưu bí mật dù xóa ở phiên bản sau.\n\n**Tham khảo:**\n\n- [Official Anthropic Python SDK](https://github.com/anthropics/anthropic-sdk-python)", "references": [{"title": "Official Anthropic Python SDK", "url": "https://github.com/anthropics/anthropic-sdk-python"}]}, {"no": 45, "id": 1160, "type": "single", "select": 1, "question": "You are designing a Claude application that maintains user sessions across multi-turn conversations. \n\nThe product team has asked how the application will handle session lifecycle: when sessions should expire, how state is reset, and how the application avoids carrying stale context into new conversations. \n\nHow would you design session lifecycle?", "imageMissing": false, "options": [{"key": "A", "text": "Define explicit session expiration rules, state reset triggers, and rules for starting fresh sessions so stale context does not leak into new conversations."}, {"key": "B", "text": "Define state reset triggers tied to specific application events but apply them across all sessions globally, with no per-session expiration rules."}, {"key": "C", "text": "Define explicit session expiration rules but rely on users to start new conversations when they want fresh context, with no automatic reset triggers in the application."}, {"key": "D", "text": "Define a single short session timeout that applies across all conversations and treat the timeout as the application's complete session lifecycle mechanism."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Define explicit session expiration rules, state reset triggers, and rules for starting fresh sessions so stale context does not leak into new conversations.\n\nExpiration, reset triggers và fresh-session rules cùng xác định khi nào bỏ state từng user, tránh ngữ cảnh cũ rò sang hội thoại mới.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Define a single short session timeout that applies across all conversations and treat the timeout as the application's complete session lifecycle mechanism.**: Một timeout ngắn không xử lý mọi sự kiện reset hoặc nhu cầu hội thoại dài.\n- **Define state reset triggers tied to specific application events but apply them across all sessions globally, with no per-session expiration rules.**: Reset toàn cục có thể xóa session người khác và thiếu expiry riêng.\n- **Define explicit session expiration rules but rely on users to start new conversations when they want fresh context, with no automatic reset triggers in the application.**: Chỉ chờ user mở mới không cưỡng chế reset khi app cần.\n\n**Tham khảo:**\n\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 46, "id": 1161, "type": "single", "select": 1, "question": "You are building an MCP server that exposes several internal data sources as MCP resources. \n\nThe server needs to be deployed so multiple Claude applications can integrate with it. \n\nHow would you approach the build and deployment?", "imageMissing": false, "options": [{"key": "A", "text": "Bypass the MCP server and embed each data source directly in every Claude application that needs the data, with each application maintaining its own integration."}, {"key": "B", "text": "Author the server with clearly defined resources, tools, and prompts, choose a communication pattern, and deploy to an accessible hosting environment."}, {"key": "C", "text": "Build the MCP server with resource and tool definitions scoped to the first Claude application that needs it, and extend the definitions to additional applications as each integration is requested."}, {"key": "D", "text": "Deploy the MCP server only on individual developer machines, with the Claude applications unable to reach the server outside each developer's machine."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Author the server with clearly defined resources, tools, and prompts, choose a communication pattern, and deploy to an accessible hosting environment.\n\nĐịnh nghĩa resource/tool/prompt rõ và transport/hosting truy cập được tạo giao diện MCP dùng chung giữa nhiều app.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Build the MCP server with resource and tool definitions scoped to the first Claude application that needs it, and extend the definitions to additional applications as each integration is requested.**: Thiết kế chỉ cho app đầu dễ khóa contract vào nhu cầu cục bộ.\n- **Deploy the MCP server only on individual developer machines, with the Claude applications unable to reach the server outside each developer's machine.**: Server chỉ ở máy cá nhân không đáp ứng các app không truy cập được.\n- **Bypass the MCP server and embed each data source directly in every Claude application that needs the data, with each application maintaining its own integration.**: Nhúng tích hợp ở mọi app bỏ lợi ích tái sử dụng MCP và lặp bảo trì.\n\n**Tham khảo:**\n\n- [Claude Code MCP configuration](https://code.claude.com/docs/en/mcp)", "references": [{"title": "Claude Code MCP configuration", "url": "https://code.claude.com/docs/en/mcp"}]}, {"no": 47, "id": 1162, "type": "single", "select": 1, "question": "Your team is preparing a new Claude application for production, and the product team has asked for a cost projection. \n\nThe team needs to estimate the cost based on expected request volume, average input length, and average output length. \n\nHow would you build the projection?", "imageMissing": false, "options": [{"key": "A", "text": "Build a cost model that combines expected request volume, average input tokens, average output tokens, the chosen model's pricing, and any caching benefits."}, {"key": "B", "text": "Build a cost model that combines expected request volume and average input tokens, treating output tokens as a small enough share of cost to leave out of the projection."}, {"key": "C", "text": "Build a cost model that uses the average per-request cost from a similar Claude application the team built last year, scaling that figure by expected request volume."}, {"key": "D", "text": "Build a cost model based on expected request volume and the chosen model's pricing, treating average input and output token counts as variables to be estimated post-launch."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Build a cost model that combines expected request volume, average input tokens, average output tokens, the chosen model's pricing, and any caching benefits.\n\nChi phí dự kiến cần volume nhân token input/output theo giá model, cộng điều kiện cache; nêu giả định và kiểm tra bằng đo thực.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Build a cost model that uses the average per-request cost from a similar Claude application the team built last year, scaling that figure by expected request volume.**: Ứng dụng năm trước có token mix và giá khác nên chỉ là baseline sơ bộ.\n- **Build a cost model that combines expected request volume and average input tokens, treating output tokens as a small enough share of cost to leave out of the projection.**: Bỏ output có thể thiếu phần chi phí đáng kể.\n- **Build a cost model based on expected request volume and the chosen model's pricing, treating average input and output token counts as variables to be estimated post-launch.**: Chưa ước token thì giá mỗi request chưa xác định.\n\n**Tham khảo:**\n\n- [Claude pricing](https://platform.claude.com/docs/en/about-claude/pricing)\n- [Prompt caching](https://platform.claude.com/docs/en/build-with-claude/prompt-caching)", "references": [{"title": "Claude pricing", "url": "https://platform.claude.com/docs/en/about-claude/pricing"}, {"title": "Prompt caching", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-caching"}]}, {"no": 48, "id": 1163, "type": "single", "select": 1, "question": "Your Claude application uses structured output that is consumed by downstream code. \n\nThe team wants to handle malformed or unexpected output gracefully so it does not crash downstream systems. \n\nThe best choice for handling this issue would be to...", "imageMissing": false, "options": [{"key": "A", "text": "Silently drop any output that does not match expectations so downstream systems do not see the malformed output the application receives from the model."}, {"key": "B", "text": "Apply defensive parsing to handle unexpected fields, missing values, and type mismatches that the downstream code might otherwise crash on."}, {"key": "C", "text": "Crash on any unexpected output and require manual recovery on affected requests the application handles during normal operation."}, {"key": "D", "text": "Use the output the model produces and leave schema enforcement to a later phase of production after the application is more complete."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Apply defensive parsing to handle unexpected fields, missing values, and type mismatches that the downstream code might otherwise crash on.\n\nDefensive parsing kiểm tra field/type rồi trả lỗi hoặc fallback có chủ đích trước consumer, tránh crash và không âm thầm biến dữ liệu sai thành đúng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Crash on any unexpected output and require manual recovery on affected requests the application handles during normal operation.**: Crash và manual recovery mọi lần không graceful.\n- **Use the output the model produces and leave schema enforcement to a later phase of production after the application is more complete.**: Để schema enforcement sau production khiến consumer nhận dữ liệu không đáng tin.\n- **Silently drop any output that does not match expectations so downstream systems do not see the malformed output the application receives from the model.**: Âm thầm bỏ output che lỗi và gây mất record không truy vết.\n\n**Tham khảo:**\n\n- [Structured outputs](https://platform.claude.com/docs/en/build-with-claude/structured-outputs)", "references": [{"title": "Structured outputs", "url": "https://platform.claude.com/docs/en/build-with-claude/structured-outputs"}]}, {"no": 49, "id": 1164, "type": "single", "select": 1, "question": "Your team uses several plugins across multiple Claude applications, and a recent plugin update introduced a regression. \n\nThe team had not been tracking plugin versions, so the team cannot easily identify which version was previously working. \n\nHow would you address this?", "imageMissing": false, "options": [{"key": "A", "text": "Stop using all plugins until the team can rebuild equivalent functionality directly into the application code, treating plugin avoidance as a way to remove version-related risk."}, {"key": "B", "text": "Add explicit plugin version tracking to the project's configuration so the team can identify, pin, and upgrade plugin versions deliberately."}, {"key": "C", "text": "Treat plugins as untrackable third-party code and rely on plugin authors to communicate breaking changes when they happen, with no internal version tracking."}, {"key": "D", "text": "Upgrade every plugin to the latest version on a regular cadence to keep version drift small, on the grounds that drift contributes to regression risk."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add explicit plugin version tracking to the project's configuration so the team can identify, pin, and upgrade plugin versions deliberately.\n\nTheo dõi và pin version cho phép tái tạo bản tốt, rollback và đánh giá nâng cấp plugin có chủ đích.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Upgrade every plugin to the latest version on a regular cadence to keep version drift small, on the grounds that drift contributes to regression risk.**: Luôn latest không xác định được phiên bản gây regression.\n- **Stop using all plugins until the team can rebuild equivalent functionality directly into the application code, treating plugin avoidance as a way to remove version-related risk.**: Bỏ mọi plugin mở rộng phạm vi xây lại mà không cần cho lỗi version.\n- **Treat plugins as untrackable third-party code and rely on plugin authors to communicate breaking changes when they happen, with no internal version tracking.**: Phụ thuộc tác giả thông báo không thay nội bộ ghi version đang dùng.\n\n**Tham khảo:**\n\n- [Claude Code best practices](https://code.claude.com/docs/en/best-practices)", "references": [{"title": "Claude Code best practices", "url": "https://code.claude.com/docs/en/best-practices"}]}, {"no": 50, "id": 1165, "type": "single", "select": 1, "question": "You are deciding between deploying a Claude-powered agent on Anthropic's hosted infrastructure or self-hosting under a \"bring your own cloud\" model in your own AWS account. \n\nThe agent processes customer data subject to your enterprise's data residency policies, but the team wants to ship quickly and avoid managing infrastructure. \n\nWhich deployment model would you recommend?", "imageMissing": false, "options": [{"key": "A", "text": "Deploying on Anthropic-hosted infrastructure to meet the team's shipping timeline, and flagging the data residency requirement for a follow-up compliance review after launch."}, {"key": "B", "text": "Self-hosting under BYOC for an initial pilot, then evaluating whether to migrate to Anthropic-hosted infrastructure once the agent's data-handling patterns are better understood."}, {"key": "C", "text": "Self-hosting under BYOC to satisfy the data residency requirement, while working with the infrastructure team to reduce the operational overhead of managing the deployment."}, {"key": "D", "text": "Deploying on Anthropic-hosted infrastructure while the team drafts a request to update the enterprise data residency policy to accommodate hosted Al deployments."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Self-hosting under BYOC to satisfy the data residency requirement, while working with the infrastructure team to reduce the operational overhead of managing the deployment.\n\nKhóa nguồn chọn BYOC nhằm ưu tiên ràng buộc cư trú dữ liệu trước tốc độ giao hàng. Cách lập luận chỉ hợp lệ nếu triển khai trong AWS của doanh nghiệp thực sự đáp ứng yêu cầu, còn lựa chọn hosted cụ thể không đáp ứng. Cần phân biệt nơi chạy agent với nơi Claude xử lý dữ liệu: tự host agent không có nghĩa tự host trọng số model, cũng không tự bảo đảm mọi đường truyền và lưu trữ đúng khu vực.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Deploying on Anthropic-hosted infrastructure to meet the team's shipping timeline, and flagging the data residency requirement for a follow-up compliance review after launch.**: Ra mắt rồi mới xem tuân thủ không giải quyết ràng buộc dữ liệu đã biết trước khi xử lý dữ liệu khách hàng.\n- **Deploying on Anthropic-hosted infrastructure while the team drafts a request to update the enterprise data residency policy to accommodate hosted Al deployments.**: Đề nghị sửa chính sách chưa phải sự chấp thuận; triển khai trong lúc chờ có thể vẫn vi phạm yêu cầu hiện tại.\n- **Self-hosting under BYOC for an initial pilot, then evaluating whether to migrate to Anthropic-hosted infrastructure once the agent's data-handling patterns are better understood.**: Pilot BYOC có thể hợp lý, nhưng chưa có bằng chứng hosted về sau đáp ứng điều kiện để chốt kế hoạch di chuyển.\n\n**Cần xem lại:** Đề không nêu khu vực được phép, dịch vụ inference, điều khoản hosted hay quyền kiểm soát dữ liệu. Không thể kết luận BYOC là đáp án duy nhất chỉ từ nhãn triển khai; cần làm rõ các giả định trước khi publish.\n\n**Tham khảo:**\n\n- [Data residency](%5C%22https%3A//platform.claude.com/docs/en/manage-claude/data-residency%5C%22)\n- [Hosting the Agent SDK](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/hosting%5C%22)", "references": [{"title": "Data residency", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/manage-claude/data-residency%5C%22"}, {"title": "Hosting the Agent SDK", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/hosting%5C%22"}]}, {"no": 51, "id": 1166, "type": "single", "select": 1, "question": "Your Claude application uses tool calling to fetch patient data and generate summary reports. \n\nThe flow occasionally fails because the model returns a tool_use block that references arguments not present in the schema, and your application code does not handle this case gracefully. \n\nHow would you address this?", "imageMissing": false, "options": [{"key": "A", "text": "Retry the same request repeatedly until the model returns a valid tool_use block that matches the schema as expected."}, {"key": "B", "text": "Log invalid tool_use blocks when they occur and allow the tool dispatch to proceed, relying on the tool's own error handling to surface failures back to the application."}, {"key": "C", "text": "Validate the tool_use block's arguments against the tool schema before dispatching the tool and handle invalid arguments as a recognized error path."}, {"key": "D", "text": "Stop using tool calling entirely and replace tools with prompted text generation that asks the model to describe what it would do."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Validate the tool_use block's arguments against the tool schema before dispatching the tool and handle invalid arguments as a recognized error path.\n\nValidate arguments trước dispatch chặn field ngoài schema và xử lý như lỗi có cấu trúc; phù hợp dữ liệu bệnh nhân cần ranh giới rõ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Stop using tool calling entirely and replace tools with prompted text generation that asks the model to describe what it would do.**: Bỏ tool calling làm mất khả năng lấy dữ liệu có kiểm soát thay vì sửa contract.\n- **Retry the same request repeatedly until the model returns a valid tool_use block that matches the schema as expected.**: Retry vô hạn không sửa nguyên nhân hoặc giới hạn chi phí.\n- **Log invalid tool_use blocks when they occur and allow the tool dispatch to proceed, relying on the tool's own error handling to surface failures back to the application.**: Log rồi vẫn dispatch để lỗi đi vào backend thay vì chặn trước.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}]}, {"no": 52, "id": 1167, "type": "single", "select": 1, "question": "Your Claude application's prompt was written months ago and has not been updated. \n\nThe team has discovered through evals that the prompt produces good results on common cases but underperforms on a specific category of inputs that has grown in volume. \n\nHow would you respond?", "imageMissing": false, "options": [{"key": "A", "text": "Iterate on the prompt to address the underperforming category, validate the change with evals, and continue refining as needed."}, {"key": "B", "text": "Add the underperforming category to a separate Claude application with its own prompt so the original prompt does not change."}, {"key": "C", "text": "Replace the prompt with a new one aligned to the underperforming category, treating any common-case performance change as a known tradeoff."}, {"key": "D", "text": "Tell users to avoid the underperforming category by adding warnings in the application's user interface about handled inputs."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Iterate on the prompt to address the underperforming category, validate the change with evals, and continue refining as needed.\n\nBổ sung prompt cho nhóm lỗi rồi chạy eval cả nhóm mới lẫn case cũ giúp cải thiện mà kiểm soát regression.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Tell users to avoid the underperforming category by adding warnings in the application's user interface about handled inputs.**: Bảo user tránh category không sửa nhu cầu đang tăng.\n- **Add the underperforming category to a separate Claude application with its own prompt so the original prompt does not change.**: App riêng có thể không cần và làm phân tán logic trước khi thử prompt có kiểm chứng.\n- **Replace the prompt with a new one aligned to the underperforming category, treating any common-case performance change as a known tradeoff.**: Đổi hẳn chỉ tối ưu nhóm mới chấp nhận regression mà chưa đo.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 53, "id": 1168, "type": "single", "select": 1, "question": "A teammate is reviewing the team's threat model for a Claude application and has asked you to identify the categories of Al-specific threats that the model should cover. \n\nThe teammate has already listed traditional web application threats and wants to know what additional categories apply to a Claude application. \n\nWhich Al-specific threat categories would you add?", "imageMissing": false, "options": [{"key": "A", "text": "Prompt injection, data leakage from prompts or context, jailbreak attempts, and unsafe model output that bypasses application controls."}, {"key": "B", "text": "Supply chain attacks on the Claude SDK because the SDK itself is the only point of vulnerability that a Claude application introduces beyond traditional web application threats."}, {"key": "C", "text": "Network-level denial of service and physical infrastructure attacks, because these categories cover the threats most likely to affect any Claude application in production."}, {"key": "D", "text": "Cross-site scripting and SQL injection, because these traditional web application threats apply with equal weight to any application that uses Claude in any way."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Prompt injection, data leakage from prompts or context, jailbreak attempts, and unsafe model output that bypasses application controls.\n\nPrompt injection, context leakage, jailbreak và unsafe output là các bề mặt đặc thù khi text có thể điều khiển hành vi model hoặc consumer.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Supply chain attacks on the Claude SDK because the SDK itself is the only point of vulnerability that a Claude application introduces beyond traditional web application threats.**: SDK supply chain là rủi ro có thật nhưng không phải điểm yếu AI duy nhất.\n- **Network-level denial of service and physical infrastructure attacks, because these categories cover the threats most likely to affect any Claude application in production.**: DoS và hạ tầng vật lý là rủi ro hệ thống chung, không bổ sung đúng bề mặt model.\n- **Cross-site scripting and SQL injection, because these traditional web application threats apply with equal weight to any application that uses Claude in any way.**: XSS/SQLi vẫn cần kiểm soát nhưng đề đã có web threats và hỏi phần AI bổ sung.\n\n**Tham khảo:**\n\n- [Mitigate prompt injection and jailbreaks](https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks)", "references": [{"title": "Mitigate prompt injection and jailbreaks", "url": "https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks"}]}, {"no": 54, "id": 1169, "type": "single", "select": 1, "question": "The Claude application your team built has grown over six months, and the prompt-handling code has accumulated duplication and tangled control flow. \n\nThe functionality is working, but new features are getting harder to add. How would you address this?", "imageMissing": false, "options": [{"key": "A", "text": "Refactor the prompt-handling code in small increments as part of each new feature ticket, treating the cleanup as a side effect of feature work."}, {"key": "B", "text": "Continue adding features and plan a refactoring pass after the next two release cycles when the team has more bandwidth for internal work."}, {"key": "C", "text": "Move all the prompt-handling code into a single large function to reduce the number of files developers have to navigate when reading the code."}, {"key": "D", "text": "Plan a refactoring pass to consolidate duplicated logic, separate concerns, and simplify control flow before adding new features."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Plan a refactoring pass to consolidate duplicated logic, separate concerns, and simplify control flow before adding new features.\n\nThành phần xử lý prompt đang cản trở việc thay đổi. Một đợt refactor có phạm vi rõ giúp bỏ logic lặp và tách trách nhiệm; kiểm tra hồi quy giữ nguyên hành vi.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Refactor the prompt-handling code in small increments as part of each new feature ticket, treating the cleanup as a side effect of feature work.**: Dọn tiện theo từng ticket không bảo đảm xử lý phần nợ rộng đang tồn tại.\n- **Continue adding features and plan a refactoring pass after the next two release cycles when the team has more bandwidth for internal work.**: Chờ thêm hai chu kỳ làm nợ tích tụ.\n- **Move all the prompt-handling code into a single large function to reduce the number of files developers have to navigate when reading the code.**: Gom vào một hàm lớn làm mờ trách nhiệm thay vì đơn giản hóa.\n\n**Tham khảo:**\n\n- [testing.googleblog.com — just-say-no-to-more-end-to-end-tests.html](%5C%22https%3A//testing.googleblog.com/2015/04/just-say-no-to-more-end-to-end-tests.html%5C%22)", "references": [{"title": "testing.googleblog.com — just-say-no-to-more-end-to-end-tests.html", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//testing.googleblog.com/2015/04/just-say-no-to-more-end-to-end-tests.html%5C%22"}]}, {"no": 55, "id": 1170, "type": "single", "select": 1, "question": "You are building a Claude application that needs to deliver model output to end users as it is generated, instead of waiting for the full response to complete. \n\nThe Claude API mechanism you would use is...", "imageMissing": false, "options": [{"key": "A", "text": "The Batch APl, which delivers full responses after a delay suitable for non-interactive workloads."}, {"key": "B", "text": "Structured JSON output, which delivers responses only after the model has finalized the JSON shape across the entire response."}, {"key": "C", "text": "Streaming responses, which deliver tokens incrementally as the model generates them so users see output progressively."}, {"key": "D", "text": "Prompt caching, which speeds up the cost profile of future requests and does not affect the delivery timing of the first response."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Streaming responses, which deliver tokens incrementally as the model generates them so users see output progressively.\n\nStreaming gửi các phần nội dung khi đang sinh để user thấy tiến độ sớm, không chờ cả response hoàn tất.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **The Batch APl, which delivers full responses after a delay suitable for non-interactive workloads.**: Batch phục vụ xử lý bất đồng bộ, không trả token tương tác ngay.\n- **Prompt caching, which speeds up the cost profile of future requests and does not affect the delivery timing of the first response.**: Caching tái sử dụng prefix, không phải cơ chế truyền output từng phần.\n- **Structured JSON output, which delivers responses only after the model has finalized the JSON shape across the entire response.**: Schema định dạng dữ liệu; không thay streaming và không phải lý do phải chờ cả response theo định nghĩa chung.\n\n**Tham khảo:**\n\n- [Streaming Messages](https://platform.claude.com/docs/en/build-with-claude/streaming)", "references": [{"title": "Streaming Messages", "url": "https://platform.claude.com/docs/en/build-with-claude/streaming"}]}, {"no": 56, "id": 1171, "type": "single", "select": 1, "question": "The Anthropic API deprecated a request parameter that your Claude application uses in approximately 40 laces across the codebase. \n\nThe deprecation notice gives a six-month window before the parameter is removed and recommends a replacement parameter with slightly different semantics. \n\nYou would respond to the deprecation by...", "imageMissing": false, "options": [{"key": "A", "text": "Migrating all 40 call sites in a single change near the removal date to ensure the deprecated parameter continues to work as long as possible."}, {"key": "B", "text": "Keeping the deprecated parameter in place while writing a wrapper function around it to insulate the rest of the codebase from the eventual change."}, {"key": "C", "text": "Adding regression tests to cover the parameter's behavior, then migrating call sites in batches that you validate against regression tests."}, {"key": "D", "text": "Swapping all 40 call sites in a single change right away to prevent drawn-out migration work that will delay ongoing functioning."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Adding regression tests to cover the parameter's behavior, then migrating call sites in batches that you validate against regression tests.\n\nTest bảo toàn hành vi rồi migrate từng nhóm giúp phát hiện thay đổi semantics sớm trước deadline removal.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Keeping the deprecated parameter in place while writing a wrapper function around it to insulate the rest of the codebase from the eventual change.**: Wrapper quanh parameter cũ vẫn phụ thuộc thứ sẽ bị xóa.\n- **Migrating all 40 call sites in a single change near the removal date to ensure the deprecated parameter continues to work as long as possible.**: Chờ sát hạn làm ít thời gian xử lý khác biệt và rollback.\n- **Swapping all 40 call sites in a single change right away to prevent drawn-out migration work that will delay ongoing functioning.**: Đổi mọi nơi ngay không test tăng blast radius regression.\n\n**Tham khảo:**\n\n- [Claude Code best practices](https://code.claude.com/docs/en/best-practices)", "references": [{"title": "Claude Code best practices", "url": "https://code.claude.com/docs/en/best-practices"}]}, {"no": 57, "id": 1172, "type": "single", "select": 1, "question": "Your application uses the Messages API to handle multi-turn conversations. \n\nEach new turn resends the entire conversation history, and your token costs are growing as conversations get longer. \n\nYou suspect there is a more efficient approach. \n\nHow would you address this?", "imageMissing": false, "options": [{"key": "A", "text": "Truncate every conversation to the last two messages so that token usage stays low and costs remain predictable across the application's normal operation."}, {"key": "B", "text": "Summarize each conversation after every turn and replace the full history with the summary on the next request, reducing token count at the cost of fidelity."}, {"key": "C", "text": "Use prompt caching to reuse the static portions of the conversation context across turns instead of paying for them at the normal input-token rate on every request the application sends."}, {"key": "D", "text": "Switch to the Batch API for every turn so the per-call cost is reduced, treating the batch as the team's primary cost-control mechanism for multi-turn work."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use prompt caching to reuse the static portions of the conversation context across turns instead of paying for them at the normal input-token rate on every request the application sends.\n\nPrompt caching tái dùng prefix ổn định theo cơ chế cache, giảm giá đọc input lặp mà vẫn giữ nội dung; không tự xóa token hay mở rộng context.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Truncate every conversation to the last two messages so that token usage stays low and costs remain predictable across the application's normal operation.**: Cắt chỉ hai message có thể mất ràng buộc quan trọng.\n- **Summarize each conversation after every turn and replace the full history with the summary on the next request, reducing token count at the cost of fidelity.**: Tóm tắt mỗi lượt có thể mất chi tiết không cần thiết khi prefix cache đã hỗ trợ.\n- **Switch to the Batch API for every turn so the per-call cost is reduced, treating the batch as the team's primary cost-control mechanism for multi-turn work.**: Batch cho mọi lượt làm mất độ trễ tương tác yêu cầu.\n\n**Tham khảo:**\n\n- [Prompt caching](https://platform.claude.com/docs/en/build-with-claude/prompt-caching)", "references": [{"title": "Prompt caching", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-caching"}]}, {"no": 58, "id": 1173, "type": "single", "select": 1, "question": "You are configuring Claude Code for a new project. \n\nThe team needs to set permissions, default model selections, and environment-specific behavior at the project level so the configuration is consistent across all developers working on the repository. \n\nThe Claude Code mechanism you would use is...", "imageMissing": false, "options": [{"key": "A", "text": "The settings.json file, scoped at the project level so the configuration applies consistently across developers and persists with the repository."}, {"key": "B", "text": "A shared spreadsheet that lists configuration values for team members to reference and update by hand as the project evolves."}, {"key": "C", "text": "Environment variables that each developer sets on their own machine when working with Claude Code on the project."}, {"key": "D", "text": "A system prompt embedded in every Claude Code conversation by each developer at the start of every session in the project."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** The settings.json file, scoped at the project level so the configuration applies consistently across developers and persists with the repository.\n\n.claude/settings.json cấp project chia sẻ model/permissions phù hợp qua repo; config local và secret riêng không nên commit.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A system prompt embedded in every Claude Code conversation by each developer at the start of every session in the project.**: Prompt mỗi session không phải cấu hình client permissions/model bền vững.\n- **Environment variables that each developer sets on their own machine when working with Claude Code on the project.**: Env từng máy dễ lệch và không tự chia sẻ project config.\n- **A shared spreadsheet that lists configuration values for team members to reference and update by hand as the project evolves.**: Spreadsheet đòi nhập tay và không được client tự áp.\n\n**Tham khảo:**\n\n- [Claude Code settings](https://code.claude.com/docs/en/settings)", "references": [{"title": "Claude Code settings", "url": "https://code.claude.com/docs/en/settings"}]}, {"no": 59, "id": 1174, "type": "single", "select": 1, "question": "Your team is preparing to roll out a configuration change that updates several prompt versions across a Claude application used by multiple downstream systems. \n\nThe change has already been tested in staging, but the team has not assessed how the prompt change will affect each downstream system that depends on the application's output. \n\nWhat would you do before rolling out the change?", "imageMissing": false, "options": [{"key": "A", "text": "Assess the configuration impact on each downstream system before rolling out, and coordinate with downstream system owners as needed."}, {"key": "B", "text": "Notify downstream system owners that a change is coming and schedule the rollout for the following week, without conducting a formal impact assessment."}, {"key": "C", "text": "Document the prompt version changes in the application changelog and proceed with the rollout, treating the staging test results as sufficient evidence of impact across all downstream systems."}, {"key": "D", "text": "Limit the rollout to systems that were explicitly included in staging testing, and defer all other downstream systems until a later release cycle."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Assess the configuration impact on each downstream system before rolling out, and coordinate with downstream system owners as needed.\n\nĐánh giá contract và tác động từng downstream giúp phát hiện parser hoặc logic phụ thuộc format trước rollout, phối hợp owner để kiểm chứng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Notify downstream system owners that a change is coming and schedule the rollout for the following week, without conducting a formal impact assessment.**: Thông báo lịch không thay đánh giá tác động.\n- **Document the prompt version changes in the application changelog and proceed with the rollout, treating the staging test results as sufficient evidence of impact across all downstream systems.**: Staging chung chưa chứng minh mọi consumer đều tương thích.\n- **Limit the rollout to systems that were explicitly included in staging testing, and defer all other downstream systems until a later release cycle.**: Chỉ rollout nhóm đã test có thể là biện pháp sau đánh giá, không thay việc xác định ảnh hưởng còn thiếu.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 60, "id": 1175, "type": "single", "select": 1, "question": "A teammate has submitted a pull request that adds a Claude-powered feature to your service. \n\nThe code works, but the prompt and model selection are hard-coded inline, error handling is missing, and there are no tests for the integration. \n\nWhat would you request during code review?", "imageMissing": false, "options": [{"key": "A", "text": "Request changes that move prompt and model configuration to a configurable location and add tests, treating the missing error handling as a follow-up release item."}, {"key": "B", "text": "Request changes that move prompt and model configuration to a configurable location, add error handling for Claude API failures, and add tests for the integration."}, {"key": "C", "text": "Approve the pull request as-is, on the grounds that the feature works in the happy path and the missing pieces can be added in follow-up commits."}, {"key": "D", "text": "Approve the pull request and add the missing pieces yourself in a follow-up commit so the teammate can move on to other work immediately."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Request changes that move prompt and model configuration to a configurable location, add error handling for Claude API failures, and add tests for the integration.\n\nConfig rõ, xử lý API failure và test integration kiểm soát thay đổi model/prompt cùng tình huống lỗi, không chỉ happy path.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Approve the pull request and add the missing pieces yourself in a follow-up commit so the teammate can move on to other work immediately.**: Approve rồi sửa sau đưa thiếu sót vào nhánh chính trước kiểm tra.\n- **Approve the pull request as-is, on the grounds that the feature works in the happy path and the missing pieces can be added in follow-up commits.**: Happy path không chứng minh vận hành khi API lỗi.\n- **Request changes that move prompt and model configuration to a configurable location and add tests, treating the missing error handling as a follow-up release item.**: Chừa error handling sau vẫn để production có đường lỗi chưa xử lý.\n\n**Tham khảo:**\n\n- [Official Anthropic Python SDK](https://github.com/anthropics/anthropic-sdk-python)\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Official Anthropic Python SDK", "url": "https://github.com/anthropics/anthropic-sdk-python"}, {"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 61, "id": 1176, "type": "single", "select": 1, "question": "You are setting up Claude Code for a new project repository. \n\nYour team has shared coding standards, preferred libraries, and project-specific context that every developer working on the repository should have available when they use Claude Code. \n\nHow would you set this up?", "imageMissing": false, "options": [{"key": "A", "text": "Initialize Claude Code in the repository and document the standards and project-specific context in a CLAUDE.mdfile at the repository root."}, {"key": "B", "text": "Add the coding standards and project context to the repository's existing README file and direct developers to reference it when starting Claude Code sessions."}, {"key": "C", "text": "Document the standards in a separate wiki page maintained outside the repository so the documentation stays decoupled from the source code."}, {"key": "D", "text": "Configure Claude Code through environment variables that each developer sets on their own machine when they begin working in the repository."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Initialize Claude Code in the repository and document the standards and project-specific context in a CLAUDE.mdfile at the repository root.\n\nCLAUDE.md gốc repo mang chuẩn và context project vào phiên đúng phạm vi, thay vì mỗi người tự nhớ chép prompt.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Document the standards in a separate wiki page maintained outside the repository so the documentation stays decoupled from the source code.**: Wiki ngoài repo không mặc nhiên được load trong session.\n- **Configure Claude Code through environment variables that each developer sets on their own machine when they begin working in the repository.**: Env variables không phù hợp chứa toàn hướng dẫn coding/context.\n- **Add the coding standards and project context to the repository's existing README file and direct developers to reference it when starting Claude Code sessions.**: README có thể được đọc khi cần nhưng không phải cơ chế tự nhận instruction project được hỏi.\n\n**Tham khảo:**\n\n- [Claude Code memory hierarchy](https://code.claude.com/docs/en/memory)", "references": [{"title": "Claude Code memory hierarchy", "url": "https://code.claude.com/docs/en/memory"}]}, {"no": 62, "id": 1177, "type": "single", "select": 1, "question": "You are reviewing an architectural diagram for a Claude-powered travel-booking system. \n\nThe diagram shows a top-level component that interprets user requests and three subordinate components that handle flights, hotels, and ground transportation. \n\nThe top-level component is responsible for routing each request, sequencing the subordinate components, and reconciling their outputs into a final itinerary. \n\nThe diagram also shows that each subordinate component has its own tool list and own short conversation history that is not shared with the others. \n\nWhich architectural pattern does this diagram most closely describe?", "imageMissing": false, "options": [{"key": "A", "text": "A retrieval-augmented pattern, where the top-level component retrieves relevant context from the subordinate components' indexed data stores before generating each response."}, {"key": "B", "text": "A manager and supervisor pattern with isolated context per subagent, where the top-level agent coordinates specialized subagents that each maintain their own conversation history and tool list."}, {"key": "C", "text": "A manager and supervisor pattern with shared context, where the top-level agent and the subagents all share a single conversation history that grows as the request flows through the system."}, {"key": "D", "text": "A pipeline pattern, where each component processes the user request in sequence and passes the full conversation history along with the request to the next component in the pipeline."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A manager and supervisor pattern with isolated context per subagent, where the top-level agent coordinates specialized subagents that each maintain their own conversation history and tool list.\n\nManager điều phối chuyên gia flights/hotels/ground, mỗi agent có tools và history riêng; isolation được nêu rõ trong diagram.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A manager and supervisor pattern with shared context, where the top-level agent and the subagents all share a single conversation history that grows as the request flows through the system.**: Shared history trái điều kiện diagram nói không chia sẻ.\n- **A pipeline pattern, where each component processes the user request in sequence and passes the full conversation history along with the request to the next component in the pipeline.**: Pipeline truyền toàn history không khớp routing và tổng hợp manager.\n- **A retrieval-augmented pattern, where the top-level component retrieves relevant context from the subordinate components' indexed data stores before generating each response.**: Retrieval từ indexed stores không mô tả các subagent có tools/history.\n\n**Tham khảo:**\n\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)", "references": [{"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}, {"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}]}, {"no": 63, "id": 1178, "type": "single", "select": 1, "question": "You are starting a new Claude application and have a small set of well-labeled examples that demonstrate the desired output format. \n\nYou want to use these examples to guide Claude's behavior. \n\nHow would you guide the application's behavior?", "imageMissing": false, "options": [{"key": "A", "text": "Train a custom model on the labeled examples before deployment so that the application does not need to include the examples in any prompt during operation."}, {"key": "B", "text": "Use multi-shot prompting by including the labeled examples in the prompt so Claude can match the desired output format on each request."}, {"key": "C", "text": "Use zero-shot prompting and rely on the model's general capability to produce the desired output format consistently across all incoming requests."}, {"key": "D", "text": "Embed the examples in a database and retrieve them at runtime as reference material for the team."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use multi-shot prompting by including the labeled examples in the prompt so Claude can match the desired output format on each request.\n\nMulti-shot đưa ví dụ gắn nhãn trực tiếp vào context để minh họa format và pattern mong muốn cho mỗi yêu cầu.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Use zero-shot prompting and rely on the model's general capability to produce the desired output format consistently across all incoming requests.**: Zero-shot không dùng chính examples đã có.\n- **Embed the examples in a database and retrieve them at runtime as reference material for the team.**: Database chỉ hữu ích nếu có retrieval đưa ví dụ vào context; lưu cho team chưa đủ.\n- **Train a custom model on the labeled examples before deployment so that the application does not need to include the examples in any prompt during operation.**: Huấn luyện riêng từ ít ví dụ quá nặng so với mục tiêu format; không cần trước khi thử prompting.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}]}, {"no": 64, "id": 1179, "type": "single", "select": 1, "question": "You are setting up the configuration management approach for a new Claude Code project. \n\nYour team will use CLAUDE.md files and settings.json files to control behavior, and you want to make sure changes are tracked and reviewable. \n\nThe configuration management approach would...", "imageMissing": false, "options": [{"key": "A", "text": "Version-control CLAUDE.md and settings.json files in a separate repository from the project's source code, so configuration evolves independently from the application code over time."}, {"key": "B", "text": "Duplicate CLAUDE.md and settings.json files in multiple repositories to provide redundancy, on the grounds that a single source of truth is risky for project configuration."}, {"key": "C", "text": "Version-control CLAUDE.md alongside the project's source code and settings. json files in a separate repository from the project's source code."}, {"key": "D", "text": "Version-control CLAUDE.md and settings.json files alongside the project's source code, with changes reviewed through standard pull request workflows the team applies."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Version-control CLAUDE.md and settings.json files alongside the project's source code, with changes reviewed through standard pull request workflows the team applies.\n\nVersion control chung code và cấu hình giúp review một thay đổi hành vi cùng implementation, tái tạo hoặc rollback đúng cặp phiên bản.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Duplicate CLAUDE.md and settings.json files in multiple repositories to provide redundancy, on the grounds that a single source of truth is risky for project configuration.**: Nhân bản nhiều bản dễ drift, không tạo nguồn chuẩn duy nhất.\n- **Version-control CLAUDE.md and settings.json files in a separate repository from the project's source code, so configuration evolves independently from the application code over time.**: Repo riêng có thể quản lý được nhưng cần liên kết version; không trực tiếp giữ thay đổi project cùng PR như đề yêu cầu.\n- **Version-control CLAUDE.md alongside the project's source code and settings. json files in a separate repository from the project's source code.**: Tách chỉ settings vẫn làm việc tái tạo cặp code/config khó hơn.\n\n**Tham khảo:**\n\n- [Claude Code settings](https://code.claude.com/docs/en/settings)\n- [Claude Code memory hierarchy](https://code.claude.com/docs/en/memory)", "references": [{"title": "Claude Code settings", "url": "https://code.claude.com/docs/en/settings"}, {"title": "Claude Code memory hierarchy", "url": "https://code.claude.com/docs/en/memory"}]}, {"no": 65, "id": 1180, "type": "single", "select": 1, "question": "Your agent is processing tasks that take 30 to 60 minutes to complete. \n\nEach task has well-defined intermediate checkpoints, and the team wants the agent to be able to resume from the most recent checkpoint if a process is interrupted. \n\nHow would you implement this resumability?", "imageMissing": false, "options": [{"key": "A", "text": "Restart the task from the beginning whenever a process is interrupted."}, {"key": "B", "text": "Apply a checkpointing pattern that persists the agent's intermediate state and reloads that state when resuming an interrupted task."}, {"key": "C", "text": "Run two copies of the agent in parallel for every task and use whichever one finishes first as the source of truth."}, {"key": "D", "text": "Increase the agent's timeout to several hours so that interruptions become rare enough to ignore in practice."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Apply a checkpointing pattern that persists the agent's intermediate state and reloads that state when resuming an interrupted task.\n\nCheckpoint lưu state trung gian và trạng thái bước đã hoàn tất để khôi phục từ điểm gần nhất, tránh làm lại tác vụ dài.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Increase the agent's timeout to several hours so that interruptions become rare enough to ignore in practice.**: Timeout dài không tránh crash hoặc mất process.\n- **Run two copies of the agent in parallel for every task and use whichever one finishes first as the source of truth.**: Hai bản chạy có thể lặp side effect và không định nghĩa khôi phục state.\n- **Restart the task from the beginning whenever a process is interrupted.**: Restart toàn bộ bỏ lợi ích checkpoint đã có.\n\n**Tham khảo:**\n\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 66, "id": 1181, "type": "single", "select": 1, "question": "A team has deployed a multi-agent system in which a primary agent decomposes user requests and delegates subtasks to three specialized subagents: one for data retrieval, one for analysis, and one for report generation. \n\nIn production, the team observes that subagents are making redundant tool calls, occasionally exceeding token budgets, and sometimes producing outputs that contradict each other - all of which the primary agent passes along without catching. \n\nWhat is the most appropriate way to address these failures?", "imageMissing": false, "options": [{"key": "A", "text": "Strengthen the primary agent's management layer to enforce per-subagent tool budgets, validate outputs against a defined schema before passing them forward, and establish explicit handoff contracts between stages."}, {"key": "B", "text": "Add retry logic to each subagent so that when a tool call fails, the subagent retries automatically before escalating - and configure each subagent to log its tool calls and outputs to a shared trace so the team can audit redundancy and contradictions after the fact."}, {"key": "C", "text": "Collapse the three subagents into a single large-context model call that handles retrieval, analysis, and generation in one pass."}, {"key": "D", "text": "Give each subagent read access to the other subagents' outputs so they can identify and resolve contradictions without routing back through the primary agent."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Strengthen the primary agent's management layer to enforce per-subagent tool budgets, validate outputs against a defined schema before passing them forward, and establish explicit handoff contracts between stages.\n\nManager cưỡng chế budget, schema và hợp đồng handoff để chặn output mâu thuẫn hoặc quá giới hạn trước khi chuyển tiếp.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Add retry logic to each subagent so that when a tool call fails, the subagent retries automatically before escalating - and configure each subagent to log its tool calls and outputs to a shared trace so the team can audit redundancy and contradictions after the fact.**: Retry và audit sau không ngăn redundant calls hay output sai lúc chạy.\n- **Give each subagent read access to the other subagents' outputs so they can identify and resolve contradictions without routing back through the primary agent.**: Đọc output lẫn nhau không thay quản lý budget và gate thống nhất.\n- **Collapse the three subagents into a single large-context model call that handles retrieval, analysis, and generation in one pass.**: Một call lớn bỏ chuyên môn hóa nhưng không giải quyết kiểm chứng hoặc giới hạn.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}, {"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 67, "id": 1182, "type": "single", "select": 1, "question": "Your agent makes 10 to 15 tool calls per task, and you have noticed it sometimes loses track of earlier results by the time it reaches later steps. \n\nThe agent's context window is large enough to hold all the messages, but the relevant information appears to get buried as the conversation grows. \n\nHow would you address this?", "imageMissing": false, "options": [{"key": "A", "text": "Increase the context window further so all tool outputs from every prior step remain in full detail throughout the task."}, {"key": "B", "text": "Switch to a different agentic framework that advertises automatic context-window management as a built-in feature."}, {"key": "C", "text": "Apply a context-management pattern that summarizes or prunes older tool outputs while preserving the active task state."}, {"key": "D", "text": "Reduce the number of tool calls per task by combining several existing tools into larger, multi-purpose tools."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Apply a context-management pattern that summarizes or prunes older tool outputs while preserving the active task state.\n\nTóm tắt/prune output cũ nhưng giữ mục tiêu, ràng buộc và kết quả đang dùng làm evidence giúp giảm nhiễu ngay cả khi chưa đầy context.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Switch to a different agentic framework that advertises automatic context-window management as a built-in feature.**: Đổi framework không tự định nghĩa thông tin cần giữ.\n- **Reduce the number of tool calls per task by combining several existing tools into larger, multi-purpose tools.**: Gộp tool quá rộng có thể làm interface mơ hồ, không xử lý state bị chôn.\n- **Increase the context window further so all tool outputs from every prior step remain in full detail throughout the task.**: Context lớn hơn chứa thêm nhiễu chứ không bảo đảm tập trung.\n\n**Tham khảo:**\n\n- [Effective context engineering](https://www.anthropic.com/research/effective-context-engineering-for-ai-agents)", "references": [{"title": "Effective context engineering", "url": "https://www.anthropic.com/research/effective-context-engineering-for-ai-agents"}]}, {"no": 68, "id": 1183, "type": "single", "select": 1, "question": "A teammate has asked why your Claude application sometimes produces a response that includes the prompt text repeated back, and other times produces a response with the prompt text rephrased. \n\nThey suspect a bug in the application's request construction. \n\nHow would you respond?", "imageMissing": false, "options": [{"key": "A", "text": "Confirm that the variation is a bug in the application's request construction and start investigating which part of the application is producing the inconsistent prompt text."}, {"key": "B", "text": "Tell the teammate that the variation is caused by the application sending two different prompts on different runs and propose a code change that pins the system prompt to a single version."}, {"key": "C", "text": "Explain that LLMs generate output token by token, and variation in how prompt content appears in output is a property of generation, not a bug in request construction."}, {"key": "D", "text": "Tell the teammate that the variation depends on which Claude model serves the request, and recommend pinning the application to a single model version to make the output behavior consistent."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Explain that LLMs generate output token by token, and variation in how prompt content appears in output is a property of generation, not a bug in request construction.\n\nKhóa nguồn chọn giải thích rằng LLM sinh văn bản từng token nên cùng nội dung prompt có thể được lặp lại hoặc diễn đạt lại khác nhau. Biến thiên này có thể là hành vi sinh bình thường, nhưng riêng hiện tượng đó chưa đủ để loại trừ lỗi dựng request. Cần so trace đầu vào và cấu hình giữa các lượt trước khi kết luận có hay không có bug.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Tell the teammate that the variation depends on which Claude model serves the request, and recommend pinning the application to a single model version to make the output behavior consistent.**: Khác model có thể ảnh hưởng đầu ra, nhưng đề không chứng minh request được phục vụ bởi nhiều model; pin version không bảo đảm câu chữ giống hệt.\n- **Confirm that the variation is a bug in the application's request construction and start investigating which part of the application is producing the inconsistent prompt text.**: Chốt là bug từ biến thiên đầu ra là kết luận trước khi xem request thực tế.\n- **Tell the teammate that the variation is caused by the application sending two different prompts on different runs and propose a code change that pins the system prompt to a single version.**: Giả định có hai prompt khác nhau khi chưa so trace cũng là khẳng định nguyên nhân chưa có bằng chứng.\n\n**Cần xem lại:** Đáp án nguồn khẳng định không phải lỗi request quá tuyệt đối. Nên sửa thành “có thể là biến thiên sinh bình thường; cần kiểm tra request để loại trừ bug”, đồng thời giữ khóa hiện có cho đến khi biên tập.\n\n**Tham khảo:**\n\n- [Glossary](%5C%22https%3A//platform.claude.com/docs/en/about-claude/glossary%5C%22)\n- [Define success criteria and build evaluations](%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22)", "references": [{"title": "Glossary", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/about-claude/glossary%5C%22"}, {"title": "Define success criteria and build evaluations", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22"}]}, {"no": 69, "id": 1184, "type": "single", "select": 1, "question": "You are designing a multi-step Claude workflow where some steps must reason without seeing the full prior conversation history. \n\nThe team wants to keep specific context isolated to specific steps. \n\nThe context engineering technique you would use is...", "imageMissing": false, "options": [{"key": "A", "text": "Context isolation through subagents or multi-step agentic workflows that scope each step's context to only what the step needs."}, {"key": "B", "text": "Using a single global prompt that applies to every step in the workflow no matter what each step is reasoning about during its run."}, {"key": "C", "text": "Augmenting the context with all available content at every step so each step has access to the entire prior history of the workflow during its reasoning."}, {"key": "D", "text": "Embedding the full prior history in each step regardless of whether the step needs the prior history for its reasoning."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Context isolation through subagents or multi-step agentic workflows that scope each step's context to only what the step needs.\n\nContext isolation cấp từng bước đúng thông tin cần thiết, tránh lộ context hoặc tác động giả định không phù hợp giữa nhiệm vụ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Augmenting the context with all available content at every step so each step has access to the entire prior history of the workflow during its reasoning.**: Thêm mọi nội dung trái yêu cầu một số bước không thấy full history.\n- **Using a single global prompt that applies to every step in the workflow no matter what each step is reasoning about during its run.**: Global prompt không tự tách dữ liệu history từng bước.\n- **Embedding the full prior history in each step regardless of whether the step needs the prior history for its reasoning.**: Nhúng full history trực tiếp vi phạm điều kiện isolation.\n\n**Tham khảo:**\n\n- [Effective context engineering](https://www.anthropic.com/research/effective-context-engineering-for-ai-agents)\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Effective context engineering", "url": "https://www.anthropic.com/research/effective-context-engineering-for-ai-agents"}, {"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 70, "id": 1185, "type": "single", "select": 1, "question": "A teammate has asked you to explain why your Claude agent's tools include detailed descriptions in the tool definition, even when the tool name is already descriptive. \n\nThe teammate suggests removing the descriptions to simplify the tool definitions. \n\nHow would you respond?", "imageMissing": false, "options": [{"key": "A", "text": "Explain that the model uses the tool description to decide when to call the tool, and descriptions disambiguate cases where the tool name is not enough."}, {"key": "B", "text": "Agree with the teammate because tool names are sufficient for the model to choose the right tool on every request the agent handles."}, {"key": "C", "text": "Suggest moving the descriptions out of the tool definition and into a separate documentation file the teamnaintains so the tool definitions stay short and the descriptions remain available."}, {"key": "D", "text": "Suggest replacing the descriptions with example calls embedded in the tool definition, treating example calls as a complete substitute for the prose description."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Explain that the model uses the tool description to decide when to call the tool, and descriptions disambiguate cases where the tool name is not enough.\n\nDescription nói khi dùng, input hợp lệ và giới hạn output; tên tool ngắn không truyền đủ edge cases để chọn đúng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Suggest replacing the descriptions with example calls embedded in the tool definition, treating example calls as a complete substitute for the prose description.**: Ví dụ bổ sung hữu ích nhưng không thay toàn ranh giới/điều kiện sử dụng.\n- **Agree with the teammate because tool names are sufficient for the model to choose the right tool on every request the agent handles.**: Tên không bảo đảm chọn đúng mọi mixed request.\n- **Suggest moving the descriptions out of the tool definition and into a separate documentation file the teamnaintains so the tool definitions stay short and the descriptions remain available.**: File ngoài không tự hiện trong catalog tool model đang dùng.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}]}, {"no": 71, "id": 1186, "type": "single", "select": 1, "question": "Your Claude application's error handling currently logs every API error with the same severity level. \n\nThe team wants to differentiate between errors that should page an on-call engineer and errors that should be logged for later review. \n\nHow would you structure the error handling?", "imageMissing": false, "options": [{"key": "A", "text": "Categorize errors by severity based on impact and recoverability, then route each category to the appropriate channel for paging or logging."}, {"key": "B", "text": "Log every error with the same severity, on the grounds that differentiating severity adds complexity that does it pay off in most application setups over time."}, {"key": "C", "text": "Page on every error, on the grounds that paging guarantees that no error is missed by the team during normal operation across the application's lifecycle."}, {"key": "D", "text": "Disable logging for any error that does not page, treating non-paging errors as not worth recording for later review either."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Categorize errors by severity based on impact and recoverability, then route each category to the appropriate channel for paging or logging.\n\nSeverity theo tác động và khả năng phục hồi giúp page sự cố cần hành động ngay, còn lỗi recoverable vẫn được ghi để phân tích.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Page on every error, on the grounds that paging guarantees that no error is missed by the team during normal operation across the application's lifecycle.**: Page mọi lỗi gây alert fatigue và làm chìm sự cố quan trọng.\n- **Disable logging for any error that does not page, treating non-paging errors as not worth recording for later review either.**: Không page không có nghĩa không cần dữ liệu debug.\n- **Log every error with the same severity, on the grounds that differentiating severity adds complexity that does it pay off in most application setups over time.**: Severity đồng nhất không phân biệt ưu tiên hành động.\n\n**Tham khảo:**\n\n- [Official Anthropic Python SDK](https://github.com/anthropics/anthropic-sdk-python)", "references": [{"title": "Official Anthropic Python SDK", "url": "https://github.com/anthropics/anthropic-sdk-python"}]}, {"no": 72, "id": 1187, "type": "single", "select": 1, "question": "Your Claude application makes high-volume API calls during business hours and very few calls overnight. \n\nThe team is concerned about staying within rate limits during peak hours and wants to understand how the Claude API enforces those limits. \n\nHow would you proceed?", "imageMissing": false, "options": [{"key": "A", "text": "Examine the peak-hour request patterns in your application logs and smooth traffic by distributing requests more evenly across the business-hours window."}, {"key": "B", "text": "Identify the rate limits, design the application to stay within them during peak hours, and use exponential backoff when limits are reached."}, {"key": "C", "text": "Assess the average payload size of current API calls and consolidate requests where possible to reduce the total number of calls made during peak hours."}, {"key": "D", "text": "Review the API documentation for streaming endpoints and evaluate whether migrating peak-hour calls to streaming reduces exposure to rate limit enforcement."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Identify the rate limits, design the application to stay within them during peak hours, and use exponential backoff when limits are reached.\n\nXác định hạn mức request và token, điều tiết tải cao điểm, rồi chờ tăng dần khi thử lại lỗi giới hạn có thể phục hồi. Lưu lượng thấp ban đêm không xóa giới hạn giờ cao điểm.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Examine the peak-hour request patterns in your application logs and smooth traffic by distributing requests more evenly across the business-hours window.**: Giãn tải có ích nhưng chưa xác định hạn mức và cách thử lại.\n- **Assess the average payload size of current API calls and consolidate requests where possible to reduce the total number of calls made during peak hours.**: Giảm số lượt gọi chưa xử lý mọi loại hạn mức.\n- **Review the API documentation for streaming endpoints and evaluate whether migrating peak-hour calls to streaming reduces exposure to rate limit enforcement.**: Streaming đổi cách truyền kết quả, không miễn giới hạn.\n\n**Tham khảo:**\n\n- [platform.claude.com — rate-limits](%5C%22https%3A//platform.claude.com/docs/en/api/rate-limits%5C%22)", "references": [{"title": "platform.claude.com — rate-limits", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/api/rate-limits%5C%22"}]}, {"no": 73, "id": 1188, "type": "single", "select": 1, "question": "You are extending a Claude agent with a capability that needs to be reusable across multiple teams in the organization, with each team able to invoke and use it independently. \n\nHow would you build the capability?", "imageMissing": false, "options": [{"key": "A", "text": "As a Skill or MCP server because both are purpose-built for cross-team reuse independently by each consuming team."}, {"key": "B", "text": "As a shared library that each team imports into its own Claude application code, with each team responsible or keeping the library up to date in its integration."}, {"key": "C", "text": "As a custom tool embedded in this team's agent only, with other teams able to copy the implementation into their own agents when they need the capability."}, {"key": "D", "text": "As a wrapper around an existing built-in tool that adds the missing functionality, on the grounds that built-in tools cover the reuse pattern when extended carefully."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** As a Skill or MCP server because both are purpose-built for cross-team reuse independently by each consuming team.\n\nSkill đóng gói workflow/instructions, MCP server cung cấp giao diện tool/resource dùng chung; chọn theo nội dung cần tái sử dụng giữa nhóm.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **As a custom tool embedded in this team's agent only, with other teams able to copy the implementation into their own agents when they need the capability.**: Embedded tool chỉ nhóm hiện tại buộc nhóm khác copy và tự bảo trì.\n- **As a shared library that each team imports into its own Claude application code, with each team responsible or keeping the library up to date in its integration.**: Shared library cũng có thể tái dùng, nên không sai tuyệt đối; nhưng đòi từng app tích hợp thay vì cơ chế discover/invoke sẵn của Skill/MCP.\n- **As a wrapper around an existing built-in tool that adds the missing functionality, on the grounds that built-in tools cover the reuse pattern when extended carefully.**: Wrapper built-in không tự tạo cơ chế phân phối độc lập cross-team.\n\n**Tham khảo:**\n\n- [Claude Code skills](https://code.claude.com/docs/en/skills)\n- [Claude Code MCP configuration](https://code.claude.com/docs/en/mcp)", "references": [{"title": "Claude Code skills", "url": "https://code.claude.com/docs/en/skills"}, {"title": "Claude Code MCP configuration", "url": "https://code.claude.com/docs/en/mcp"}]}, {"no": 74, "id": 1189, "type": "single", "select": 1, "question": "You are choosing between using STDIO-based communication and HTTP-based communication for an ACP server. \n\nThe server will be invoked by a Claude Code session running locally. \n\nWhich communication pattern would you use?", "imageMissing": false, "options": [{"key": "A", "text": "HTTP on the grounds that HTTP is preferable to STDIO in any context the application might encounter during normal operation."}, {"key": "B", "text": "STDIO because STDIO is well-suited to local process communication and avoids unnecessary network setup."}, {"key": "C", "text": "STDIO and HTTP simultaneously for redundancy, with the team running two communication patterns at the same time across Claude Code sessions."}, {"key": "D", "text": "HTTP polling against the MCP server, treating HTTP as a substitute for the standard MCP communication patterns."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** STDIO because STDIO is well-suited to local process communication and avoids unnecessary network setup.\n\nSTDIO phù hợp khi MCP server được chạy như tiến trình con cục bộ: client trao đổi thông điệp qua đầu vào và đầu ra chuẩn mà không mở điểm mạng. HTTP cục bộ cũng dùng được, nhưng STDIO tránh cấu hình mạng khi chỉ cần giao tiếp giữa tiến trình. Đề ghi ACP nên cách giải thích này có điều kiện: giao thức thực sự được hỏi phải là MCP.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **STDIO and HTTP simultaneously for redundancy, with the team running two communication patterns at the same time across Claude Code sessions.**: Chạy cả hai transport tăng cấu hình và điểm lỗi khi đề không yêu cầu dự phòng.\n- **HTTP on the grounds that HTTP is preferable to STDIO in any context the application might encounter during normal operation.**: HTTP hữu ích cho server từ xa hoặc dùng chung, nhưng không luôn tốt hơn cho tiến trình con cục bộ.\n- **HTTP polling against the MCP server, treating HTTP as a substitute for the standard MCP communication patterns.**: Polling điểm HTTP không thay thế việc triển khai đúng transport và thông điệp MCP.\n\n**Cần xem lại:** Phần đề ghi ACP còn lựa chọn và khóa mô tả MCP. Giữ nguyên nguồn nhưng cần xác nhận giao thức được hỏi trước khi xuất bản.\n\n**Tham khảo:**\n\n- [MCP architecture — Transport layer](%5C%22https%3A//modelcontextprotocol.io/docs/learn/architecture%5C%22)", "references": [{"title": "MCP architecture — Transport layer", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//modelcontextprotocol.io/docs/learn/architecture%5C%22"}]}, {"no": 75, "id": 1190, "type": "single", "select": 1, "question": "Your Claude application's API keys are stored in a secrets manager. \n\nThe team is debating whether the same key should be used in development, staging, and production environments. \n\nHow would you handle the keys across environments?", "imageMissing": false, "options": [{"key": "A", "text": "Use a single development key everywhere on the grounds that production keys are too risky to deploy across the application's three environments during normal operation."}, {"key": "B", "text": "Use distinct keys for each environment so a compromise in one environment does not affect the others during normal operation across the application's lifecycle."}, {"key": "C", "text": "Rotate the same key across environments at random intervals on the grounds that random rotation provides isolation between environments without requiring distinct keys."}, {"key": "D", "text": "Use the same key across all environments for simplicity and treat the propagation of any compromise as a known operational tradeoff for the team's key management approach."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use distinct keys for each environment so a compromise in one environment does not affect the others during normal operation across the application's lifecycle.\n\nKey riêng từng môi trường cô lập quyền, quota và tác động khi lộ dev key khỏi production; vẫn cần quản lý rotate/revoke.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Rotate the same key across environments at random intervals on the grounds that random rotation provides isolation between environments without requiring distinct keys.**: Rotate cùng key không tạo ranh giới đồng thời giữa môi trường.\n- **Use the same key across all environments for simplicity and treat the propagation of any compromise as a known operational tradeoff for the team's key management approach.**: Chấp nhận lan lộ key không đáp ứng mục tiêu cô lập.\n- **Use a single development key everywhere on the grounds that production keys are too risky to deploy across the application's three environments during normal operation.**: Dùng dev key ở production vẫn chia sẻ cùng bí mật và có thể sai quyền.\n\n**Tham khảo:**\n\n- [Official Anthropic Python SDK](https://github.com/anthropics/anthropic-sdk-python)", "references": [{"title": "Official Anthropic Python SDK", "url": "https://github.com/anthropics/anthropic-sdk-python"}]}, {"no": 76, "id": 1191, "type": "single", "select": 1, "question": "You are explaining to a stakeholder why running the same Claude prompt twice can produce slightly different results. \n\nThe stakeholder is concerned this means the application is broken. \n\nHow would you address the stakeholder's concern?", "imageMissing": false, "options": [{"key": "A", "text": "Tell the stakeholder the variation is a bug that the team will fix in the next release of the application, then create a work ticket to fix the bug."}, {"key": "B", "text": "Tell the stakeholder the variation comes from network latency and that switching to a faster network connection will produce more consistent results across runs."}, {"key": "C", "text": "Tell the stakeholder the variation is caused by Claude being updated continuously by Anthropic, and that switching to a fixed model snapshot will eliminate the variation entirely"}, {"key": "D", "text": "Explain that LLMs are non-deterministic by default due to sampling, and describe how the application handles this through validation, retries, or temperature adjustment."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Explain that LLMs are non-deterministic by default due to sampling, and describe how the application handles this through validation, retries, or temperature adjustment.\n\nSampling khiến cùng prompt có thể cho wording khác; ứng dụng nên validate tiêu chí, retry có giới hạn và điều chỉnh tham số hỗ trợ, không hứa tuyệt đối deterministic.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Tell the stakeholder the variation is a bug that the team will fix in the next release of the application, then create a work ticket to fix the bug.**: Wording khác không tự chứng minh bug để hứa sửa.\n- **Tell the stakeholder the variation comes from network latency and that switching to a faster network connection will produce more consistent results across runs.**: Độ trễ mạng không quyết định token sampling như mô tả.\n- **Tell the stakeholder the variation is caused by Claude being updated continuously by Anthropic, and that switching to a fixed model snapshot will eliminate the variation entirely**: Snapshot cố định không loại toàn bộ biến thiên sampling.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}]}, {"no": 77, "id": 1192, "type": "single", "select": 1, "question": "The product team has asked you to choose a Claude model for a new feature. \n\nThe team has provided functional requirements but has not specified performance, cost, or quality targets. \n\nThe team's product manager says, \"Use whatever model gives us the best results.\" \n\nHow would you respond?", "imageMissing": false, "options": [{"key": "A", "text": "Run every Claude model on a representative sample and pick whichever scores best on a generic benchmark."}, {"key": "B", "text": "Ask the product team to specify quality, latency, and cost targets, then select the model whose tradeoffs best fit those targets."}, {"key": "C", "text": "Choose a mid-tier model and ship the feature, because mid-tier models work for most use cases without specified targets."}, {"key": "D", "text": "Choose the largest, highest-capability Claude model, on the grounds that \"best results\" is most likely to mean highest quality."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Ask the product team to specify quality, latency, and cost targets, then select the model whose tradeoffs best fit those targets.\n\nQuality, latency và cost targets định nghĩa trade-off để eval chọn model phù hợp nhu cầu thực thay vì “best” chung chung.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Run every Claude model on a representative sample and pick whichever scores best on a generic benchmark.**: Benchmark chung có thể không đo task và constraint sản phẩm.\n- **Choose a mid-tier model and ship the feature, because mid-tier models work for most use cases without specified targets.**: Mid-tier mặc định không chứng minh đạt target chưa có.\n- **Choose the largest, highest-capability Claude model, on the grounds that \"best results\" is most likely to mean highest quality.**: Model lớn nhất có thể không đáp ứng chi phí hoặc độ trễ.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 78, "id": 1193, "type": "single", "select": 1, "question": "Your Claude application is deployed to development, staging, and production environments. \n\nEach environment uses a different model version, different prompt versions, and different plugin dependencies, but the configuration is currently scattered across environment variables, hardcoded values, and undocumented setup scripts. \n\nHow would you manage the configuration?", "imageMissing": false, "options": [{"key": "A", "text": "Move all configuration into hardcoded application code to reduce reliance on external configuration sources that are difficult to track over time."}, {"key": "B", "text": "Use the latest available model version everywhere and stop pinning model versions, on the grounds that pinning adds maintenance overhead the team should aim to reduce."}, {"key": "C", "text": "Standardize all environments to use the same configuration values to eliminate the differences betweendevelopment, staging, and production."}, {"key": "D", "text": "Consolidate the configuration into a version-controlled system documenting model version pinning, prompt versioning, and plugin dependencies for each environment."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Consolidate the configuration into a version-controlled system documenting model version pinning, prompt versioning, and plugin dependencies for each environment.\n\nNguồn config versioned ghi rõ model/prompt/plugin từng môi trường giúp tái hiện, so drift và review rollout mà vẫn giữ khác biệt cần thiết.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Use the latest available model version everywhere and stop pinning model versions, on the grounds that pinning adds maintenance overhead the team should aim to reduce.**: Luôn latest mất bản cụ thể để tái hiện regression.\n- **Move all configuration into hardcoded application code to reduce reliance on external configuration sources that are difficult to track over time.**: Hardcode mọi config làm khó thay môi trường và không tự giải quyết tracking.\n- **Standardize all environments to use the same configuration values to eliminate the differences betweendevelopment, staging, and production.**: Mọi môi trường giống hệt có thể trái nhu cầu test/pilot và quyền riêng.\n\n**Tham khảo:**\n\n- [Claude Code settings](https://code.claude.com/docs/en/settings)\n- [Claude Code best practices](https://code.claude.com/docs/en/best-practices)", "references": [{"title": "Claude Code settings", "url": "https://code.claude.com/docs/en/settings"}, {"title": "Claude Code best practices", "url": "https://code.claude.com/docs/en/best-practices"}]}, {"no": 79, "id": 1194, "type": "single", "select": 1, "question": "You are designing a Claude application that will require structured JSON output for downstream processing. \n\nThe output schema is well-defined, and downstream systems will reject malformed JSON. \n\nYour application design would ...", "imageMissing": false, "options": [{"key": "A", "text": "avoid structured output and use free-form text everywhere instead, on the grounds that free-form text is more flexible and handles edge cases better than structured schemas."}, {"key": "B", "text": "define a clear schema and structure the prompt to request output in that schema, with downstream systems handling any validation needed."}, {"key": "C", "text": "define a clear schema, structure the prompt to request output in that schema, and validate Claude's output against the schema before passing it downstream."}, {"key": "D", "text": "structure the prompt to request output in a schema that is described in plain English, with downstream systems parsing whatever shape Claude produces."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** define a clear schema, structure the prompt to request output in that schema, and validate Claude's output against the schema before passing it downstream.\n\nDùng schema rõ ràng và kiểm tra dữ liệu trước khi chuyển cho hệ thống sau. Structured output ràng buộc lúc sinh; kiểm tra trong ứng dụng bảo vệ điểm tiếp nhận.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **avoid structured output and use free-form text everywhere instead, on the grounds that free-form text is more flexible and handles edge cases better than structured schemas.**: Văn bản tự do không đáp ứng giao diện dữ liệu.\n- **structure the prompt to request output in a schema that is described in plain English, with downstream systems parsing whatever shape Claude produces.**: Mô tả schema mơ hồ rồi nhận mọi dạng dữ liệu không giữ hợp đồng.\n- **define a clear schema and structure the prompt to request output in that schema, with downstream systems handling any validation needed.**: Đẩy toàn bộ kiểm tra cho phía sau bỏ mất chốt bảo vệ trước khi chuyển.\n\n**Tham khảo:**\n\n- [platform.claude.com — structured-outputs](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/structured-outputs%5C%22)", "references": [{"title": "platform.claude.com — structured-outputs", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/structured-outputs%5C%22"}]}, {"no": 80, "id": 1195, "type": "single", "select": 1, "question": "You are designing a Claude application that will process customer support tickets in two stages: a triage stage that classifies tickets and a response stage that drafts replies. \n\nThe team is debating whether to use a single Claude call that handles both stages or separate Claude calls for each stage. \n\nHow would you structure the application?", "imageMissing": false, "options": [{"key": "A", "text": "Use separate Claude calls for triage and response, because each stage has distinct inputs, outputs, and success criteria that benefit from focused prompts."}, {"key": "B", "text": "Use a single Claude call for both stages, on the grounds that a single call is cheaper than multiple calls in any production Claude application setup."}, {"key": "C", "text": "Use multiple Claude calls in parallel that each draft a complete ticket reply, then have a fourth Claude call select the best one to send to the customer."}, {"key": "D", "text": "Use a single Claude call for triage and then use a non-Claude rule-based system for response generation, on the grounds that rule-based systems are more reliable for drafting replies."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use separate Claude calls for triage and response, because each stage has distinct inputs, outputs, and success criteria that benefit from focused prompts.\n\nTriage và drafting có input/output và tiêu chí khác; tách call giúp validate classification trước khi dùng nó chọn hướng trả lời.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Use a single Claude call for triage and then use a non-Claude rule-based system for response generation, on the grounds that rule-based systems are more reliable for drafting replies.**: Rule-based drafting chưa được chứng minh phù hợp và không giải quyết trực tiếp phân tách hai bước Claude.\n- **Use multiple Claude calls in parallel that each draft a complete ticket reply, then have a fourth Claude call select the best one to send to the customer.**: Nhiều complete replies song song là voting/evaluation, không tách triage rồi response.\n- **Use a single Claude call for both stages, on the grounds that a single call is cheaper than multiple calls in any production Claude application setup.**: Một call không luôn rẻ hơn khi prompt phức tạp hoặc lỗi phải sửa; không thay tiêu chí thiết kế.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}]}, {"no": 81, "id": 1196, "type": "single", "select": 1, "question": "A new agent your team built handles customer support tickets, but it routinely gets confused when a single ticket spans billing, shipping, and product issues. \n\nThe agent often loses track of which sub-issue it has already addressed and revisits the same one. \n\nThe team is considering architectural changes. \n\nWhat architectural change would you recommend?", "imageMissing": false, "options": [{"key": "A", "text": "Add detailed prompting that instructs the agent to track which sub-issues have been resolved and which remain."}, {"key": "B", "text": "Increase the size of the agent's context window so it can hold the full ticket history at once."}, {"key": "C", "text": "Introduce an orchestrator agent that delegates billing, shipping, and product sub-issues to dedicated subagents."}, {"key": "D", "text": "Switch to a deterministic workflow that handles billing, shipping, and product issues in a fixed sequence."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Introduce an orchestrator agent that delegates billing, shipping, and product sub-issues to dedicated subagents.\n\nOrchestrator tách billing/shipping/product cho chuyên gia, giữ trạng thái sub-issue rồi tổng hợp để giảm quay lại việc đã xử lý.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Switch to a deterministic workflow that handles billing, shipping, and product issues in a fixed sequence.**: Chuỗi cứng mọi chủ đề có thể chạy bước không cần và khó linh hoạt theo ticket.\n- **Add detailed prompting that instructs the agent to track which sub-issues have been resolved and which remain.**: Prompt tracking có thể giúp nhưng không tạo sự phân chia trách nhiệm khi hệ thống đang lẫn nhiều miền.\n- **Increase the size of the agent's context window so it can hold the full ticket history at once.**: Context lớn không tự tạo task state hoặc phân biệt nhánh đã hoàn tất.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}, {"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 82, "id": 1197, "type": "single", "select": 1, "question": "Your Claude agent's hooks are currently triggered for every action, which slows down the agent significantly ven when actions pose no risk. \n\nThe team wants to scope hooks more carefully. \n\nHow would you scope the hooks?", "imageMissing": false, "options": [{"key": "A", "text": "Scope hooks to only the high-risk actions, such as destructive operations or sensitive data access, and remove hooks from low-risk actions to balance safety with performance."}, {"key": "B", "text": "Replace hooks with system prompt instructions on the grounds that prompt instructions can produce the same enforcement effect that hooks produce on the agent's actions."}, {"key": "C", "text": "Disable the agent during peak hours so the hook overhead does not slow the application down during the busiest periods of the day across the application's operation."}, {"key": "D", "text": "Disable all hooks while the team re-scopes them, treating the period of no hook enforcement as a temporary state during the re-scoping work."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Scope hooks to only the high-risk actions, such as destructive operations or sensitive data access, and remove hooks from low-risk actions to balance safety with performance.\n\nMatcher hook theo loại hành động rủi ro giảm chạy kiểm tra không cần trong khi vẫn cưỡng chế nơi có phá hủy hoặc dữ liệu nhạy cảm; phải giữ kiểm soát bắt buộc.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Disable all hooks while the team re-scopes them, treating the period of no hook enforcement as a temporary state during the re-scoping work.**: Tắt toàn bộ tạo khoảng trống enforcement.\n- **Disable the agent during peak hours so the hook overhead does not slow the application down during the busiest periods of the day across the application's operation.**: Tắt agent giờ cao điểm không xử lý hook scope.\n- **Replace hooks with system prompt instructions on the grounds that prompt instructions can produce the same enforcement effect that hooks produce on the agent's actions.**: Prompt không có cùng hiệu lực cưỡng chế như hook code.\n\n**Tham khảo:**\n\n- [Claude Code hooks reference](https://code.claude.com/docs/en/hooks)", "references": [{"title": "Claude Code hooks reference", "url": "https://code.claude.com/docs/en/hooks"}]}, {"no": 83, "id": 1198, "type": "single", "select": 1, "question": "You are designing a Claude application that processes user-submitted text. \n\nSome of that text could include sensitive information such as account numbers or passwords that the application should not send to Claude. \n\nHow would you design the application?", "imageMissing": false, "options": [{"key": "A", "text": "Define the application boundary explicitly, identify what content can leave the boundary for Claude, and add filtering or redaction at the boundary."}, {"key": "B", "text": "Add a prompt instruction in the system prompt specifying the categories of sensitive information Claude should disregard when processing user-submitted text."}, {"key": "C", "text": "Log all user-submitted text before it is sent to Claude and review the logs periodically to identify whether sensitive information is reaching the model."}, {"key": "D", "text": "Apply filtering at the boundary for the most commonly observed sensitive data patterns and expand coverage to additional patterns based on findings from production monitoring."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Define the application boundary explicitly, identify what content can leave the boundary for Claude, and add filtering or redaction at the boundary.\n\nXác định dữ liệu được phép rời boundary rồi lọc/redact trước gửi ngăn secret vào prompt ngay từ nguồn, không trông chờ model bỏ qua sau khi nhận.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Add a prompt instruction in the system prompt specifying the categories of sensitive information Claude should disregard when processing user-submitted text.**: Model bỏ qua vẫn có nghĩa dữ liệu đã được gửi ra ngoài.\n- **Log all user-submitted text before it is sent to Claude and review the logs periodically to identify whether sensitive information is reaching the model.**: Log đầy đủ tạo bản sao nhạy cảm và chỉ phát hiện sau sự kiện.\n- **Apply filtering at the boundary for the most commonly observed sensitive data patterns and expand coverage to additional patterns based on findings from production monitoring.**: Chỉ pattern thường gặp thiếu ranh giới rõ cho dữ liệu chưa quan sát.\n\n**Tham khảo:**\n\n- [Mitigate prompt injection](https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks)\n- [Securely deploying AI agents](https://code.claude.com/docs/en/agent-sdk/secure-deployment)", "references": [{"title": "Mitigate prompt injection", "url": "https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks"}, {"title": "Securely deploying AI agents", "url": "https://code.claude.com/docs/en/agent-sdk/secure-deployment"}]}, {"no": 84, "id": 1199, "type": "single", "select": 1, "question": "Your Claude application runs long agentic workflows where the agent makes many tool calls, and the conversation history grows quickly. \n\nAfter about 20 tool calls, you notice the agent's responses become less focused and sometimes ignore earlier task constraints. \n\nHow would you address this?", "imageMissing": false, "options": [{"key": "A", "text": "Increase the model's context window so the agent can hold every tool output at full detail across the entire workflow no matter how many tool calls it accumulates."}, {"key": "B", "text": "Restart the agent every five tool calls to prevent any drift, with the agent losing all task state at each restart point during the workflow."}, {"key": "C", "text": "Remove tool calling from the workflow entirely so the agent operates as a single text-generation step with no tool outputs accumulating in the context window."}, {"key": "D", "text": "Apply context engineering techniques such as tool output pruning or compaction to keep the active task state visible while reducing the volume of older content."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Apply context engineering techniques such as tool output pruning or compaction to keep the active task state visible while reducing the volume of older content.\n\nPruning/compaction giảm output cũ nhưng giữ mục tiêu, constraint và kết quả đang dùng để tác vụ dài không lạc hướng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Remove tool calling from the workflow entirely so the agent operates as a single text-generation step with no tool outputs accumulating in the context window.**: Bỏ tools làm mất khả năng thực hiện workflow cần dữ liệu/hành động.\n- **Increase the model's context window so the agent can hold every tool output at full detail across the entire workflow no matter how many tool calls it accumulates.**: Context lớn không vô hạn và không bảo đảm chú ý mọi constraint.\n- **Restart the agent every five tool calls to prevent any drift, with the agent losing all task state at each restart point during the workflow.**: Restart mất state mỗi năm call phá tính liên tục.\n\n**Tham khảo:**\n\n- [Effective context engineering](https://www.anthropic.com/research/effective-context-engineering-for-ai-agents)", "references": [{"title": "Effective context engineering", "url": "https://www.anthropic.com/research/effective-context-engineering-for-ai-agents"}]}, {"no": 85, "id": 1200, "type": "single", "select": 1, "question": "You are designing an agent that handles a complex claim-processing workflow. \n\nEach claim moves through fact extraction, eligibility evaluation, and a decision step. \n\nThe three subtasks have distinct success criteria, and some claims require iteration between fact extraction and eligibility evaluation before a decision can be reached. \n\nWhich agent pattern would you apply?", "imageMissing": false, "options": [{"key": "A", "text": "A graph-based pattern that lets the agent move between subtasks based on the state of each claim, with each subtask evaluated against its own criteria."}, {"key": "B", "text": "A streaming pattern that emits partial decisions as the agent processes each claim, refining the output until a final decision emerges from the stream."}, {"key": "C", "text": "A single tool-use loop pattern that gives one agent access to all the tools needed for fact extraction, eligibility evaluation, and decision-making."}, {"key": "D", "text": "A linear chain pattern that processes every claim through fact extraction, then eligibility evaluation, then decision, with no return paths between subtasks."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A graph-based pattern that lets the agent move between subtasks based on the state of each claim, with each subtask evaluated against its own criteria.\n\nGraph theo state cho phép quay từ eligibility về fact extraction khi thiếu bằng chứng, đồng thời mỗi node có tiêu chí riêng trước decision.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A streaming pattern that emits partial decisions as the agent processes each claim, refining the output until a final decision emerges from the stream.**: Streaming là cơ chế truyền output, không định nghĩa dependency hoặc back edge.\n- **A single tool-use loop pattern that gives one agent access to all the tools needed for fact extraction, eligibility evaluation, and decision-making.**: Loop chung có thể làm được nhưng không biểu diễn rõ gate riêng từng subtask như graph.\n- **A linear chain pattern that processes every claim through fact extraction, then eligibility evaluation, then decision, with no return paths between subtasks.**: Linear chain không có đường quay lại nên trái yêu cầu iteration.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}]}, {"no": 86, "id": 1201, "type": "single", "select": 1, "question": "Your enterprise has a contract with AWS that requires Claude API calls to flow through Amazon Bedrock rather lan the direct Anthropic API. \n\nYour team is building a new Claude application and is unfamiliar with this constraint. \n\nHow would you build the application?", "imageMissing": false, "options": [{"key": "A", "text": "Build two parallel implementations of every call, one for the direct Anthropic API and one for Bedrock, and pick the faster one at runtime."}, {"key": "B", "text": "Build the application against the direct Anthropic API and ignore the contractual requirement to route Claude calls through Amazon Bedrock."}, {"key": "C", "text": "Build the application against the direct Anthropic API now and migrate to Bedrock in a follow-up release once the team has more experience with the Bedrock API."}, {"key": "D", "text": "Configure the application to invoke Claude through the Bedrock-compatible API path while keeping the application's logic provider-agnostic."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Configure the application to invoke Claude through the Bedrock-compatible API path while keeping the application's logic provider-agnostic.\n\nDùng đường API Bedrock đáp ứng hợp đồng định tuyến, còn cô lập logic nghiệp vụ khỏi adapter giảm phụ thuộc provider.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Build two parallel implementations of every call, one for the direct Anthropic API and one for Bedrock, and pick the faster one at runtime.**: Chọn nhanh nhất runtime có thể gọi direct API trái hợp đồng.\n- **Build the application against the direct Anthropic API now and migrate to Bedrock in a follow-up release once the team has more experience with the Bedrock API.**: Migrate sau vẫn vi phạm trong giai đoạn đầu.\n- **Build the application against the direct Anthropic API and ignore the contractual requirement to route Claude calls through Amazon Bedrock.**: Bỏ qua constraint hợp đồng không phải quyết định triển khai hợp lệ.\n\n**Tham khảo:**\n\n- [Claude on Amazon Bedrock](https://platform.claude.com/docs/en/build-with-claude/claude-on-amazon-bedrock-legacy)", "references": [{"title": "Claude on Amazon Bedrock", "url": "https://platform.claude.com/docs/en/build-with-claude/claude-on-amazon-bedrock-legacy"}]}, {"no": 87, "id": 1202, "type": "single", "select": 1, "question": "Your Claude application has been running for several conversation turns, and you notice the model occasionally references information that was discussed many turns ago but is no longer relevant. \n\nYou suspect context drift is causing the model to weight stale content too heavily. \n\nHow would you address the drift?", "imageMissing": false, "options": [{"key": "A", "text": "Apply compaction to summarize older portions of the conversation so the gist remains while the specifics carry less weight."}, {"key": "B", "text": "Reset the conversation after every turn so the model loses all prior turns when generating a response."}, {"key": "C", "text": "Truncate the conversation so the model sees only the most recent turn during each subsequent response."}, {"key": "D", "text": "Increase the context window size so all turns of the conversation remain visible to the model in full detail."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Apply compaction to summarize older portions of the conversation so the gist remains while the specifics carry less weight.\n\nCompaction giữ ý chính cần thiết nhưng giảm chi tiết cũ không liên quan; summary phải bảo toàn mục tiêu và quyết định còn hiệu lực.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Increase the context window size so all turns of the conversation remain visible to the model in full detail.**: Cửa sổ lớn giữ thêm stale content, không trực tiếp giảm trọng số nhiễu.\n- **Reset the conversation after every turn so the model loses all prior turns when generating a response.**: Reset mọi lượt mất liên tục hội thoại.\n- **Truncate the conversation so the model sees only the most recent turn during each subsequent response.**: Chỉ turn mới nhất làm mất constraint cũ còn hiệu lực.\n\n**Tham khảo:**\n\n- [Effective context engineering](https://www.anthropic.com/research/effective-context-engineering-for-ai-agents)", "references": [{"title": "Effective context engineering", "url": "https://www.anthropic.com/research/effective-context-engineering-for-ai-agents"}]}, {"no": 88, "id": 1203, "type": "single", "select": 1, "question": "You are building a Claude application that needs to maintain a persistent connection to a service that streams real- time updates. \n\nThe team is unsure what communication pattern to use.\n\nWhich communication pattern would you use?", "imageMissing": false, "options": [{"key": "A", "text": "A WebSocket, because WebSockets are designed for bidirectional, persistent, real-time communication between the client and the streaming service."}, {"key": "B", "text": "A single long HTTP request the server holds open indefinitely, with no standard WebSocket framing on the connection."}, {"key": "C", "text": "File-based communication where the service writes new updates to disk and the application polls the file system for changes."}, {"key": "D", "text": "Repeated short-lived HTTP polling requests, where the application opens a new HTTP connection each time it checks for updates."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A WebSocket, because WebSockets are designed for bidirectional, persistent, real-time communication between the client and the streaming service.\n\nWebSocket cung cấp kênh bền vững hai chiều nên phù hợp khi ứng dụng cần vừa nhận cập nhật vừa gửi thông điệp theo cùng kênh. Tuy nhiên đề chỉ nói nhận cập nhật thời gian thực: luồng sự kiện HTTP một chiều cũng có thể đáp ứng. Khóa WebSocket hợp lý nhưng chưa duy nhất nếu không có yêu cầu hai chiều.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Repeated short-lived HTTP polling requests, where the application opens a new HTTP connection each time it checks for updates.**: Polling lặp tạo các lượt kiểm tra rời và overhead request thay vì luồng cập nhật mở liên tục được yêu cầu.\n- **A single long HTTP request the server holds open indefinitely, with no standard WebSocket framing on the connection.**: HTTP giữ mở có thể triển khai streaming một chiều hợp lệ như SSE; không có frame WebSocket chưa đủ khiến nó không phù hợp.\n- **File-based communication where the service writes new updates to disk and the application polls the file system for changes.**: Polling hệ thống file thêm phối hợp lưu trữ và không tạo kết nối dịch vụ bền vững trực tiếp.\n\n**Cần xem lại:** Cần làm rõ có yêu cầu gửi nhận hai chiều không. Cập nhật liên tục từ server đến client có thể dùng HTTP streaming/SSE nên cách viết hiện tại chưa chọn duy nhất WebSocket.\n\n**Tham khảo:**\n\n- [RFC 6455 — The WebSocket Protocol](%5C%22https%3A//www.rfc-editor.org/rfc/rfc6455%5C%22)\n- [Claude streaming messages — SSE](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/streaming%5C%22)", "references": [{"title": "RFC 6455 — The WebSocket Protocol", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//www.rfc-editor.org/rfc/rfc6455%5C%22"}, {"title": "Claude streaming messages — SSE", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/streaming%5C%22"}]}, {"no": 89, "id": 1204, "type": "single", "select": 1, "question": "A teammate has asked how the Claude SDK handles transient API errors, such as a temporary network issue or a brief rate-limit response. \n\nThey want to know whether the application code needs to handle every transient error or whether the SDK provides any default behavior. \n\nHow would you describe the SDK's default behavior?", "imageMissing": false, "options": [{"key": "A", "text": "The SDK logs transient errors to a default error stream and continues execution without retrying, leaving the application code responsible for detecting and responding to failed calls."}, {"key": "B", "text": "The SDK provides default retry behavior for transient errors up to a fixed number of attempts, and this behavior is not configurable."}, {"key": "C", "text": "The SDK provides default retry behavior for many transient errors, and the application code can configure or extend that behavior as needed."}, {"key": "D", "text": "The SDK provides default retry behavior for network errors but surfaces rate-limit responses directly to the application code, which must implement its own retry logic for those cases."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** The SDK provides default retry behavior for many transient errors, and the application code can configure or extend that behavior as needed.\n\nSDK có retry mặc định cho nhiều lỗi tạm thời và cho cấu hình max_retries; app vẫn cần xử lý exhausted retries và lỗi không retry được.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **The SDK provides default retry behavior for transient errors up to a fixed number of attempts, and this behavior is not configurable.**: Số lần retry có thể cấu hình, không cố định bất biến.\n- **The SDK provides default retry behavior for network errors but surfaces rate-limit responses directly to the application code, which must implement its own retry logic for those cases.**: Rate-limit responses nằm trong nhóm có thể retry theo SDK, không luôn chuyển ngay không thử.\n- **The SDK logs transient errors to a default error stream and continues execution without retrying, leaving the application code responsible for detecting and responding to failed calls.**: Log rồi tiếp tục không mô tả retry behavior của SDK.\n\n**Tham khảo:**\n\n- [Official Anthropic Python SDK](https://github.com/anthropics/anthropic-sdk-python)", "references": [{"title": "Official Anthropic Python SDK", "url": "https://github.com/anthropics/anthropic-sdk-python"}]}, {"no": 90, "id": 1205, "type": "single", "select": 1, "question": "Your team is debating how to manage the prompts used in your Claude application. \n\nSome prompts are checked into the code repository, some live in a separate configuration file, and some are constructed inline at runtime. \n\nThe result is inconsistent, and a recent prompt change went out without code review. \n\nWhat steps would you take?", "imageMissing": false, "options": [{"key": "A", "text": "Establish a single source of truth for prompts but keep change review optional, allowing developers to update prompts directly when changes are urgent."}, {"key": "B", "text": "Establish a single source of truth for prompts, version-control them alongside code, and require code review for prompt changes."}, {"key": "C", "text": "Move all prompts out of version control to a separate spreadsheet that team members can edit freely as the application evolves over time."}, {"key": "D", "text": "Move all prompts to inline runtime construction so the team can update them quickly through a streamlined process outside the standard code review workflow."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Establish a single source of truth for prompts, version-control them alongside code, and require code review for prompt changes.\n\nMột nguồn prompt versioned và code review giúp truy nguyên thay đổi hành vi, rollback và tránh chỉnh prompt ngoài quy trình.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Move all prompts out of version control to a separate spreadsheet that team members can edit freely as the application evolves over time.**: Spreadsheet tự do ngoài version control mất review và lịch sử deploy rõ ràng.\n- **Move all prompts to inline runtime construction so the team can update them quickly through a streamlined process outside the standard code review workflow.**: Inline runtime để né review làm trầm trọng vấn đề.\n- **Establish a single source of truth for prompts but keep change review optional, allowing developers to update prompts directly when changes are urgent.**: Nguồn duy nhất nhưng review tùy chọn vẫn cho thay đổi chưa được đánh giá.\n\n**Tham khảo:**\n\n- [Claude Code best practices](https://code.claude.com/docs/en/best-practices)", "references": [{"title": "Claude Code best practices", "url": "https://code.claude.com/docs/en/best-practices"}]}, {"no": 91, "id": 1206, "type": "single", "select": 1, "question": "Your Claude application is hitting context window limits when processing long customer service transcripts. \n\nA junior developer suggests increasing the temperature parameter to fix the issue. \n\nHow would you respond?", "imageMissing": false, "options": [{"key": "A", "text": "Explain that temperature controls sampling randomness and is unrelated to context capacity, then address the context issue through summarization or chunking."}, {"key": "B", "text": "Increase the temperature parameter as the junior developer suggested and observe whether the context window issue resolves over the next several runs of the application in production."}, {"key": "C", "text": "Remove the system prompt entirely to make room for longer transcripts in each request, freeing up context window space the system prompt would otherwise consume."}, {"key": "D", "text": "Adjust the temperature parameter together with the max_tokens parameter, treating the combined adjustment as the team's mechanism for managing context window pressure during long-transcript processing."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Explain that temperature controls sampling randomness and is unrelated to context capacity, then address the context issue through summarization or chunking.\n\nTemperature ảnh hưởng độ ngẫu nhiên lấy mẫu nếu model được chọn hỗ trợ tham số đó; nó không tăng cửa sổ context. Hãy tóm tắt phần transcript cũ hoặc chia việc thành đoạn vừa giới hạn, đồng thời giữ dữ kiện cần thiết và chỉ dẫn tác vụ hiện tại. Cần tính cả token vào lẫn ra theo giới hạn thật của model.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Adjust the temperature parameter together with the max_tokens parameter, treating the combined adjustment as the team's mechanism for managing context window pressure during long-transcript processing.**: Đổi lấy mẫu và giới hạn đầu ra không bỏ bớt đầu vào quá lớn; tăng ngân sách đầu ra còn có thể giảm chỗ dành cho đầu vào trong tổng context.\n- **Remove the system prompt entirely to make room for longer transcripts in each request, freeing up context window space the system prompt would otherwise consume.**: Xóa toàn bộ system prompt làm mất quy tắc hành vi cần thiết và không phải chiến lược chung hợp lý để quản lý transcript.\n- **Increase the temperature parameter as the junior developer suggested and observe whether the context window issue resolves over the next several runs of the application in production.**: Thử tham số lấy mẫu không liên quan trên production không xử lý nguyên nhân giới hạn dung lượng context đã biết.\n\n**Tham khảo:**\n\n- [Claude context windows](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/context-windows%5C%22)\n- [Claude compaction overview](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/compaction%5C%22)", "references": [{"title": "Claude context windows", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/context-windows%5C%22"}, {"title": "Claude compaction overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/compaction%5C%22"}]}, {"no": 92, "id": 1207, "type": "single", "select": 1, "question": "You are integrating Claude into an application written in Python. \n\nThe Claude SDK provides a Python client that wraps the underlying REST API. \n\nHow would you integrate the SDK?", "imageMissing": false, "options": [{"key": "A", "text": "Skip the SDK and embed Claude calls in shell commands invoked from Python, so that the application runs the calls outside the main Python process."}, {"key": "B", "text": "Call the REST API directly with raw HTTP requests so the application avoids the SDK's abstraction between the application code and the API."}, {"key": "C", "text": "Use the Claude Python SDK and let it handle authentication, retries, and response parsing through its standard documented patterns for Python integrations."}, {"key": "D", "text": "Use a different LLM provider's SDK and translate the responses into Claude's API shape so the application can switch providers in the future."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use the Claude Python SDK and let it handle authentication, retries, and response parsing through its standard documented patterns for Python integrations.\n\nPython SDK chuẩn hóa auth, retry và parse response theo interface được tài liệu duy trì, giảm tự viết HTTP plumbing.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Call the REST API directly with raw HTTP requests so the application avoids the SDK's abstraction between the application code and the API.**: Raw HTTP vẫn hợp lệ nhưng đòi tự xử lý cơ chế SDK đã cung cấp, không phải lựa chọn đơn giản nhất ở đây.\n- **Use a different LLM provider's SDK and translate the responses into Claude's API shape so the application can switch providers in the future.**: SDK provider khác không tự tương thích schema Claude.\n- **Skip the SDK and embed Claude calls in shell commands invoked from Python, so that the application runs the calls outside the main Python process.**: Shelling out thêm process/quoting/error handling không cần cho Python integration.\n\n**Tham khảo:**\n\n- [Official Anthropic Python SDK](https://github.com/anthropics/anthropic-sdk-python)", "references": [{"title": "Official Anthropic Python SDK", "url": "https://github.com/anthropics/anthropic-sdk-python"}]}, {"no": 93, "id": 1208, "type": "single", "select": 1, "question": "Your Claude agent has access to a tool that retrieves customer records. \n\nA teammate has noticed that the agent occasionally calls the tool with arguments the schema does not declare, and the tool's downstream service returns an error each time. \n\nThe teammate proposes loosening the schema so the tool accepts whatever arguments the model produces. \n\nHow would you respond?", "imageMissing": false, "options": [{"key": "A", "text": "Keep the schema strict, validate arguments before dispatching, and return a structured error so the agent can retry."}, {"key": "B", "text": "Add a system prompt instruction telling the model to produce schema-conforming arguments, treating the prompt instruction as the primary mechanism for keeping the agent's tool calls valid."}, {"key": "C", "text": "Remove the schema entirely and rely on the downstream service to reject invalid calls, treating the downstream service as the team's primary enforcement layer."}, {"key": "D", "text": "Loosen the schema as the teammate proposed so the downstream service receives every call the agent makes during normal operation."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Keep the schema strict, validate arguments before dispatching, and return a structured error so the agent can retry.\n\nGiữ schema strict và validate trước dispatch bảo vệ contract backend; lỗi có cấu trúc chỉ rõ field sai để agent sửa thay vì cho tham số tùy ý.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Add a system prompt instruction telling the model to produce schema-conforming arguments, treating the prompt instruction as the primary mechanism for keeping the agent's tool calls valid.**: Prompt nên bổ trợ, không thay validation code.\n- **Remove the schema entirely and rely on the downstream service to reject invalid calls, treating the downstream service as the team's primary enforcement layer.**: Bỏ schema chuyển phát hiện lỗi xuống backend và mất hợp đồng tool.\n- **Loosen the schema as the teammate proposed so the downstream service receives every call the agent makes during normal operation.**: Nới schema cho mọi argument che lỗi model và có thể nhận dữ liệu backend không hiểu.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}]}, {"no": 94, "id": 1209, "type": "single", "select": 1, "question": "Your Claude application is producing inconsistent outputs for similar inputs, even when using the same model and prompt. \n\nYou want to debug the issue systematically. \n\nYour debugging approach would...", "imageMissing": false, "options": [{"key": "A", "text": "Assume inconsistent outputs reflect normal LLM non-determinism and document the variability as an accepted characteristic of the application's behavior."}, {"key": "B", "text": "Capture full traces of input, system prompt, user messages, model output, and parameters, then analyze the differences between consistent and inconsistent runs."}, {"key": "C", "text": "Lower the model's temperature and re-run the inconsistent inputs to determine whether the parameter change reduces output variability across runs."}, {"key": "D", "text": "Retry every request that produces an unexpected output and log the results to identify whether repeated calls converge on a consistent response pattern."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Capture full traces of input, system prompt, user messages, model output, and parameters, then analyze the differences between consistent and inconsistent runs.\n\nTrace input, system/user messages, model và tham số cho phép so biến thực giữa run tốt/xấu trước khi quy lỗi sampling hoặc đổi cấu hình.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Lower the model's temperature and re-run the inconsistent inputs to determine whether the parameter change reduces output variability across runs.**: Giảm temperature có thể là thử nghiệm sau khi ghi baseline, không thay chẩn đoán đầy đủ.\n- **Retry every request that produces an unexpected output and log the results to identify whether repeated calls converge on a consistent response pattern.**: Retry chỉ quan sát thêm mà chưa giữ đủ yếu tố để tìm nguyên nhân.\n- **Assume inconsistent outputs reflect normal LLM non-determinism and document the variability as an accepted characteristic of the application's behavior.**: Chấp nhận nondeterminism bỏ qua khả năng prompt/context/config khác ngoài ý muốn.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 95, "id": 1210, "type": "single", "select": 1, "question": "You are building an agent that needs to call several internal APIs and a database in a structured, repeatable way. \n\nYour team has decided to use the Claude Agent SDK rather than build a custom loop. \n\nYou are setting up the agent's tool definitions and execution loop. \n\nHow would you set up the tools and execution loop?", "imageMissing": false, "options": [{"key": "A", "text": "Call the Messages API directly and let the model format its tool calls in plain text."}, {"key": "B", "text": "Use the SDK's tool interface and write the loop and history layer in the team's own code."}, {"key": "C", "text": "Use the SDK's tool interface and let the SDK handle the loop, dispatch, and history."}, {"key": "D", "text": "Use the SDK's tool interface and loop, with conversation history stored in a separate team database."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use the SDK's tool interface and let the SDK handle the loop, dispatch, and history.\n\nAgent SDK quản lý loop, dispatch và conversation history theo interface tool chuẩn, đúng mục tiêu tránh viết custom loop.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Call the Messages API directly and let the model format its tool calls in plain text.**: Messages API cùng tool calls dạng text đòi tự parse và không dùng SDK loop đã chọn.\n- **Use the SDK's tool interface and loop, with conversation history stored in a separate team database.**: Database ngoài có thể dùng để persist nhưng không bắt buộc tách quản lý history ra để đạt yêu cầu.\n- **Use the SDK's tool interface and write the loop and history layer in the team's own code.**: Tự viết loop/history bỏ lợi ích chính team chọn SDK.\n\n**Tham khảo:**\n\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 96, "id": 1211, "type": "single", "select": 1, "question": "Your Claude application's token costs have grown faster than expected. \n\nThe team has not been tracking token usage by feature, so the team cannot identify which features are driving cost. \n\nThe team is debating how to respona. \n\nHow would you respond?", "imageMissing": false, "options": [{"key": "A", "text": "Reduce token usage uniformly across all features by half, applying the cut evenly across the application during normal operation."}, {"key": "B", "text": "Add token usage tracking by feature to the application's logging so the team can identify which features drive cost before recommending changes."}, {"key": "C", "text": "Tell the team that cost growth is unavoidable as the application scales and that no investigation will change the trajectory of the application's cost over the next several quarters."}, {"key": "D", "text": "Switch every feature to the smallest model to cut cost broadly across the application during normal operation."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add token usage tracking by feature to the application's logging so the team can identify which features drive cost before recommending changes.\n\nTheo dõi token theo feature gắn chi phí với tác vụ cụ thể để tối ưu nơi tốn nhiều trước, không cắt mù mọi tính năng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Tell the team that cost growth is unavoidable as the application scales and that no investigation will change the trajectory of the application's cost over the next several quarters.**: Tăng chi phí không tất yếu bất khả cải thiện; thiếu đo lường mới là vấn đề đầu.\n- **Switch every feature to the smallest model to cut cost broadly across the application during normal operation.**: Model nhỏ mọi nơi có thể làm hỏng chất lượng tính năng khó.\n- **Reduce token usage uniformly across all features by half, applying the cut evenly across the application during normal operation.**: Cắt đồng đều một nửa không căn cứ nhu cầu hoặc mức lãng phí từng feature.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 97, "id": 1212, "type": "single", "select": 1, "question": "Your Claude application produces good responses for typical inputs but struggles with edge cases. \n\nYou have several labeled examples of edge-case inputs and the desired response for each. \n\nYou want to use these examples to improve the model's handling of edge cases. \n\nWhat is the best way to use these examples?", "imageMissing": false, "options": [{"key": "A", "text": "Tell users to avoid submitting the edge-case inputs to the application by adding warnings in the application's user interface."}, {"key": "B", "text": "Train a custom model on the edge-case examples and deploy that custom model in place of the team's currentClaude integration."}, {"key": "C", "text": "Add the labeled edge-case examples to the prompt as few-shot examples so the model can learn the pattern."}, {"key": "D", "text": "Embed the examples in a database for the model to find during inference."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Add the labeled edge-case examples to the prompt as few-shot examples so the model can learn the pattern.\n\nFew-shot đưa case biên cùng output đúng vào prompt, cho thấy pattern quyết định ở những trường hợp model đang yếu.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Embed the examples in a database for the model to find during inference.**: Lưu embedding chưa bảo đảm ví dụ được truy xuất và đưa vào context.\n- **Train a custom model on the edge-case examples and deploy that custom model in place of the team's currentClaude integration.**: Train model riêng từ ít ví dụ là thay đổi lớn không cần trước khi thử prompt có eval.\n- **Tell users to avoid submitting the edge-case inputs to the application by adding warnings in the application's user interface.**: Cấm user gửi edge case bỏ nhu cầu thay vì cải thiện xử lý.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}]}, {"no": 98, "id": 1213, "type": "single", "select": 1, "question": "You have just shipped a new Claude-powered application to production. \n\nThe development phase is complete, and the system is now in active use by internal teams. \n\nThe next phase of work for this system is...", "imageMissing": false, "options": [{"key": "A", "text": "Operating and maintaining the system, including monitoring, responding to issues, and planning evolution."}, {"key": "B", "text": "Running a formal post-deployment review that assesses the development phase before the team does any further work on the system."}, {"key": "C", "text": "Retiring the system, since shipping is the final lifecycle stage for any application that reaches production."}, {"key": "D", "text": "Handing the system over to a separate operations team that will manage it independently of the development team going forward."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Operating and maintaining the system, including monitoring, responding to issues, and planning evolution.\n\nProduction mở giai đoạn vận hành: giám sát chất lượng, chi phí, sự cố và cập nhật theo dữ liệu thực, không kết thúc lifecycle.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Retiring the system, since shipping is the final lifecycle stage for any application that reaches production.**: Ship không có nghĩa retire hệ thống vừa đưa vào dùng.\n- **Running a formal post-deployment review that assesses the development phase before the team does any further work on the system.**: Post-deploy review có ích nhưng không cần chặn mọi hoạt động vận hành chờ một buổi review.\n- **Handing the system over to a separate operations team that will manage it independently of the development team going forward.**: Ops riêng là lựa chọn tổ chức, không điều kiện bắt buộc hoặc xóa trách nhiệm dev.\n\n**Tham khảo:**\n\n- [Define success criteria and evaluations](https://platform.claude.com/docs/en/test-and-evaluate/develop-tests)", "references": [{"title": "Define success criteria and evaluations", "url": "https://platform.claude.com/docs/en/test-and-evaluate/develop-tests"}]}, {"no": 99, "id": 1214, "type": "single", "select": 1, "question": "A teammate has asked how to extend Claude Code with a custom Skill that the team can invoke during sessions. \n\nThe Skill consists of a set of instructions and a few support scripts the team wants Claude to be able to call when the Skill is loaded. \n\nWhere is the right place to define the Skill?", "imageMissing": false, "options": [{"key": "A", "text": "Define the Skill as a long inline instruction at the top of every CLAUDE.md file in the team's repositories soClaude has access to it on every session."}, {"key": "B", "text": "Define the Skill in a Skills directory recognized by Claude Code, where Claude can discover and load it during sessions for the team's repositories."}, {"key": "C", "text": "Define the Skill in a personal scratch directory on each developer's machine and load it manually before eachClaude Code session that needs it."}, {"key": "D", "text": "Define the Skill inside the application's source code as a regular library module and call it from the application code instead of from Claude Code."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Define the Skill in a Skills directory recognized by Claude Code, where Claude can discover and load it during sessions for the team's repositories.\n\nSkill ở thư mục Claude Code nhận biết giúp discovery và load hướng dẫn/script theo phạm vi, tái sử dụng mà không chép vào mọi session.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Define the Skill as a long inline instruction at the top of every CLAUDE.md file in the team's repositories soClaude has access to it on every session.**: Nhét dài trong mọi CLAUDE.md làm luôn tải nội dung không cần và khó bảo trì.\n- **Define the Skill inside the application's source code as a regular library module and call it from the application code instead of from Claude Code.**: Library module là logic app, không cơ chế Skill được Claude Code tìm thấy.\n- **Define the Skill in a personal scratch directory on each developer's machine and load it manually before eachClaude Code session that needs it.**: Scratch riêng không chuẩn hóa discovery hoặc chia sẻ project.\n\n**Tham khảo:**\n\n- [Claude Code skills](https://code.claude.com/docs/en/skills)", "references": [{"title": "Claude Code skills", "url": "https://code.claude.com/docs/en/skills"}]}, {"no": 100, "id": 1215, "type": "single", "select": 1, "question": "The product team has described a new Claude feature in business terms: \"agents should help our analysts produce client memos faster.\" \n\nYou need to convert this into actionable technical requirements for the engineering team. \n\nYour first step would be to...", "imageMissing": false, "options": [{"key": "A", "text": "Interpret the functional and infrastructure requirements implied by the business goal."}, {"key": "B", "text": "Examine what model capabilities and tier options are available and determine which best supports the memo drafting workflow described by the product team."}, {"key": "C", "text": "Assess what similar agent-based features have been built internally or in the industry and use those precedents to scope the technical approach."}, {"key": "D", "text": "Ask the analysts about the current memo production process to see where they think Claude could be introduced as a prompt-driven drafting step."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Interpret the functional and infrastructure requirements implied by the business goal.\n\nChuyển mục tiêu viết memo nhanh hơn thành chức năng, dữ liệu vào/ra, tiêu chí chất lượng, phụ thuộc và ràng buộc hạ tầng trước khi chọn cách làm.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Ask the analysts about the current memo production process to see where they think Claude could be introduced as a prompt-driven drafting step.**: Hỏi người dùng hữu ích nhưng phương án đã giả định trước giải pháp soạn thảo bằng prompt.\n- **Assess what similar agent-based features have been built internally or in the industry and use those precedents to scope the technical approach.**: Tiền lệ không xác lập yêu cầu riêng của sản phẩm.\n- **Examine what model capabilities and tier options are available and determine which best supports the memo drafting workflow described by the product team.**: Chọn model trước làm đảo ngược trình tự thiết kế theo yêu cầu.\n\n**Tham khảo:**\n\n- [www.anthropic.com — building-effective-agents](%5C%22https%3A//www.anthropic.com/research/building-effective-agents%5C%22)", "references": [{"title": "www.anthropic.com — building-effective-agents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//www.anthropic.com/research/building-effective-agents%5C%22"}]}, {"no": 101, "id": 1292, "type": "single", "select": 1, "question": "A Claude application is occasionally refusing to answer questions that should be in scope, including questions the application has answered correctly in the past. \n\nYou want to investigate. \n\nWhat is the first step of your investigation?", "imageMissing": false, "options": [{"key": "A", "text": "Identify which questions have been refused and compare them against previously answered questions to determine what changed between the successful and refused interactions."}, {"key": "B", "text": "Test whether removing or adjusting those instructions resolves the behavior."}, {"key": "C", "text": "Assess whether the refusals cluster around specific input patterns, question types, or time periods by analyzing the distribution of refused requests in the logs."}, {"key": "D", "text": "Examine traces of the refused requests to identify what triggers the refusal, whether input patterns, system prompt content, or other context."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Identify which questions have been refused and compare them against previously answered questions to determine what changed between the successful and refused interactions.\n\nSo sánh lượt bị từ chối với lượt thành công để tìm thay đổi ở đầu vào, hướng dẫn, model hoặc ngữ cảnh. Bằng chứng này giúp khoanh vùng trước khi sửa.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Test whether removing or adjusting those instructions resolves the behavior.**: Sửa hướng dẫn chưa xác định là thay đổi trước khi tìm nguyên nhân.\n- **Assess whether the refusals cluster around specific input patterns, question types, or time periods by analyzing the distribution of refused requests in the logs.**: Phân tích phân bố hữu ích nhưng chưa so trực tiếp các lượt thành công và thất bại đã biết.\n- **Examine traces of the refused requests to identify what triggers the refusal, whether input patterns, system prompt content, or other context.**: Xem trace hữu ích; bước đầu được chọn thiết lập mốc so sánh cụ thể.\n\n**Tham khảo:**\n\n- [platform.claude.com — develop-tests](%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22)", "references": [{"title": "platform.claude.com — develop-tests", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22"}]}, {"no": 102, "id": 1216, "type": "single", "select": 1, "question": "You are designing an agent that handles a multi-step research task. \n\nYou want the agent to break the task into smaller pieces, hand each piece to a focused subagent, and consolidate the results. \n\nThe agent pattern you would apply is...", "imageMissing": false, "options": [{"key": "A", "text": "An orchestrator and subagent pattern with specialized subagents assigned to each subtask."}, {"key": "B", "text": "A context-window pruning pattern that drops each subtask's content after the agent moves on."}, {"key": "C", "text": "A memory pattern that stores the entire research history in advance, before any subtask begins execution."}, {"key": "D", "text": "A single tool-use loop that includes every tool the agent might need across all subtasks."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** An orchestrator and subagent pattern with specialized subagents assigned to each subtask.\n\nOrchestrator chia task cho chuyên gia rồi tổng hợp findings, đúng mô tả nhiều phần nghiên cứu có trách nhiệm riêng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A memory pattern that stores the entire research history in advance, before any subtask begins execution.**: Lưu toàn history trước không thực hiện phân chia và điều phối.\n- **A context-window pruning pattern that drops each subtask's content after the agent moves on.**: Pruning quản lý context, không phải pattern phân công subtask.\n- **A single tool-use loop that includes every tool the agent might need across all subtasks.**: Một loop mọi tool không tạo chuyên gia có context và trách nhiệm tách biệt.\n\n**Tham khảo:**\n\n- [Building effective agents](https://www.anthropic.com/research/building-effective-agents)\n- [Claude Agent SDK](https://code.claude.com/docs/en/agent-sdk/overview)", "references": [{"title": "Building effective agents", "url": "https://www.anthropic.com/research/building-effective-agents"}, {"title": "Claude Agent SDK", "url": "https://code.claude.com/docs/en/agent-sdk/overview"}]}, {"no": 103, "id": 1217, "type": "single", "select": 1, "question": "Your Claude application receives untrusted input from external sources. \n\nThe team is establishing how the application should treat this untrusted input. \n\nUntrusted input would be...", "imageMissing": false, "options": [{"key": "A", "text": "Routed through a separate Claude application with more lax security controls so the original application does not handle the untrusted input directly."}, {"key": "B", "text": "Validated and sanitized before being incorporated into prompts, and treated as data the model should not interpret as instructions."}, {"key": "C", "text": "Treated identically to trusted input from internal sources, on the grounds that all input the application receives can be handled the same way."}, {"key": "D", "text": "Blocked entirely so the application accepts only trusted input, with no path for legitimate external input the application might process."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Validated and sanitized before being incorporated into prompts, and treated as data the model should not interpret as instructions.\n\nValidate/sanitize và đặt external text ở vai trò dữ liệu giữ ranh giới tin cậy; cần kiểm soát tool/permission vì lọc text không bảo đảm hết injection.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Treated identically to trusted input from internal sources, on the grounds that all input the application receives can be handled the same way.**: Nguồn ngoài không có cùng độ tin cậy instruction nội bộ.\n- **Routed through a separate Claude application with more lax security controls so the original application does not handle the untrusted input directly.**: App có bảo vệ lỏng hơn tăng rủi ro thay vì cô lập an toàn.\n- **Blocked entirely so the application accepts only trusted input, with no path for legitimate external input the application might process.**: Chặn mọi nguồn ngoài bỏ cả use case hợp lệ khi có thể kiểm soát boundary.\n\n**Tham khảo:**\n\n- [Define tools](https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools)", "references": [{"title": "Define tools", "url": "https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools"}]}, {"no": 104, "id": 1218, "type": "single", "select": 1, "question": "Your Claude application's outputs are inconsistent in format. \n\nThe team's instructions are scattered across the system prompt and user messages, with some instructions stated only once and others repeated. \n\nHow would you fix the inconsistency?", "imageMissing": false, "options": [{"key": "A", "text": "Repeat all instructions in both the system prompt and the user message so the model sees each instruction more than once."}, {"key": "B", "text": "Consolidate behavioral and format instructions in the system prompt and keep user messages focused on the user's input."}, {"key": "C", "text": "Place each instruction wherever the developer who first wrote it found most natural, retaining the original intent."}, {"key": "D", "text": "Move all instructions into the user message so the application's behavior is controlled at the input point."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Consolidate behavioral and format instructions in the system prompt and keep user messages focused on the user's input.\n\nSystem prompt tập trung rule hành vi/format, user message chứa input giúp giảm hướng dẫn mâu thuẫn và phân biệt dữ liệu với chính sách; vẫn validate schema khi app cần.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Move all instructions into the user message so the application's behavior is controlled at the input point.**: Dồn rule vào user làm lẫn chính sách app với dữ liệu đầu vào.\n- **Place each instruction wherever the developer who first wrote it found most natural, retaining the original intent.**: Giữ chỗ viết ngẫu nhiên duy trì chính sự phân tán gây lỗi.\n- **Repeat all instructions in both the system prompt and the user message so the model sees each instruction more than once.**: Lặp mọi rule hai nơi làm tốn token và tăng khả năng lệch phiên bản.\n\n**Tham khảo:**\n\n- [Claude prompting best practices](https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices)", "references": [{"title": "Claude prompting best practices", "url": "https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"}]}, {"no": 105, "id": 1219, "type": "single", "select": 1, "question": "Your team uses Claude Code across multiple repositories. \n\nYou want the team's rules and general coding standards to apply to all repositories, and other rules to apply only to specific repositories. \n\nThe team is currently duplicating instructions across every repository's CLAUDE.md file. \n\nHow would you address this?", "imageMissing": false, "options": [{"key": "A", "text": "Use a CLAUDE.md hierarchy that scopes general standards broadly and project-specific context within each repository's local CLAUDE.md."}, {"key": "B", "text": "Stop using CLAUDE.md altogether and ask each developer to configure Claude Code manually for each project they work on."}, {"key": "C", "text": "Use a single repository's CLAUDE.md as the central source of truth and link to it from every other repository'sCLAUDE.md file."}, {"key": "D", "text": "Move all instructions to a separate documentation site that developers consult during Claude Code sessions across all repositories."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use a CLAUDE.md hierarchy that scopes general standards broadly and project-specific context within each repository's local CLAUDE.md.\n\nHierarchy CLAUDE.md đặt chuẩn chung ở phạm vi rộng, context project ở repo giúp tái sử dụng mà vẫn áp quy tắc đặc thù đúng nơi.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Move all instructions to a separate documentation site that developers consult during Claude Code sessions across all repositories.**: Website ngoài không tự được load theo scope repository.\n- **Stop using CLAUDE.md altogether and ask each developer to configure Claude Code manually for each project they work on.**: Tự cấu hình mỗi người làm mất nguồn chuẩn chia sẻ và review.\n- **Use a single repository's CLAUDE.md as the central source of truth and link to it from every other repository'sCLAUDE.md file.**: Link repo trung tâm có thể tham khảo nhưng không tự bằng hierarchy được client nhận biết.\n\n**Tham khảo:**\n\n- [Claude Code memory hierarchy](https://code.claude.com/docs/en/memory)", "references": [{"title": "Claude Code memory hierarchy", "url": "https://code.claude.com/docs/en/memory"}]}, {"no": 106, "id": 1290, "type": "single", "select": 1, "question": "You are running Claude Code as part of an automated continuous integration pipeline. \n\nThe pipeline needs Claude Code to execute a set of well-defined tasks without prompting for confirmation, and the output needs to be captured for downstream processing. \n\nHow would you configure the pipeline?", "imageMissing": false, "options": [{"key": "A", "text": "Disable Claude Code's confirmation prompts globally across all environments so the pipeline runs without interruption from any prompt."}, {"key": "B", "text": "Run Claude Code in interactive mode and have a developer manually approve every confirmation prompt while the pipeline executes its tasks."}, {"key": "C", "text": "Replace Claude Code with a different tool that does not require any configuration to operate without confirmation prompts in the pipeline."}, {"key": "D", "text": "Run Claude Code in headless mode with the required permissions configured in settings.json and capture its output for downstream processing."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Run Claude Code in headless mode with the required permissions configured in settings.json and capture its output for downstream processing.\n\nChế độ headless cùng quyền được cấu hình đúng phạm vi cho phép CI chạy không cần người duyệt và thu kết quả. Cần nạp đúng settings dự án; dùng định dạng máy đọc được khi cần.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Disable Claude Code's confirmation prompts globally across all environments so the pipeline runs without interruption from any prompt.**: Tắt quyền xác nhận toàn cục làm ảnh hưởng các môi trường không liên quan.\n- **Replace Claude Code with a different tool that does not require any configuration to operate without confirmation prompts in the pipeline.**: Đổi công cụ không giải quyết yêu cầu cấu hình đang có.\n- **Run Claude Code in interactive mode and have a developer manually approve every confirmation prompt while the pipeline executes its tasks.**: Duyệt thủ công trái với CI chạy tự động.\n\n**Tham khảo:**\n\n- [code.claude.com — permissions](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/permissions%5C%22)", "references": [{"title": "code.claude.com — permissions", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/permissions%5C%22"}]}, {"no": 107, "id": 1291, "type": "single", "select": 1, "question": "A teammate has asked you to explain why the team's Claude application is billed for output tokens at a different rate than input tokens. \n\nThey had assumed the rate was the same for both. How would you explain the difference?", "imageMissing": false, "options": [{"key": "A", "text": "Output tokens are typically billed at the same rate as input tokens, and the apparent rate difference is a billing error to report to Anthropic."}, {"key": "B", "text": "Output tokens are typically billed at a lower rate than input tokens, because output tokens are cheaper to produce than input tokens are to process."}, {"key": "C", "text": "Output tokens are not billed at all, because cost is determined entirely by the input tokens sent to the model on each request."}, {"key": "D", "text": "Output tokens are typically billed at a higher rate than input tokens, and cost models for the application should reflect both rates separately."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Output tokens are typically billed at a higher rate than input tokens, and cost models for the application should reflect both rates separately.\n\nTính riêng lượng token vào và ra nhân đơn giá tương ứng, rồi cộng lại. Token ra thường có giá cao hơn; cần dùng bảng giá của model thay vì giả định một đơn giá chung.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Output tokens are typically billed at the same rate as input tokens, and the apparent rate difference is a billing error to report to Anthropic.**: Đơn giá khác nhau là cấu phần bảng giá, không tự chứng minh lỗi tính phí.\n- **Output tokens are typically billed at a lower rate than input tokens, because output tokens are cheaper to produce than input tokens are to process.**: Token ra nhìn chung không rẻ hơn token vào.\n- **Output tokens are not billed at all, because cost is determined entirely by the input tokens sent to the model on each request.**: Token sinh ra có được tính phí.\n\n**Tham khảo:**\n\n- [platform.claude.com — overview](%5C%22https%3A//platform.claude.com/docs/en/models/overview%5C%22)", "references": [{"title": "platform.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/models/overview%5C%22"}]}, {"no": 108, "id": 1343, "type": "single", "select": 1, "question": "A small internal tool needs to read files, run shell commands, and search a codebase for a one-off refactor task using the Claude Agent SDK. \n\nNo external systems or custom domain logic are involved. \n\nWhat is the most appropriate starting point?", "imageMissing": false, "options": [{"key": "A", "text": "Connect an external MCP server that reimplements filesystem and shell access over a network protocol"}, {"key": "B", "text": "Write a Skill containing instructions for how to read files and run commands in place of built-in tools"}, {"key": "C", "text": "Build a custom tool for reading files and another for running shell commands before writing any code"}, {"key": "D", "text": "Use the SDK's built-in tools such as Read, Edit, Bash, Glob, and Grep without building any custom tools or MCP servers"}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Use the SDK's built-in tools such as Read, Edit, Bash, Glob, and Grep without building any custom tools or MCP servers\n\nBắt đầu bằng tool file, tìm kiếm và shell sẵn có vì đã đủ cho công việc. Chỉ thêm tích hợp riêng khi xuất hiện khả năng thực sự còn thiếu.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Build a custom tool for reading files and another for running shell commands before writing any code**: Tự viết lại tool file và shell là lặp khả năng đã được hỗ trợ.\n- **Connect an external MCP server that reimplements filesystem and shell access over a network protocol**: MCP từ xa thêm tầng mạng không cần cho việc cục bộ.\n- **Write a Skill containing instructions for how to read files and run commands in place of built-in tools**: Hướng dẫn trong Skill không thay thế tool thực hiện thao tác.\n\n**Tham khảo:**\n\n- [code.claude.com — overview](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22)", "references": [{"title": "code.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22"}]}, {"no": 109, "id": 1342, "type": "single", "select": 1, "question": "A fintech startup is building an internal support agent with the Claude Agent SDK. \n\nThe agent must look up account balances from a proprietary ledger service reachable only through an internal REST gateway with no existing MCP server or public SDK. \n\nWhich approach best fits this requirement?", "imageMissing": false, "options": [{"key": "A", "text": "Rely on the built-in WebFetch tool to query the gateway directly from the agent's prompt"}, {"key": "B", "text": "Write a Skill that documents the ledger schema and expects Claude to reason about balances from memory"}, {"key": "C", "text": "Define a custom tool that calls the internal REST gateway and register it through an in-process MCP server"}, {"key": "D", "text": "Search for a community MCP server that might expose a similar ledger balance capability"}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Define a custom tool that calls the internal REST gateway and register it through an in-process MCP server\n\nViết handler gọi REST có xác thực rồi cung cấp qua MCP server trong tiến trình. Model gọi tool đã định nghĩa; mã ứng dụng quản lý thông tin xác thực, kiểm tra dữ liệu và lỗi dịch vụ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Rely on the built-in WebFetch tool to query the gateway directly from the agent's prompt**: Lấy web chung chung không phải tích hợp sổ cái có xác thực theo nghiệp vụ.\n- **Write a Skill that documents the ledger schema and expects Claude to reason about balances from memory**: Tài liệu không cung cấp số dư trực tiếp từ trí nhớ.\n- **Search for a community MCP server that might expose a similar ledger balance capability**: Server cộng đồng tương tự chưa triển khai API thật của dịch vụ riêng này.\n\n**Tham khảo:**\n\n- [code.claude.com — custom-tools](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/custom-tools%5C%22)", "references": [{"title": "code.claude.com — custom-tools", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/custom-tools%5C%22"}]}, {"no": 110, "id": 1341, "type": "single", "select": 1, "question": "A team is building an automated agent using the Claude Agent SDK that runs unattended in a CI pipeline. \n\nIt needs to run a fixed set of tools (`Read`, `Grep`, `Bash(npm test)`) without any human available to approve prompts, and any tool call outside that fixed set must be rejected outright rather than hang waiting for approval. \n\nWhich configuration achieves this?", "imageMissing": false, "options": [{"key": "A", "text": "Set `permission_mode` to `bypassPermissions` and omit `allowed_tools` entirely, since bypass mode already restricts execution to a minimal safe tool set by default."}, {"key": "B", "text": "Set `permission_mode` to `default` and register a `canUseTool` callback that always throws an exception for tools outside the fixed set."}, {"key": "C", "text": "Set `allowed_tools` to the fixed set and `permission_mode` to `dontAsk`; listed tools run, and every other call is denied without invoking `canUseTool`."}, {"key": "D", "text": "Set `permission_mode` to `plan` and set `allowed_tools` to the fixed set, since plan mode auto-denies any tool call that is not explicitly pre-approved."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Set `allowed_tools` to the fixed set and `permission_mode` to `dontAsk`; listed tools run, and every other call is denied without invoking `canUseTool`.\n\nPhương án gần nhất kết hợp lời gọi được duyệt trước với dontAsk để từ chối lời gọi cần hỏi. Tuy nhiên allowed_tools là danh sách duyệt quyền trước, không phải danh sách duy nhất tool được thấy: một số lời gọi ngoài danh sách vốn không cần hỏi vẫn có thể chạy. Vì vậy phương án này chưa bảo đảm tuyệt đối như đề yêu cầu. Cần giới hạn tool được cung cấp hoặc thêm kiểm tra deny rõ ràng để cưỡng chế tập cố định.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Set `permission_mode` to `bypassPermissions` and omit `allowed_tools` entirely, since bypass mode already restricts execution to a minimal safe tool set by default.**: Bypass không tự giới hạn còn tập tool an toàn tối thiểu.\n- **Set `permission_mode` to `plan` and set `allowed_tools` to the fixed set, since plan mode auto-denies any tool call that is not explicitly pre-approved.**: Plan mode không phải chính sách thực thi tập tool cố định để chạy test.\n- **Set `permission_mode` to `default` and register a `canUseTool` callback that always throws an exception for tools outside the fixed set.**: Callback ném ngoại lệ không phải quyết định deny rõ ràng và không thay thế chính sách giới hạn tool xác định.\n\n**Cần duyệt nội dung: không lựa chọn nào bảo đảm đầy đủ việc giới hạn tool tuyệt đối như đề đang viết.**\n\n**Tham khảo:**\n\n- [code.claude.com — permissions](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/permissions%5C%22)", "references": [{"title": "code.claude.com — permissions", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/permissions%5C%22"}]}, {"no": 111, "id": 1340, "type": "single", "select": 1, "question": "An engineer configuring a Claude Code hook wants it to fire for every Bash, Edit, and NotebookEdit tool call without listing each tool name explicitly. \n\nAccording to Anthropic's documentation on regex-based matchers, which configuration achieves this?", "imageMissing": false, "options": [{"key": "A", "text": "Omitting the matcher field entirely, which causes the hook to fire only for tools with names longer than four characters, such as Bash and NotebookEdit."}, {"key": "B", "text": "A matcher of `Bash+Edit+NotebookEdit`, where the plus sign acts as a concatenation operator, causing the pattern to be evaluated as a single exact-match string."}, {"key": "C", "text": "A matcher of `Bash, Edit, NotebookEdit` with commas, which triggers regex evaluation, causing the pattern to match any tool name containing those substrings."}, {"key": "D", "text": "A matcher like `Bash|Edit.*` is used; the system falls back to regex evaluation and matches any tool name containing those as substrings."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A matcher like `Bash|Edit.*` is used; the system falls back to regex evaluation and matches any tool name containing those as substrings.\n\nPhép hoặc trong regex khớp Bash hoặc tên chứa Edit rồi đến hậu tố bất kỳ, nên bao gồm Edit và NotebookEdit theo cơ chế matcher được mô tả.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A matcher of `Bash, Edit, NotebookEdit` with commas, which triggers regex evaluation, causing the pattern to match any tool name containing those substrings.**: Với sự kiện tool, dấu phẩy phân cách các tên tool khớp chính xác; không kích hoạt cách khớp chuỗi con bằng regex như mô tả. Cách này cũng liệt kê từng tool, trái yêu cầu của đề.\n- **Omitting the matcher field entirely, which causes the hook to fire only for tools with names longer than four characters, such as Bash and NotebookEdit.**: Bỏ matcher không đặt điều kiện độ dài tên tool.\n- **A matcher of `Bash+Edit+NotebookEdit`, where the plus sign acts as a concatenation operator, causing the pattern to be evaluated as a single exact-match string.**: Dấu cộng là lượng từ regex, không biểu thị danh sách tên thay thế.\n\n**Tham khảo:**\n\n- [code.claude.com — hooks](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/hooks%5C%22)\n- [Tham khảo hooks — quy tắc matcher](%5C%22https%3A//code.claude.com/docs/en/hooks#matcher-patterns%5C%22)", "references": [{"title": "code.claude.com — hooks", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/hooks%5C%22"}, {"title": "Tham khảo hooks — quy tắc matcher", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/hooks#matcher-patterns%5C%22"}]}, {"no": 112, "id": 1339, "type": "multiple", "select": 3, "question": "Which of the following statements about hook decision priority and configuration scope are accurate according to Anthropic's documentation? (Select 3)", "imageMissing": false, "options": [{"key": "A", "text": "Async hook outputs can safely block, modify, or inject context into the operation as long as `asyncTimeout` is set high enough"}, {"key": "B", "text": "A hook matcher of `*` is functionally identical to an omitted matcher, since only `*` fully disables regex evaluation for that hook"}, {"key": "C", "text": "When multiple hooks return conflicting decisions, deny takes priority over defer, which takes priority over ask, which takes priority over allow"}, {"key": "D", "text": "Managed policy settings apply organization-wide and are admin-controlled, taking precedence in a way project-local settings cannot override"}, {"key": "E", "text": "`.claude/settings.local.json` is gitignored and intended for local-only configuration, not for sharing hooks with a team"}, {"key": "F", "text": "PostToolUse hooks can block a tool call before it executes, just like PreToolUse hooks"}], "correct": ["C", "D", "E"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** When multiple hooks return conflicting decisions, deny takes priority over defer, which takes priority over ask, which takes priority over allow; `.claude/settings.local.json` is gitignored and intended for local-only configuration, not for sharing hooks with a team; Managed policy settings apply organization-wide and are admin-controlled, taking precedence in a way project-local settings cannot override\n\nQuyết định PreToolUse đồng bộ xung đột dùng thứ tự deny/defer/ask/allow được tài liệu nêu. Settings local dành cho cấu hình riêng trong dự án; settings managed thể hiện chính sách quản trị. Ba nhận định này mô tả ba quy tắc riêng về quyết định và phạm vi cấu hình.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A hook matcher of `*` is functionally identical to an omitted matcher, since only `*` fully disables regex evaluation for that hook**: Bỏ matcher cũng có thể khớp mọi sự kiện phù hợp, nên nói chỉ wildcard mới bỏ lọc là sai.\n- **PostToolUse hooks can block a tool call before it executes, just like PreToolUse hooks**: PostToolUse chạy sau thực thi, không chặn ngược lời gọi đã xong.\n- **Async hook outputs can safely block, modify, or inject context into the operation as long as `asyncTimeout` is set high enough**: Đầu ra async không chặn, sửa hay chèn context vào thao tác đã đi tiếp.\n\nĐã sửa đáp án nguồn: PDF chỉ đánh dấu một phương án, nhưng đề và đối chiếu từng lựa chọn cho thấy có nhiều phương án đúng. Xem báo cáo kiểm tra đáp án đi kèm.\n\n**Tham khảo:**\n\n- [code.claude.com — hooks](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/hooks%5C%22)\n- [code.claude.com — settings](%5C%22https%3A//code.claude.com/docs/en/settings%5C%22)", "references": [{"title": "code.claude.com — hooks", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/hooks%5C%22"}, {"title": "code.claude.com — settings", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/settings%5C%22"}]}, {"no": 113, "id": 1338, "type": "single", "select": 1, "question": "A healthcare organization with a HIPAA-enabled Claude API organization sends a request that includes the code execution tool. \n\nThe API responds with a 400 invalid_request_error stating the feature is not available for HIPAA-regulated organizations without Zero Data Retention. \n\nWhat is the most appropriate immediate remediation for this specific request?", "imageMissing": false, "options": [{"key": "A", "text": "Switch the request to a different, unrelated organization ID without a BAA in place so the feature restriction no longer applies"}, {"key": "B", "text": "Ignore the error and resubmit the same request repeatedly, since HIPAA feature restrictions are only advisory warnings rather than enforced blocks"}, {"key": "C", "text": "Remove the code execution tool from the request and use only features listed as eligible for HIPAA readiness in the feature eligibility table"}, {"key": "D", "text": "Retry the identical request with a higher max_tokens value, since the error is caused by insufficient token budget for the tool call"}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Remove the code execution tool from the request and use only features listed as eligible for HIPAA readiness in the feature eligibility table\n\nVới lỗi đã nêu, bỏ tool không tương thích và chỉ dùng tính năng được cho phép theo cấu hình thực của tổ chức. Thông báo lỗi quyết định cách sửa request ngay lúc này, không phải ngân sách token; cần kiểm tra lại bảng điều kiện hiện hành trước triển khai.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Retry the identical request with a higher max_tokens value, since the error is caused by insufficient token budget for the tool call**: Tăng token đầu ra không bật được tính năng chưa được phép.\n- **Switch the request to a different, unrelated organization ID without a BAA in place so the feature restriction no longer applies**: Chuyển sang tổ chức không liên quan là né ràng buộc thay vì xử lý điều kiện.\n- **Ignore the error and resubmit the same request repeatedly, since HIPAA feature restrictions are only advisory warnings rather than enforced blocks**: Gửi lại y nguyên nhiều lần không xóa chặn tính năng xác định.\n\n**Tham khảo:**\n\n- [platform.claude.com — api-and-data-retention](%5C%22https%3A//platform.claude.com/docs/en/manage-claude/api-and-data-retention%5C%22)", "references": [{"title": "platform.claude.com — api-and-data-retention", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/manage-claude/api-and-data-retention%5C%22"}]}, {"no": 114, "id": 1293, "type": "single", "select": 1, "question": "Your Claude application processes 50-page legal contracts and produces summaries with citation references back to the source. \n\nThe team is debating whether to send each contract whole or split into smaller pieces. \n\nThe contracts fit within Claude's context window. \n\nInitial testing shows that whole- document processing produces summaries with stronger cross-section reasoning but occasionally drifts on citation accuracy in later sections. \n\nChunked processing produces stronger citation accuracy per chunk but loses cross-section reasoning. \n\nThe team has not decided which property matters more. \n\nHow would you guide the team's decision?", "imageMissing": false, "options": [{"key": "A", "text": "Examine the use cases where cross-section reasoning failures occur and assess whether whole-document processing meets the application's accuracy requirements across a representative sample of contracts."}, {"key": "B", "text": "Identify which property matters more for the application's actual use case and let that decision drive the chunking approach, then validate the choice against representative contracts."}, {"key": "C", "text": "Review the citation accuracy results from chunked processing and determine whether the loss of cross-section reasoning produces summaries that still meet the application's quality bar."}, {"key": "D", "text": "Assess the cost and latency implications of both approaches against the application's performance requirements before recommending which processing strategy to adopt."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Identify which property matters more for the application's actual use case and let that decision drive the chunking approach, then validate the choice against representative contracts.\n\nChốt thuộc tính chất lượng quan trọng nhất với nghiệp vụ, rồi kiểm tra cả xử lý nguyên văn lẫn chia đoạn trên hợp đồng đại diện. Vừa context chưa đủ để quyết định đánh đổi.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Assess the cost and latency implications of both approaches against the application's performance requirements before recommending which processing strategy to adopt.**: Chi phí và độ trễ chưa giải quyết ưu tiên chất lượng còn bỏ ngỏ.\n- **Examine the use cases where cross-section reasoning failures occur and assess whether whole-document processing meets the application's accuracy requirements across a representative sample of contracts.**: Chỉ đánh giá suy luận nguyên văn làm lệch quyết định trước khi đặt mục tiêu.\n- **Review the citation accuracy results from chunked processing and determine whether the loss of cross-section reasoning produces summaries that still meet the application's quality bar.**: Chỉ nhìn trích dẫn theo đoạn cũng chốt ưu tiên quá sớm.\n\n**Tham khảo:**\n\n- [www.anthropic.com — effective-context-engineering-for-ai-agents](%5C%22https%3A//www.anthropic.com/engineering/effective-context-engineering-for-ai-agents%5C%22)", "references": [{"title": "www.anthropic.com — effective-context-engineering-for-ai-agents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//www.anthropic.com/engineering/effective-context-engineering-for-ai-agents%5C%22"}]}, {"no": 115, "id": 1295, "type": "single", "select": 1, "question": "You are writing a system prompt for a Claude application that needs to produce output in a specific JSON shape. \n\nThe downstream system will reject any output that does not match the schema. \n\nYour prompt would need to...", "imageMissing": false, "options": [{"key": "A", "text": "Instruct Claude to return JSON sometimes and free text other times so the application's output captures both formats."}, {"key": "B", "text": "Omit any reference to the format and rely on a post-processing step in the application to reshape Claude's output."}, {"key": "C", "text": "Instruct Claude to use whichever output format it considers most appropriate for each request the application handles."}, {"key": "D", "text": "Include explicit constraints describing the required JSON schema and an instruction to produce only output matching that schema."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Include explicit constraints describing the required JSON schema and an instruction to produce only output matching that schema.\n\nNêu rõ cấu trúc cần trả và không thêm lời dẫn ngoài JSON. Prompt sẽ bớt mơ hồ; vẫn cần structured output được hỗ trợ và kiểm tra schema trong ứng dụng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Instruct Claude to use whichever output format it considers most appropriate for each request the application handles.**: Để model tự chọn dạng trái với hợp đồng cố định.\n- **Instruct Claude to return JSON sometimes and free text other times so the application's output captures both formats.**: Lúc JSON lúc văn bản không tạo giao diện nhất quán.\n- **Omit any reference to the format and rely on a post-processing step in the application to reshape Claude's output.**: Không nêu định dạng khiến schema cần dùng không được chỉ rõ.\n\n**Tham khảo:**\n\n- [platform.claude.com — structured-outputs](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/structured-outputs%5C%22)", "references": [{"title": "platform.claude.com — structured-outputs", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/structured-outputs%5C%22"}]}, {"no": 116, "id": 1296, "type": "single", "select": 1, "question": "You are building a Claude application that processes 10,000 customer emails overnight to extract structured data. \n\nThe work is non-interactive, runs once daily, and has a flexible completion window of several hours. \n\nWhich Claude API would you use?", "imageMissing": false, "options": [{"key": "A", "text": "The Batch API, which is designed for non-interactive workloads with flexible completion windows."}, {"key": "B", "text": "The real-time Messages API with concurrent requests to process the emails as fast as possible during the overnight window."}, {"key": "C", "text": "The real-time Messages API, processing the emails one at a time sequentially to ensure consistent ordering of results."}, {"key": "D", "text": "The streaming responses API to process each email and return partial results to a database as the model generates them."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** The Batch API, which is designed for non-interactive workloads with flexible completion windows.\n\nCông việc chấp nhận chờ hoàn tất bất đồng bộ nên Message Batches phù hợp hơn luồng tương tác. Gắn mã từng email và xử lý riêng kết quả cùng lỗi.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **The streaming responses API to process each email and return partial results to a database as the model generates them.**: Streaming phục vụ trả dần kết quả, không trực tiếp phục vụ nhu cầu chạy lô.\n- **The real-time Messages API, processing the emails one at a time sequentially to ensure consistent ordering of results.**: Gọi đồng bộ tuần tự làm các việc độc lập phải chờ nhau.\n- **The real-time Messages API with concurrent requests to process the emails as fast as possible during the overnight window.**: Gọi đồng bộ song song ưu tiên độ trễ mà bài toán không đòi hỏi.\n\n**Tham khảo:**\n\n- [platform.claude.com — batch-processing](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/batch-processing%5C%22)", "references": [{"title": "platform.claude.com — batch-processing", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/batch-processing%5C%22"}]}, {"no": 117, "id": 1297, "type": "single", "select": 1, "question": "The team is debating whether to integrate with the Claude API directly or through a third-party abstraction layer that supports multiple LLM providers. \n\nThe team has identified that all current and projected use cases run on Claude, no internal customer has requested LLM portability, and the team's product roadmap does not mention multi-provider support over the next two years. \n\nThe third-party abstraction would add roughly 15 percent overhead in code complexity and introduce one additional dependency. \n\nWhich integration approach would you recommend?", "imageMissing": false, "options": [{"key": "A", "text": "A custom multi-provider abstraction layer the team builds in-house so that the team controls every part of the abstraction the application uses for its API calls."}, {"key": "B", "text": "Direct integration with Claude through its SDK, because no multi-provider need exists and abstraction would add complexity that does not pay off."}, {"key": "C", "text": "The third-party abstraction layer, on the grounds that multi-provider support is valuable for any application as a matter of long-term flexibility across vendors."}, {"key": "D", "text": "Both integration paths in parallel, where the application uses each path on different runs to compare which performs better in production over time."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Direct integration with Claude through its SDK, because no multi-provider need exists and abstraction would add complexity that does not pay off.\n\nDùng SDK trực tiếp vì lộ trình thực tế chỉ cần Claude. Lớp trừu tượng nên phục vụ nhu cầu chuyển nhà cung cấp có thật, thay vì thêm phụ thuộc cho khả năng giả định.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **The third-party abstraction layer, on the grounds that multi-provider support is valuable for any application as a matter of long-term flexibility across vendors.**: Linh hoạt chung chung trong tương lai chưa bù cho việc không có nhu cầu hiện tại.\n- **Both integration paths in parallel, where the application uses each path on different runs to compare which performs better in production over time.**: Duy trì hai đường tích hợp thêm việc khi không có yêu cầu so sánh.\n- **A custom multi-provider abstraction layer the team builds in-house so that the team controls every part of the abstraction the application uses for its API calls.**: Tự viết lớp đa nhà cung cấp vẫn tạo lớp trừu tượng chưa cần.\n\n**Tham khảo:**\n\n- [code.claude.com — overview](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22)", "references": [{"title": "code.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22"}]}, {"no": 118, "id": 1298, "type": "single", "select": 1, "question": "You are implementing a custom tool for your Claude agent. \n\nThe tool needs to interact with an external pricing service that returns product data. \n\nWhich of the following best practices would you apply as you develop this tool?", "imageMissing": false, "options": [{"key": "A", "text": "Define the tool with a loose schema and let the model interpret the inputs flexibly on each call the agent makes."}, {"key": "B", "text": "Define the tool with a clear schema, write a precise description for when to call it, and handle pricing service errors explicitly."}, {"key": "C", "text": "Omit the tool description and let the model infer when to use the tool based on the tool's name and the rest of the prompt context."}, {"key": "D", "text": "Implement the tool with no error handling and let the agent loop catch failures whenever the pricing service returns an error during operation."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Define the tool with a clear schema, write a precise description for when to call it, and handle pricing service errors explicitly.\n\nTool cần hợp đồng đầu vào tin cậy và mô tả khi nào nên gọi. Xử lý lỗi dịch vụ giá rõ ràng giúp phân biệt đầu vào sai, gián đoạn và kết quả hợp lệ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Omit the tool description and let the model infer when to use the tool based on the tool's name and the rest of the prompt context.**: Chỉ tên tool chưa mô tả điều kiện lựa chọn.\n- **Define the tool with a loose schema and let the model interpret the inputs flexibly on each call the agent makes.**: Schema lỏng làm tăng tham số sai.\n- **Implement the tool with no error handling and let the agent loop catch failures whenever the pricing service returns an error during operation.**: Bỏ xử lý lỗi ở handler khiến lỗi dịch vụ đi vào vòng lặp không kiểm soát.\n\n**Tham khảo:**\n\n- [platform.claude.com — define-tools](%5C%22https%3A//platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools%5C%22)", "references": [{"title": "platform.claude.com — define-tools", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools%5C%22"}]}, {"no": 119, "id": 1299, "type": "single", "select": 1, "question": "Your Claude application has multi-step workflows where each step's output is needed only briefly before the agent moves on. \n\nThe cumulative tool output is filling the context window with content that is no longer relevant. \n\nHow would you handle the accumulating tool output?", "imageMissing": false, "options": [{"key": "A", "text": "Apply prompt caching to the accumulated tool outputs so the application does not re-pay for the older content on each subsequent step."}, {"key": "B", "text": "Switch to a smaller Claude model that processes context more efficiently and treat any quality loss as a tradeoff for the cost reduction."}, {"key": "C", "text": "Keep every tool output in the context indefinitely so the agent has the full record of every step it has executed during the workflow."}, {"key": "D", "text": "Apply tool output pruning to remove tool outputs that are no longer needed by later steps in the workflow."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Apply tool output pruning to remove tool outputs that are no longer needed by later steps in the workflow.\n\nBỏ kết quả tool khi các bước sau không còn cần, đồng thời giữ quyết định và tham chiếu hữu ích. Cách này giảm context đang chiếm chỗ thay vì chỉ đổi giá.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Apply prompt caching to the accumulated tool outputs so the application does not re-pay for the older content on each subsequent step.**: Cache giảm chi phí xử lý lặp nhưng không bỏ ngữ cảnh cũ.\n- **Switch to a smaller Claude model that processes context more efficiently and treat any quality loss as a tradeoff for the cost reduction.**: Model nhỏ hơn không tự xóa kết quả đã hết cần.\n- **Keep every tool output in the context indefinitely so the agent has the full record of every step it has executed during the workflow.**: Giữ mọi kết quả chính là nguyên nhân gây áp lực context.\n\n**Tham khảo:**\n\n- [platform.claude.com — context-editing](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/context-editing%5C%22)", "references": [{"title": "platform.claude.com — context-editing", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/context-editing%5C%22"}]}, {"no": 120, "id": 1300, "type": "single", "select": 1, "question": "A Claude application that worked well in testing is now occasionally returning outputs that mention information not present in the input. \n\nThe development team initially assumed the model was hallucinating, so they asked you to troubleshoot. \n\nWhat would you do first?", "imageMissing": false, "options": [{"key": "A", "text": "Add a system prompt instruction telling the model not to invent information, on the grounds that prompt-level instructions are the fastest fix for hallucination concerns."}, {"key": "B", "text": "Apply a retrieval-augmented generation pattern to ground the responses in source content before any further investigation of the production traces."}, {"key": "C", "text": "Replace the current model with a larger one to reduce the chance of hallucination, on the grounds that larger models tend to hallucinate less in typical applications."}, {"key": "D", "text": "Examine production traces to identify whether the issue is hallucination by the model, context loss, prompt injection, or another failure mode before recommending a fix."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Examine production traces to identify whether the issue is hallucination by the model, context loss, prompt injection, or another failure mode before recommending a fix.\n\nĐọc request thực tế, dữ liệu truy xuất, kết quả tool và đầu ra trước khi gọi hiện tượng này là ảo giác. Mỗi nguyên nhân cần cách sửa riêng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Replace the current model with a larger one to reduce the chance of hallucination, on the grounds that larger models tend to hallucinate less in typical applications.**: Đổi model là suy đoán khi chưa chẩn đoán.\n- **Apply a retrieval-augmented generation pattern to ground the responses in source content before any further investigation of the production traces.**: Truy xuất có thể giúp bám nguồn nhưng không sửa mọi dạng lỗi.\n- **Add a system prompt instruction telling the model not to invent information, on the grounds that prompt-level instructions are the fastest fix for hallucination concerns.**: Thêm hướng dẫn là giả định nguyên nhân khi chưa xem bằng chứng.\n\n**Tham khảo:**\n\n- [platform.claude.com — develop-tests](%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22)", "references": [{"title": "platform.claude.com — develop-tests", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22"}]}, {"no": 121, "id": 1302, "type": "single", "select": 1, "question": "Your team's Claude application has been in production for a year, and the team has decided to formalize its testing strategy. \n\nCurrently, the team writes ad-hoc tests for individual features but has no overall testing approach. \n\nWhat testing approach would you formalize?", "imageMissing": false, "options": [{"key": "A", "text": "Define unit tests for individual functions, integration tests for the Claude integration, and end-to-end tests for critical user flows, applied consistently across the codebase."}, {"key": "B", "text": "Define a single testing approach that uses end-to-end tests and apply it consistently across all new features as they are added to the codebase."}, {"key": "C", "text": "Continue writing ad-hoc tests as features ship and introduce a peer review step to ensure each test adequately covers the feature being released."}, {"key": "D", "text": "Adopt a test-driven development practice where unit tests are written before each feature is implemented and must pass before code is merged."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Define unit tests for individual functions, integration tests for the Claude integration, and end-to-end tests for critical user flows, applied consistently across the codebase.\n\nDùng unit test cho logic cục bộ, integration test cho điểm tích hợp và kiểm tra đầu cuối cho luồng quan trọng. Mỗi lớp bắt một nhóm lỗi khác nhau.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Adopt a test-driven development practice where unit tests are written before each feature is implemented and must pass before code is merged.**: Viết test trước chưa tự xác lập độ phủ các tầng.\n- **Continue writing ad-hoc tests as features ship and introduce a peer review step to ensure each test adequately covers the feature being released.**: Review test tùy hứng vẫn thiếu chiến lược chung.\n- **Define a single testing approach that uses end-to-end tests and apply it consistently across all new features as they are added to the codebase.**: Chỉ test đầu cuối thường chậm và khó cô lập lỗi nhỏ.\n\n**Tham khảo:**\n\n- [testing.googleblog.com — just-say-no-to-more-end-to-end-tests.html](%5C%22https%3A//testing.googleblog.com/2015/04/just-say-no-to-more-end-to-end-tests.html%5C%22)", "references": [{"title": "testing.googleblog.com — just-say-no-to-more-end-to-end-tests.html", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//testing.googleblog.com/2015/04/just-say-no-to-more-end-to-end-tests.html%5C%22"}]}, {"no": 122, "id": 1303, "type": "single", "select": 1, "question": "A teammate has asked you to explain the difference between context engineering and prompt engineering. \n\nThey have heard the terms used interchangeably and are unsure how each applies to a Claude application that processes long-running multi-step tasks. \n\nHow would you describe the distinction?", "imageMissing": false, "options": [{"key": "A", "text": "Prompt engineering focuses on the model's response, while context engineering focuses on the user's input across many sessions in a long-running multi-step Claude application."}, {"key": "B", "text": "Prompt engineering shapes individual prompts for specific outputs, while context engineering manages how content flows across turns and steps and takes steps to keep relevant state visible."}, {"key": "C", "text": "Prompt engineering and context engineering each address content the team gives Claude, but the team can group them under a single workflow because the practices use overlapping techniques."}, {"key": "D", "text": "Prompt engineering is the older term for prompt design, while context engineering is the newer term that has replaced it in modern Claude applications across the industry."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Prompt engineering shapes individual prompts for specific outputs, while context engineering manages how content flows across turns and steps and takes steps to keep relevant state visible.\n\nPrompt engineering thiết kế chỉ dẫn cho từng tương tác; context engineering chọn, giữ và chuyển thông tin cần dùng xuyên suốt quy trình.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Prompt engineering focuses on the model's response, while context engineering focuses on the user's input across many sessions in a long-running multi-step Claude application.**: Context engineering gồm kết quả tool và trạng thái, không chỉ đầu vào người dùng.\n- **Prompt engineering is the older term for prompt design, while context engineering is the newer term that has replaced it in modern Claude applications across the industry.**: Khái niệm mới không đơn giản thay thế khái niệm cũ.\n- **Prompt engineering and context engineering each address content the team gives Claude, but the team can group them under a single workflow because the practices use overlapping techniques.**: Có kỹ thuật giao nhau không có nghĩa phạm vi giống nhau.\n\n**Tham khảo:**\n\n- [www.anthropic.com — effective-context-engineering-for-ai-agents](%5C%22https%3A//www.anthropic.com/engineering/effective-context-engineering-for-ai-agents%5C%22)", "references": [{"title": "www.anthropic.com — effective-context-engineering-for-ai-agents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//www.anthropic.com/engineering/effective-context-engineering-for-ai-agents%5C%22"}]}, {"no": 123, "id": 1304, "type": "single", "select": 1, "question": "The team is debating whether to build a new capability as a custom tool or to use an existing built-in tool that nearly covers the use case but lacks one specific feature. \n\nHow would you decide?", "imageMissing": false, "options": [{"key": "A", "text": "Examine the custom tool option by scoping the implementation effort and determining whether the additional flexibility justifies the development and maintenance cost."}, {"key": "B", "text": "Review the built-in tool's documentation and assess whether its existing capabilities are sufficient to cover the use case without any modification or extension."}, {"key": "C", "text": "Identify whether the team has previously built similar custom tools and use those precedents to determine which approach is more consistent with the existing codebase."}, {"key": "D", "text": "Evaluate whether the missing feature can be addressed by extending the built-in tool or warrants a custom tool, then choose accordingly."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Evaluate whether the missing feature can be addressed by extending the built-in tool or warrants a custom tool, then choose accordingly.\n\nĐánh giá phần còn thiếu và khả năng mở rộng được hỗ trợ để bù phần đó. Chỉ viết tool riêng khi lợi ích đủ bù chi phí xây dựng và duy trì.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Identify whether the team has previously built similar custom tools and use those precedents to determine which approach is more consistent with the existing codebase.**: Tiền lệ có thể tham khảo nhưng chưa quyết định mức cần thiết của phần thiếu.\n- **Examine the custom tool option by scoping the implementation effort and determining whether the additional flexibility justifies the development and maintenance cost.**: Chỉ tính phương án tự viết là bỏ qua tool sẵn có.\n- **Review the built-in tool's documentation and assess whether its existing capabilities are sufficient to cover the use case without any modification or extension.**: Chỉ đọc tính năng hiện có bỏ qua mở rộng và phương án tool riêng.\n\n**Tham khảo:**\n\n- [code.claude.com — overview](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22)", "references": [{"title": "code.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22"}]}, {"no": 124, "id": 1305, "type": "single", "select": 1, "question": "Your Claude application returns confident-sounding answers, but occasionally those answers contain factual errors that downstream systems treat as ground truth. \n\nThe team is concerned about the application's confidence-versus-accuracy gap. \n\nHow would you address the gap?", "imageMissing": false, "options": [{"key": "A", "text": "Lower the model's temperature so the model's responses sound less confident and downstream systems are less likely to treat the responses as ground truth in normal operation."}, {"key": "B", "text": "Apply skepticism toward confident output by adding validation steps, sourcing requirements, or confidence calibration before treating outputs as ground truth."}, {"key": "C", "text": "Add a disclaimer to every output telling users to verify the accuracy of the output and treat the disclaimer as the primary mechanism for managing the confidence-versus-accuracy gap."}, {"key": "D", "text": "Reject every response the application produces until a manual accuracy review is conducted on each response by a human reviewer before any downstream system uses it."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Apply skepticism toward confident output by adding validation steps, sourcing requirements, or confidence calibration before treating outputs as ground truth.\n\nKhông coi diễn đạt trôi chảy và tự tin là bằng chứng đúng. Đối chiếu phát biểu quan trọng với nguồn hoặc quy tắc kiểm tra; hiệu chuẩn luồng theo confidence bằng kết quả có nhãn.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Lower the model's temperature so the model's responses sound less confident and downstream systems are less likely to treat the responses as ground truth in normal operation.**: Temperature không kiểm chứng dữ kiện hay bảo đảm confidence được hiệu chuẩn.\n- **Reject every response the application produces until a manual accuracy review is conducted on each response by a human reviewer before any downstream system uses it.**: Từ chối mọi đầu ra là quá rộng và mất tính hữu dụng.\n- **Add a disclaimer to every output telling users to verify the accuracy of the output and treat the disclaimer as the primary mechanism for managing the confidence-versus-accuracy gap.**: Lời cảnh báo không ngăn hệ thống sau nhận dữ kiện sai.\n\n**Tham khảo:**\n\n- [platform.claude.com — develop-tests](%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22)", "references": [{"title": "platform.claude.com — develop-tests", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/develop-tests%5C%22"}]}, {"no": 125, "id": 1306, "type": "single", "select": 1, "question": "You are designing an agent that processes vendor invoices. \n\nThe work involves a small number of well- understood steps, but occasionally an invoice arrives in an unexpected format that requires the system to decide between rerouting, requesting clarification, or flagging for human review. \n\nThe most appropriate architecture for this system is...", "imageMissing": false, "options": [{"key": "A", "text": "A fully autonomous agent that handles every invoice from start to finish across all formats."}, {"key": "B", "text": "A single large prompt that processes every incoming invoice, both standard and unexpected, in one model call."}, {"key": "C", "text": "A workflow for the standard path with an agent invoked at the decision point for unexpected formats."}, {"key": "D", "text": "A manager agent that delegates each step of standard invoice processing to a dedicated subagent, with a separate subagent handling each unexpected format."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A workflow for the standard path with an agent invoked at the decision point for unexpected formats.\n\nGiữ đường xử lý hóa đơn chuẩn trong workflow và dùng agent tại ngoại lệ cần lựa chọn. Nhờ vậy tính linh hoạt tập trung đúng nơi cần.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A fully autonomous agent that handles every invoice from start to finish across all formats.**: Tự trị toàn bộ là không cần cho luồng thông thường đã rõ.\n- **A manager agent that delegates each step of standard invoice processing to a dedicated subagent, with a separate subagent handling each unexpected format.**: Mỗi bước chuẩn một subagent làm tăng điều phối.\n- **A single large prompt that processes every incoming invoice, both standard and unexpected, in one model call.**: Một prompt lớn không tạo luồng chuẩn và rẽ nhánh ngoại lệ rõ ràng.\n\n**Tham khảo:**\n\n- [www.anthropic.com — building-effective-agents](%5C%22https%3A//www.anthropic.com/research/building-effective-agents%5C%22)", "references": [{"title": "www.anthropic.com — building-effective-agents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//www.anthropic.com/research/building-effective-agents%5C%22"}]}, {"no": 126, "id": 1307, "type": "single", "select": 1, "question": "A teammate has asked you to explain when a Skill would be the right choice over an MCP server. \n\nThe teammate is unsure how the two differ in practice when both can be reused across teams. \n\nHow would you explain the distinction?", "imageMissing": false, "options": [{"key": "A", "text": "A Skill and an MCP server are equivalent extension mechanisms that the team can use interchangeably for any reusable capability that needs to be accessible across teams."}, {"key": "B", "text": "A Skill is the older mechanism and an MCP server is the newer one, so the team should prefer an MCP server for any reusable capability that the team builds going forward."}, {"key": "C", "text": "A Skill bundles prompts, scripts, and data into a package the model loads as a unit while an MCP server exposes resources, tools, and prompts through a standard client interface."}, {"key": "D", "text": "A Skill is preferable for cross-team reuse because it loads more efficiently than an MCP server during normal operation in the team's typical multi-team workloads."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A Skill bundles prompts, scripts, and data into a package the model loads as a unit while an MCP server exposes resources, tools, and prompts through a standard client interface.\n\nSkill đóng gói hướng dẫn thao tác cùng tài nguyên hỗ trợ; MCP server cung cấp khả năng gọi qua giao thức. Chọn theo thứ cần tái sử dụng và cách bên khác sử dụng nó.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A Skill and an MCP server are equivalent extension mechanisms that the team can use interchangeably for any reusable capability that needs to be accessible across teams.**: Hai cơ chế có vai trò khác nhau, không thể thay thế tùy ý.\n- **A Skill is the older mechanism and an MCP server is the newer one, so the team should prefer an MCP server for any reusable capability that the team builds going forward.**: Cũ hay mới không quyết định cơ chế mở rộng.\n- **A Skill is preferable for cross-team reuse because it loads more efficiently than an MCP server during normal operation in the team's typical multi-team workloads.**: Lợi thế hiệu suất tuyệt đối không phải khác biệt bản chất được hỏi.\n\n**Tham khảo:**\n\n- [code.claude.com — skills](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/skills%5C%22)\n- [modelcontextprotocol.io — server-concepts](%5C%22https%3A//modelcontextprotocol.io/docs/learn/server-concepts%5C%22)", "references": [{"title": "code.claude.com — skills", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/skills%5C%22"}, {"title": "modelcontextprotocol.io — server-concepts", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//modelcontextprotocol.io/docs/learn/server-concepts%5C%22"}]}, {"no": 127, "id": 1308, "type": "single", "select": 1, "question": "Your team is choosing how to add a capability to a Claude application. \n\nYou want to apply the appropriate option, whether built-in tool, custom tool, Skill, or MCP server, based on the use case. \n\nYou would choose the option that...", "imageMissing": false, "options": [{"key": "A", "text": "Is the easiest to build given the team's current development tools and workflows."}, {"key": "B", "text": "Is the most familiar to the team based on prior experience with similar capabilities."}, {"key": "C", "text": "Is the newest available option among built-in tools, custom tools, Skills, and MCP servers."}, {"key": "D", "text": "Matches the use case's scope, reuse needs, and integration context."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Matches the use case's scope, reuse needs, and integration context.\n\nChọn cơ chế mở rộng vừa đủ đáp ứng khả năng và nhu cầu chia sẻ thực tế. Ranh giới tích hợp giúp quyết định tool sẵn có, handler riêng, Skill hay MCP server phù hợp.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Is the most familiar to the team based on prior experience with similar capabilities.**: Quen thuộc chỉ là yếu tố phụ và có thể dẫn tới giao diện không phù hợp.\n- **Is the newest available option among built-in tools, custom tools, Skills, and MCP servers.**: Mới hơn chưa chứng minh phù hợp hơn.\n- **Is the easiest to build given the team's current development tools and workflows.**: Dễ xây chưa bảo đảm đáp ứng tái sử dụng và tích hợp.\n\n**Tham khảo:**\n\n- [code.claude.com — overview](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22)", "references": [{"title": "code.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22"}]}, {"no": 128, "id": 1309, "type": "single", "select": 1, "question": "A code-review agent needs to read through 40 files, but the team wants the main conversation to stay short so later turns aren't paying for tokens spent on every file that was opened during the review. \n\nWhich architecture keeps the main agent's context lean?", "imageMissing": false, "options": [{"key": "A", "text": "Delegate the review to a subagent defined with an AgentDefinition; its tool calls and file contents stay in its own context, and only a final summary returns to the parent."}, {"key": "B", "text": "Enable include_partial_messages so file contents stream back to the main conversation incrementally as text deltas instead of arriving all at once."}, {"key": "C", "text": "Increase max_turns on the main query so Claude has enough budget to read all 40 files directly in the main conversation without the loop stopping early."}, {"key": "D", "text": "Set effort to \"low\" on the main query so each turn that reads a file consumes fewer reasoning tokens, even though all 40 files still load fully into the shared main conversation."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Delegate the review to a subagent defined with an AgentDefinition; its tool calls and file contents stay in its own context, and only a final summary returns to the parent.\n\nCho việc review file một context riêng, rồi trả kết quả ngắn về agent chính. Các lượt đọc trung gian không đi vào lịch sử hội thoại tiếp diễn của agent chính.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Increase max_turns on the main query so Claude has enough budget to read all 40 files directly in the main conversation without the loop stopping early.**: Tăng số lượt cho phép làm nhiều hơn nhưng không tách context.\n- **Set effort to \\\"low\\\" on the main query so each turn that reads a file consumes fewer reasoning tokens, even though all 40 files still load fully into the shared main conversation.**: Effort thấp đổi mức suy luận, không giảm văn bản file đã nạp.\n- **Enable include_partial_messages so file contents stream back to the main conversation incrementally as text deltas instead of arriving all at once.**: Trả message từng phần đổi cách truyền, không đổi nơi giữ context.\n\n**Tham khảo:**\n\n- [code.claude.com — subagents](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/subagents%5C%22)", "references": [{"title": "code.claude.com — subagents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/subagents%5C%22"}]}, {"no": 129, "id": 1310, "type": "single", "select": 1, "question": "A long-running agent session is approaching its context window limit. \n\nThe team wants two things: a full, unabridged copy of the conversation saved before the SDK summarizes older history, and a guarantee that a specific formatting rule survives every compaction event without being paraphrased away. \n\nWhich combination of mechanisms addresses both needs?", "imageMissing": false, "options": [{"key": "A", "text": "Register a PostToolUse hook to archive the transcript after each tool call completes, and place the formatting rule inside a subagent's AgentDefinition prompt instead of the main session."}, {"key": "B", "text": "Increase max_turns so compaction never triggers, and repeat the formatting rule at the start of every single user message sent throughout the session."}, {"key": "C", "text": "Rely on the automatic compaction summary alone to preserve both the transcript and the formatting rule, since summaries are designed to retain conversation details verbatim."}, {"key": "D", "text": "Register a PreCompact hook to archive the full transcript first, and put the formatting rule in CLAUDE.md so it reloads on every request instead of living only in the initial prompt."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Register a PreCompact hook to archive the full transcript first, and put the formatting rule in CLAUDE.md so it reloads on every request instead of living only in the initial prompt.\n\nLưu transcript gốc ở PreCompact trước khi tóm tắt. Đặt quy tắc bền vững trong CLAUDE.md và bảo đảm SDK nạp nguồn cấu hình đó; bản tóm tắt không phải bản lưu nguyên văn.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Increase max_turns so compaction never triggers, and repeat the formatting rule at the start of every single user message sent throughout the session.**: Giới hạn số lượt không vô hiệu nén theo dung lượng context.\n- **Rely on the automatic compaction summary alone to preserve both the transcript and the formatting rule, since summaries are designed to retain conversation details verbatim.**: Tóm tắt có mất thông tin không bảo đảm transcript nguyên bản hay đúng từng chữ.\n- **Register a PostToolUse hook to archive the transcript after each tool call completes, and place the formatting rule inside a subagent's AgentDefinition prompt instead of the main session.**: Hook sau tool và quy tắc chỉ cho subagent không đáp ứng cả hai yêu cầu của phiên chính.\n\n**Tham khảo:**\n\n- [code.claude.com — hooks](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/hooks%5C%22)", "references": [{"title": "code.claude.com — hooks", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/hooks%5C%22"}]}, {"no": 130, "id": 1311, "type": "multiple", "select": 2, "question": "A software architect is comparing three open-source agent frameworks for a project that requires integration with multiple LLM providers and end-to-end observability via OpenTelemetry. \n\nThe project's agent logic is linear and does not require the manual specification of execution graphs. \n\nThe frameworks under consideration are Strands Agents SDK, LangGraph, and Pydantic AI. \n\nBased on your knowledge of these frameworks, which of the following statements are true? (Select all that apply.)", "imageMissing": false, "options": [{"key": "A", "text": "LangGraph is best suited for simple, linear agent chains because its graph model restricts the developer to a single execution path."}, {"key": "B", "text": "Strands Agents SDK enforces that all agents are deployed on AWS and does not permit the use of third-party model APIs."}, {"key": "C", "text": "LangGraph models agent workflows as directed graphs, giving developers precise control over branching and looping in execution paths."}, {"key": "D", "text": "The Strands Agents SDK is designed to be model-agnostic and includes first-class support for OpenTelemetry, allowing trace export to observability platforms like AWS CloudWatch."}, {"key": "E", "text": "Pydantic AI includes a built-in OpenTelemetry collector that can be configured to send traces to CloudWatch out of the box."}, {"key": "F", "text": "LangGraph can only orchestrate agents that use the Anthropic API because it was developed by Anthropic."}], "correct": ["C", "D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** The Strands Agents SDK is designed to be model-agnostic and includes first-class support for OpenTelemetry, allowing trace export to observability platforms like AWS CloudWatch.; LangGraph models agent workflows as directed graphs, giving developers precise control over branching and looping in execution paths.\n\nStrands hỗ trợ nhiều nhà cung cấp model và đo lường bằng OpenTelemetry. LangGraph biểu diễn luồng có trạng thái bằng nút và cạnh, gồm cả rẽ nhánh và lặp. Cả hai nhận định đúng dù dự án tuyến tính không cần kiểm soát đồ thị.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **LangGraph can only orchestrate agents that use the Anthropic API because it was developed by Anthropic.**: LangGraph thuộc hệ sinh thái LangChain và không bị giới hạn ở Anthropic.\n- **Pydantic AI includes a built-in OpenTelemetry collector that can be configured to send traces to CloudWatch out of the box.**: Tích hợp OpenTelemetry/Logfire không đồng nghĩa có sẵn collector được cấu hình cho CloudWatch.\n- **Strands Agents SDK enforces that all agents are deployed on AWS and does not permit the use of third-party model APIs.**: Strands không bắt buộc chỉ chạy trên AWS hoặc chỉ dùng model AWS.\n- **LangGraph is best suited for simple, linear agent chains because its graph model restricts the developer to a single execution path.**: Đồ thị hỗ trợ nhiều nhánh và vòng lặp, không chỉ một đường.\n\nĐã sửa đáp án nguồn: PDF chỉ đánh dấu một phương án, nhưng đề và đối chiếu từng lựa chọn cho thấy có nhiều phương án đúng. Xem báo cáo kiểm tra đáp án đi kèm.\n\n**Tham khảo:**\n\n- [aws.amazon.com — strands-agents-sdk-a-technical-deep-dive-into-agent-architectures-and-observability](%5C%22https%3A//aws.amazon.com/blogs/machine-learning/strands-agents-sdk-a-technical-deep-dive-into-agent-architectures-and-observability/%5C%22)\n- [strandsagents.com — model-providers](%5C%22https%3A//strandsagents.com/latest/documentation/docs/user-guide/concepts/model-providers/%5C%22)\n- [strandsagents.com — observability](%5C%22https%3A//strandsagents.com/latest/documentation/docs/user-guide/observability-evaluation/observability/%5C%22)\n- [docs.langchain.com — overview](%5C%22https%3A//docs.langchain.com/oss/python/langgraph/overview%5C%22)\n- [pydantic.dev — logfire](%5C%22https%3A//pydantic.dev/docs/ai/integrations/logfire/%5C%22)", "references": [{"title": "aws.amazon.com — strands-agents-sdk-a-technical-deep-dive-into-agent-architectures-and-observability", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//aws.amazon.com/blogs/machine-learning/strands-agents-sdk-a-technical-deep-dive-into-agent-architectures-and-observability/%5C%22"}, {"title": "strandsagents.com — model-providers", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//strandsagents.com/latest/documentation/docs/user-guide/concepts/model-providers/%5C%22"}, {"title": "strandsagents.com — observability", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//strandsagents.com/latest/documentation/docs/user-guide/observability-evaluation/observability/%5C%22"}, {"title": "docs.langchain.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//docs.langchain.com/oss/python/langgraph/overview%5C%22"}, {"title": "pydantic.dev — logfire", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//pydantic.dev/docs/ai/integrations/logfire/%5C%22"}]}, {"no": 131, "id": 1312, "type": "single", "select": 1, "question": "A team wants higher-confidence answers from a fraud-detection prompt applied to a transaction description. \n\nRather than reviewing different angles, they run the exact same prompt against the same transaction five times and keep whichever verdict -- fraudulent or legitimate -- appears most often across the five runs. \n\nWhich pattern are they using?", "imageMissing": false, "options": [{"key": "A", "text": "Parallelization by sectioning, where five different prompts each examine a distinct aspect of the same transaction independently."}, {"key": "B", "text": "Evaluator-optimizer, where a second LLM call critiques the first verdict and the prompt is revised until the criteria are satisfied."}, {"key": "C", "text": "Prompt chaining, where each of the five runs consumes the verdict produced by the run immediately before it."}, {"key": "D", "text": "Parallelization by voting, where the identical task runs multiple times and the majority verdict is selected."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Parallelization by voting, where the identical task runs multiple times and the majority verdict is selected.\n\nChạy độc lập cùng một tác vụ nhiều lần rồi lấy kết quả đa số là voting. Không có chia thành góc nhìn khác nhau hay truyền kết quả theo chuỗi.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Parallelization by sectioning, where five different prompts each examine a distinct aspect of the same transaction independently.**: Sectioning chia các khía cạnh khác nhau thay vì lặp cùng việc.\n- **Evaluator-optimizer, where a second LLM call critiques the first verdict and the prompt is revised until the criteria are satisfied.**: Evaluator-optimizer cần bước phê bình và cải tiến.\n- **Prompt chaining, where each of the five runs consumes the verdict produced by the run immediately before it.**: Chaining truyền đầu ra bước trước cho bước sau.\n\n**Tham khảo:**\n\n- [www.anthropic.com — building-effective-agents](%5C%22https%3A//www.anthropic.com/research/building-effective-agents%5C%22)", "references": [{"title": "www.anthropic.com — building-effective-agents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//www.anthropic.com/research/building-effective-agents%5C%22"}]}, {"no": 132, "id": 1313, "type": "single", "select": 1, "question": "A support-ticket pipeline runs a simple sentiment classification step on every incoming ticket before the main conversation continues with more complex reasoning. \n\nThis classification happens far more often than any other step and doesn't need the team's most capable model. \n\nHow should the team reduce cost for this specific step?", "imageMissing": false, "options": [{"key": "A", "text": "Convert the pipeline into an agent team, since every teammate in an agent team automatically defaults to the cheapest available model."}, {"key": "B", "text": "Run the classification step in the main conversation using the same model as the rest of the pipeline, since subagents cannot be configured with a different model than their caller."}, {"key": "C", "text": "Convert the classification step into an evaluator-optimizer loop, since that pattern always uses a cheaper model for the evaluator half of the loop."}, {"key": "D", "text": "Route the classification step to a dedicated subagent configured to use a faster, cheaper model, since subagents can be assigned their own model independent of the main conversation."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Route the classification step to a dedicated subagent configured to use a faster, cheaper model, since subagents can be assigned their own model independent of the main conversation.\n\nBộ phân loại riêng có thể dùng model rẻ hơn trong khi agent chính giữ model cho suy luận khó. Cần kiểm tra chất lượng phân loại trước khi chuyển tải thực tế.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Run the classification step in the main conversation using the same model as the rest of the pipeline, since subagents cannot be configured with a different model than their caller.**: Subagent có thể chọn model riêng, không bắt buộc dùng model đắt của agent chính.\n- **Convert the classification step into an evaluator-optimizer loop, since that pattern always uses a cheaper model for the evaluator half of the loop.**: Mẫu evaluator-optimizer không bảo đảm evaluator rẻ hơn.\n- **Convert the pipeline into an agent team, since every teammate in an agent team automatically defaults to the cheapest available model.**: Thành viên nhóm agent không tự động chọn model rẻ nhất.\n\n**Tham khảo:**\n\n- [code.claude.com — subagents](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/subagents%5C%22)", "references": [{"title": "code.claude.com — subagents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/subagents%5C%22"}]}, {"no": 133, "id": 1314, "type": "multiple", "select": 2, "question": "A long-running autonomous agent conversation regularly approaches the model's context window limit. \n\nThe architecture needs the platform to automatically summarize earlier parts of the conversation server-side, and to clear out stale tool results as the token limit approaches, without the client managing this manually. \n\nWhich two features should the architecture enable?", "imageMissing": false, "options": [{"key": "A", "text": "Batch processing"}, {"key": "B", "text": "Prompt caching"}, {"key": "C", "text": "Context editing"}, {"key": "D", "text": "Compaction"}, {"key": "E", "text": "Token counting"}, {"key": "F", "text": "Files API"}], "correct": ["C", "D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Compaction; Context editing\n\nCompaction tóm tắt phần hội thoại cũ. Context editing có thể bỏ kết quả tool hết cần theo chính sách cấu hình. Đề yêu cầu cả hai cơ chế quản lý context.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Prompt caching**: Cache tái sử dụng tiền tố nhưng không bỏ phần context đó.\n- **Token counting**: Đếm token chỉ đo, không tóm tắt hoặc xóa nội dung.\n- **Batch processing**: Batch lập lịch request độc lập, không quản lý hội thoại đang chạy.\n- **Files API**: Files API lưu file, không đặt chính sách cắt context hội thoại.\n\nĐã sửa đáp án nguồn: PDF chỉ đánh dấu một phương án, nhưng đề và đối chiếu từng lựa chọn cho thấy có nhiều phương án đúng. Xem báo cáo kiểm tra đáp án đi kèm.\n\n**Tham khảo:**\n\n- [platform.claude.com — compaction](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/compaction%5C%22)\n- [platform.claude.com — context-editing](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/context-editing%5C%22)", "references": [{"title": "platform.claude.com — compaction", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/compaction%5C%22"}, {"title": "platform.claude.com — context-editing", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/context-editing%5C%22"}]}, {"no": 134, "id": 1316, "type": "single", "select": 1, "question": "An agent built with the Claude Agent SDK reads an authentication module in one query call, and the team wants a second, later query call to reference 'it' meaning that same module without re-reading or re-explaining context. \n\nWhat should they capture and reuse from the first call to accomplish this?", "imageMissing": false, "options": [{"key": "A", "text": "Capture the tool_use_id from the first query's Read tool call and pass it as the model parameter on the second query call."}, {"key": "B", "text": "Capture the file contents read during the first query and hardcode them into the system prompt used for the second query call."}, {"key": "C", "text": "Capture the full text of every message from the first query and re-send it as the prompt string prefix on the second query call."}, {"key": "D", "text": "Capture the session_id from the SystemMessage of type 'init' during the first query, then pass it as the resume option on the second query call."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Capture the session_id from the SystemMessage of type 'init' during the first query, then pass it as the resume option on the second query call.\n\nLấy mã phiên lúc khởi tạo và dùng resume cho query sau. Lịch sử của phiên cung cấp đối tượng được nhắc tới, điều mà phiên độc lập mới chưa biết.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Capture the full text of every message from the first query and re-send it as the prompt string prefix on the second query call.**: Tự ghép lại mọi văn bản là quản lý lịch sử thủ công thay vì dùng API phiên.\n- **Capture the file contents read during the first query and hardcode them into the system prompt used for the second query call.**: Chép cứng file có thể lỗi thời và không khôi phục hội thoại.\n- **Capture the tool_use_id from the first query's Read tool call and pass it as the model parameter on the second query call.**: Mã lượt gọi tool không phải mã phiên hay tên model.\n\n**Tham khảo:**\n\n- [code.claude.com — sessions](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/sessions%5C%22)", "references": [{"title": "code.claude.com — sessions", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/sessions%5C%22"}]}, {"no": 135, "id": 1317, "type": "single", "select": 1, "question": "An engineer building an SDLC automation wants an agent to run git status, stage changes, and commit them as part of a scripted workflow, in addition to reading and editing source files. \n\nWhich built-in Agent SDK tool grants this ability to run version-control commands directly?", "imageMissing": false, "options": [{"key": "A", "text": "Bash, which runs terminal commands and scripts, including git operations, in addition to other shell tasks"}, {"key": "B", "text": "AskUserQuestion, which prompts the user with clarifying multiple-choice questions rather than executing shell commands"}, {"key": "C", "text": "WebFetch, which retrieves and parses web page content and cannot execute local version-control commands"}, {"key": "D", "text": "Grep, which searches file contents with regex and has no ability to invoke external commands like git"}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Bash, which runs terminal commands and scripts, including git operations, in addition to other shell tasks\n\nBash chạy lệnh shell, gồm các lệnh git trong yêu cầu, tùy quyền agent được cấp. Tool tìm kiếm và truy xuất không thực thi lệnh quản lý phiên bản cục bộ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Grep, which searches file contents with regex and has no ability to invoke external commands like git**: Grep tìm văn bản, không chạy git.\n- **WebFetch, which retrieves and parses web page content and cannot execute local version-control commands**: WebFetch lấy nội dung web, không chạy lệnh máy cục bộ.\n- **AskUserQuestion, which prompts the user with clarifying multiple-choice questions rather than executing shell commands**: AskUserQuestion lấy lựa chọn từ người dùng, không thực thi shell.\n\n**Tham khảo:**\n\n- [code.claude.com — overview](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22)", "references": [{"title": "code.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/overview%5C%22"}]}, {"no": 136, "id": 1318, "type": "single", "select": 1, "question": "A batch-processing service runs thousands of independent, single-shot document classification tasks per hour using the Agent SDK. \n\nEach task is unrelated to the others, must never be resumable later, and the team wants to avoid unnecessary disk writes for these throwaway sessions in their TypeScript service. \n\nWhat is the correct session configuration?", "imageMissing": false, "options": [{"key": "A", "text": "Set `persistSession: false` on each `query()` call, so the session exists only in memory for the duration of that call and nothing is written to disk"}, {"key": "B", "text": "Use the Python SDK's `ClaudeSDKClient` instead, since only the Python SDK offers an option to skip writing session transcripts to disk"}, {"key": "C", "text": "Set `continue: true` on each call so every task shares a single reusable session instead of creating a new one each time"}, {"key": "D", "text": "Call `resume` with a randomly generated session ID on each task, which creates a new in-memory-only session and skips disk persistence"}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Set `persistSession: false` on each `query()` call, so the session exists only in memory for the duration of that call and nothing is written to disk\n\nĐặt persistSession thành false cho query TypeScript dùng xong bỏ. Cấu hình này tắt lưu transcript phiên, không có nghĩa tool hoặc mọi thành phần ứng dụng đều bị cấm ghi file khác.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Set `continue: true` on each call so every task shares a single reusable session instead of creating a new one each time**: Dùng tiếp một phiên trộn các tác vụ độc lập và giữ lịch sử của chúng.\n- **Call `resume` with a randomly generated session ID on each task, which creates a new in-memory-only session and skips disk persistence**: Mã resume ngẫu nhiên không phải cấu hình tắt lưu.\n- **Use the Python SDK's `ClaudeSDKClient` instead, since only the Python SDK offers an option to skip writing session transcripts to disk**: Không cần đổi ngôn ngữ vì TypeScript có hỗ trợ tùy chọn này.\n\n**Tham khảo:**\n\n- [code.claude.com — sessions](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/sessions%5C%22)", "references": [{"title": "code.claude.com — sessions", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/sessions%5C%22"}]}, {"no": 137, "id": 1319, "type": "single", "select": 1, "question": "A developer resumes a long-running session with `claude --resume` that was previously running on Opus 4.6. \n\nBetween the original session and the resume, the organization's admin retired Opus 4.6 and it is no longer reachable. \n\nWhat happens when the session resumes?", "imageMissing": false, "options": [{"key": "A", "text": "The session silently resumes on Opus 4.6 anyway, since Claude Code caches the model's response format locally and does not need to reach the retired model to continue an existing transcript"}, {"key": "B", "text": "The session automatically and permanently updates its saved `model` setting to whatever the resume happens to fall back to, overwriting the user's prior explicit `/model` choice for all future sessions"}, {"key": "C", "text": "The resume command fails immediately with an unrecoverable error, since resumed sessions are hard-locked to their originally saved model with no fallback path"}, {"key": "D", "text": "The resumed session falls through to the normal precedence order for selecting a model, since the restored model is unavailable, rather than failing outright"}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** The resumed session falls through to the normal precedence order for selecting a model, since the restored model is unavailable, rather than failing outright\n\nKhi model đã lưu không thể khôi phục, hệ thống có thể chọn theo thứ tự ưu tiên cấu hình thông thường. Khôi phục hội thoại không khôi phục quyền truy cập model từ xa đã ngừng.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **The resume command fails immediately with an unrecoverable error, since resumed sessions are hard-locked to their originally saved model with no fallback path**: Có cơ chế chọn lại nên transcript không bị khóa cứng vào model không khả dụng.\n- **The session silently resumes on Opus 4.6 anyway, since Claude Code caches the model's response format locally and does not need to reach the retired model to continue an existing transcript**: Metadata cache không sinh được phản hồi của model từ xa.\n- **The session automatically and permanently updates its saved `model` setting to whatever the resume happens to fall back to, overwriting the user's prior explicit `/model` choice for all future sessions**: Chọn dự phòng không đồng nghĩa ghi đè vĩnh viễn tùy chọn đã lưu.\n\n**Tham khảo:**\n\n- [code.claude.com — model-config](%5C%22https%3A//code.claude.com/docs/en/model-config%5C%22)", "references": [{"title": "code.claude.com — model-config", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/model-config%5C%22"}]}, {"no": 138, "id": 1320, "type": "multiple", "select": 3, "question": "A team is scoping the operational limits of the Message Batches API before committing to it for a recurring nightly job. \n\nSelect the statements below that accurately describe these limits.", "imageMissing": false, "options": [{"key": "A", "text": "A batch can include `stream: true` on individual requests as long as the overall batch call itself is submitted without streaming, letting each request specify its own streaming behavior."}, {"key": "B", "text": "Batches are visible across every Workspace in an organization by default, so a batch created in one Workspace can be listed and its results downloaded by any other Workspace."}, {"key": "C", "text": "A batch expires if it has not finished processing within 24 hours of creation, and any requests still unprocessed at that point are automatically marked as expired."}, {"key": "D", "text": "Batch results remain available for download for 29 days after the batch creation, after which the batch record still exists but results can no longer be downloaded."}, {"key": "E", "text": "A single Message Batch is restricted to a maximum of 100,000 requests or 256 MB, and the API will immediately reject any batch exceeding either of these limits."}], "correct": ["C", "D", "E"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A single Message Batch is restricted to a maximum of 100,000 requests or 256 MB, and the API will immediately reject any batch exceeding either of these limits.; A batch expires if it has not finished processing within 24 hours of creation, and any requests still unprocessed at that point are automatically marked as expired.; Batch results remain available for download for 29 days after the batch creation, after which the batch record still exists but results can no longer be downloaded.\n\nBatch phải thỏa cả giới hạn số request lẫn dung lượng; phần chưa xử lý hết hạn khi quá thời gian xử lý; kết quả có cửa sổ tải riêng tính từ lúc tạo. Đây là ba giới hạn độc lập.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Batches are visible across every Workspace in an organization by default, so a batch created in one Workspace can be listed and its results downloaded by any other Workspace.**: Batch bị giới hạn trong workspace, không tự hiển thị cho mọi workspace.\n- **A batch can include `stream: true` on individual requests as long as the overall batch call itself is submitted without streaming, letting each request specify its own streaming behavior.**: Không hỗ trợ streaming từng request của batch; kết quả được tải dưới dạng file.\n\nĐã sửa đáp án nguồn: PDF chỉ đánh dấu một phương án, nhưng đề và đối chiếu từng lựa chọn cho thấy có nhiều phương án đúng. Xem báo cáo kiểm tra đáp án đi kèm.\n\n**Tham khảo:**\n\n- [platform.claude.com — batch-processing](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/batch-processing%5C%22)", "references": [{"title": "platform.claude.com — batch-processing", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/batch-processing%5C%22"}]}, {"no": 139, "id": 1321, "type": "single", "select": 1, "question": "A platform team deploys `.claude/settings.json` to every repository with a `permissions.deny` rule blocking `Bash(curl *)`. \n\nAn individual developer adds the opposite rule, an `allow` entry for `Bash(curl *)`, in their own `.claude/settings.local.json` because they need curl for a personal debugging script. \n\nWhen that developer runs Claude Code in the repo, what happens to `curl` commands?", "imageMissing": false, "options": [{"key": "A", "text": "Curl commands prompt for manual approval every time, because conflicting allow and deny rules across scopes cancel each other out and fall back to interactive confirmation"}, {"key": "B", "text": "Curl commands stay blocked, because permission rules merge across scopes instead of one scope overriding another, so a local allow cannot remove a project-level deny"}, {"key": "C", "text": "Curl commands stay blocked only until the developer restarts Claude Code, after which the local settings file's allow rule takes effect on the next session"}, {"key": "D", "text": "Curl commands become allowed, because `settings.local.json` has higher precedence than `settings.json` and its permission rules fully replace the lower-scoped file's rules"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Curl commands stay blocked, because permission rules merge across scopes instead of one scope overriding another, so a local allow cannot remove a project-level deny\n\nDanh sách quyền được gộp qua các phạm vi và deny khớp có ưu tiên chặn. Allow cục bộ của lập trình viên không xóa được deny của repository cho cùng lệnh.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Curl commands become allowed, because `settings.local.json` has higher precedence than `settings.json` and its permission rules fully replace the lower-scoped file's rules**: File ưu tiên cao hơn không thay toàn bộ danh sách quyền đã gộp.\n- **Curl commands prompt for manual approval every time, because conflicting allow and deny rules across scopes cancel each other out and fall back to interactive confirmation**: Deny rõ ràng không tự triệt tiêu thành câu hỏi duyệt.\n- **Curl commands stay blocked only until the developer restarts Claude Code, after which the local settings file's allow rule takes effect on the next session**: Khởi động lại không đổi quy tắc phân giải quyền.\n\n**Tham khảo:**\n\n- [code.claude.com — settings](%5C%22https%3A//code.claude.com/docs/en/settings%5C%22)\n- [code.claude.com — permissions](%5C%22https%3A//code.claude.com/docs/en/permissions%5C%22)", "references": [{"title": "code.claude.com — settings", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/settings%5C%22"}, {"title": "code.claude.com — permissions", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/permissions%5C%22"}]}, {"no": 140, "id": 1322, "type": "single", "select": 1, "question": "A vendor wants to package a set of internal-workflow skills, a custom subagent, an audit-logging hook, and a database MCP server as one reusable unit that different project teams can load into their own Claude Code sessions without copying files into each project. \n\nWhich design satisfies this requirement?", "imageMissing": false, "options": [{"key": "A", "text": "Register the skills, subagent logic, hook scripts, and MCP server configuration as a single custom tool function in the Agent SDK's tool registry, and have each project team enable it by adding the tool to their session's tool-calling loop."}, {"key": "B", "text": "Publish the skills, subagent definition, hook scripts, and MCP server configuration as a single CLAUDE.md file with sections like `## Skills`, `## Agents`, `## Hooks`, and `## MCP`, and have each project load it by adding an import directive in the project configuration."}, {"key": "C", "text": "Place the skills, subagent, hooks, and MCP config into a base directory; then have each team copy the skills into their `.claude/skills/` folder and manually add the subagent, hooks, and MCP settings to their project configuration."}, {"key": "D", "text": "Package the skills, agent, hooks, and MCP server definition into a plugin directory (with `skills/`, `agents/`, `hooks/`, and `.mcp.json`) and have each project load it via the `plugins` option pointing at the plugin's path."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Package the skills, agent, hooks, and MCP server definition into a plugin directory (with `skills/`, `agents/`, `hooks/`, and `.mcp.json`) and have each project load it via the `plugins` option pointing at the plugin's path.\n\nPlugin đóng gói các loại mở rộng này cùng nhau và có thể được nạp theo đường dẫn. Mỗi nhóm tái sử dụng gói thay vì chép từng thành phần vào mọi repository.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Place the skills, subagent, hooks, and MCP config into a base directory; then have each team copy the skills into their `.claude/skills/` folder and manually add the subagent, hooks, and MCP settings to their project configuration.**: Chép thủ công trái với yêu cầu dùng lại mà không nhân bản theo dự án.\n- **Publish the skills, subagent definition, hook scripts, and MCP server configuration as a single CLAUDE.md file with sections like `## Skills`, `## Agents`, `## Hooks`, and `## MCP`, and have each project load it by adding an import directive in the project configuration.**: CLAUDE.md là file hướng dẫn, không phải manifest và bộ nạp plugin.\n- **Register the skills, subagent logic, hook scripts, and MCP server configuration as a single custom tool function in the Agent SDK's tool registry, and have each project team enable it by adding the tool to their session's tool-calling loop.**: Một custom tool không thay thế vòng đời riêng của Skill, agent, hook và cấu hình MCP.\n\n**Tham khảo:**\n\n- [code.claude.com — plugins](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/plugins%5C%22)", "references": [{"title": "code.claude.com — plugins", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/plugins%5C%22"}]}, {"no": 141, "id": 1323, "type": "single", "select": 1, "question": "A product team needs a model for code generation, data analysis, and agentic tool use across a large user base. \n\nThey want the best combination of speed and intelligence rather than the highest-capability, most expensive model. \n\nWhich current Claude model fits this requirement?", "imageMissing": false, "options": [{"key": "A", "text": "Claude Sonnet 5.5"}, {"key": "B", "text": "Claude Haiku 4.5"}, {"key": "C", "text": "Claude Mythos 5.1"}, {"key": "D", "text": "Claude Opus 5.5"}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Claude Sonnet 5.5\n\nTrong các lựa chọn, dòng Sonnet hướng tới cân bằng tốc độ và năng lực. Opus ưu tiên việc khó hơn; chỉ chọn dòng rẻ nhất hoặc mạnh nhất chưa đáp ứng đúng cân bằng cần tìm. Tên model phụ thuộc thời điểm.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Claude Opus 5.5**: Opus ưu tiên công việc đòi hỏi cao hơn thay vì cân bằng được hỏi.\n- **Claude Haiku 4.5**: Haiku ưu tiên độ trễ và chi phí thấp hơn là mức cân bằng năng lực trong đề.\n- **Claude Mythos 5.1**: Mythos không phải lựa chọn cân bằng cho công việc phổ thông đang mô tả.\n\n**Tham khảo:**\n\n- [platform.claude.com — overview](%5C%22https%3A//platform.claude.com/docs/en/models/sonnet-5-5/overview%5C%22)", "references": [{"title": "platform.claude.com — overview", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/models/sonnet-5-5/overview%5C%22"}]}, {"no": 142, "id": 1324, "type": "single", "select": 1, "question": "A team's usage sits well under their published requests-per-minute limit, yet they begin seeing 429 errors after a marketing campaign causes API traffic to triple within a few minutes. \n\nHistorical usage was steady before the spike. \n\nWhat is the most likely explanation, and what should the team change to avoid recurrence?", "imageMissing": false, "options": [{"key": "A", "text": "The spike exceeded the request size limit for the Messages API, so each oversized request was individually rejected with a rate-limit error"}, {"key": "B", "text": "The published RPM limit only applies to the Message Batches API, so any spike in synchronous Messages API traffic will always return 429 regardless of pacing"}, {"key": "C", "text": "The 429 responses indicate the organization's API key was automatically revoked for suspected abuse and must be regenerated in the Console"}, {"key": "D", "text": "The spike likely triggered acceleration limits designed to catch sharp usage increases; the team should ramp traffic up gradually and keep usage patterns more consistent"}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** The spike likely triggered acceleration limits designed to catch sharp usage increases; the team should ramp traffic up gradually and keep usage patterns more consistent\n\nTải tăng đột ngột có thể chạm acceleration limit dù chưa đạt trần RPM ổn định. Tăng tải từ từ xử lý đúng dạng tăng vọt thay vì chỉ giảm mức trung bình.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **The published RPM limit only applies to the Message Batches API, so any spike in synchronous Messages API traffic will always return 429 regardless of pacing**: RPM không chỉ áp dụng cho Message Batches.\n- **The 429 responses indicate the organization's API key was automatically revoked for suspected abuse and must be regenerated in the Console**: Mã 429 không có nghĩa API key tự bị thu hồi.\n- **The spike exceeded the request size limit for the Messages API, so each oversized request was individually rejected with a rate-limit error**: Quá dung lượng request là lỗi kích thước payload, được phân biệt với hạn mức tần suất.\n\n**Tham khảo:**\n\n- [platform.claude.com — rate-limits](%5C%22https%3A//platform.claude.com/docs/en/api/rate-limits%5C%22)", "references": [{"title": "platform.claude.com — rate-limits", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/api/rate-limits%5C%22"}]}, {"no": 143, "id": 1325, "type": "multiple", "select": 3, "question": "An engineer is deciding, for several failing requests, whether simply switching to the streaming API or increasing max_tokens would resolve the failure. \n\nSelect all of the following scenarios where neither of those two changes would fix the described error.", "imageMissing": false, "options": [{"key": "A", "text": "A request fails with 409 conflict_error because two workers concurrently modified the same underlying resource before this request was sent"}, {"key": "B", "text": "A request fails with 401 authentication_error because the API key used to sign the request has expired"}, {"key": "C", "text": "A request fails with 504 timeout_error because a very large non-streaming generation ran past the idle-connection limit on an unreliable network"}, {"key": "D", "text": "A response completes with stop_reason set to max_tokens because the generated content reached the configured output token cap"}, {"key": "E", "text": "A request fails with 413 request_too_large because the inlined message content itself exceeds the Messages API's maximum request payload size"}], "correct": ["A", "B", "E"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A request fails with 413 request_too_large because the inlined message content itself exceeds the Messages API's maximum request payload size; A request fails with 409 conflict_error because two workers concurrently modified the same underlying resource before this request was sent; A request fails with 401 authentication_error because the API key used to sign the request has expired\n\nLỗi kích thước cần giảm hoặc tổ chức lại đầu vào; xung đột cần xử lý trạng thái tài nguyên; lỗi xác thực cần thông tin đăng nhập hợp lệ. Đổi cách truyền hoặc ngân sách đầu ra không sửa ba nguyên nhân này.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **A response completes with stop_reason set to max_tokens because the generated content reached the configured output token cap**: Đầu ra dừng vì max_tokens có thể được xử lý bằng tăng giới hạn đầu ra nếu model hỗ trợ.\n- **A request fails with 504 timeout_error because a very large non-streaming generation ran past the idle-connection limit on an unreliable network**: Streaming có thể giúp tình huống kết nối không streaming bị timeout lúc chờ quá lâu như đề mô tả.\n\nĐã sửa đáp án nguồn: PDF chỉ đánh dấu một phương án, nhưng đề và đối chiếu từng lựa chọn cho thấy có nhiều phương án đúng. Xem báo cáo kiểm tra đáp án đi kèm.\n\n**Tham khảo:**\n\n- [platform.claude.com — errors](%5C%22https%3A//platform.claude.com/docs/en/api/errors%5C%22)", "references": [{"title": "platform.claude.com — errors", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/api/errors%5C%22"}]}, {"no": 144, "id": 1326, "type": "single", "select": 1, "question": "A billing-sensitive workload needs to know exactly how many tokens a large prompt will consume before it is sent to Claude, so the team can stay within a budget. \n\nWhat should they use?", "imageMissing": false, "options": [{"key": "A", "text": "The budget_tokens field on extended thinking, which caps and reports total request token usage"}, {"key": "B", "text": "A token counting call, to determine the number of tokens in a message before sending it"}, {"key": "C", "text": "The effort parameter set to low, which returns an estimated token count in the response metadata"}, {"key": "D", "text": "The Files API, since uploaded files automatically report their token size before generation begins"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** A token counting call, to determine the number of tokens in a message before sending it\n\nDùng endpoint đếm token trước khi sinh để ước lượng đầu vào. Tài liệu chính thức lưu ý số đếm có thể lệch nhẹ so với mức dùng thực tế; từ exactly trong đề không phải bảo đảm hóa đơn tuyệt đối.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **The effort parameter set to low, which returns an estimated token count in the response metadata**: Effort điều khiển suy luận, không trả số token trước request.\n- **The Files API, since uploaded files automatically report their token size before generation begins**: Tải file không thay thế đếm toàn bộ đầu vào message.\n- **The budget_tokens field on extended thinking, which caps and reports total request token usage**: Ngân sách thinking điều khiển phần suy luận đầu ra, không đo đầu vào.\n\n**Tham khảo:**\n\n- [platform.claude.com — token-counting](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/token-counting%5C%22)", "references": [{"title": "platform.claude.com — token-counting", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/token-counting%5C%22"}]}, {"no": 145, "id": 1327, "type": "single", "select": 1, "question": "While streaming a response with extended thinking enabled, a client receives a thinking content block that ends with a signature_delta event immediately before content_block_stop. \n\nWhat is the purpose of this signature_delta event?", "imageMissing": false, "options": [{"key": "A", "text": "It marks the point at which the thinking block's token usage should be added to the cumulative usage total."}, {"key": "B", "text": "It signals that a fallback model has taken over generation for the remainder of the response."}, {"key": "C", "text": "It provides a signature used to verify the integrity of the thinking block's content."}, {"key": "D", "text": "It indicates that the thinking block has been redacted for policy compliance and its content should be discarded."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** It provides a signature used to verify the integrity of the thinking block's content.\n\nChữ ký đi kèm khối thinking để phục vụ xác minh tính toàn vẹn. Giữ nội dung thinking và chữ ký khi giao thức yêu cầu gửi lại những khối này ở lượt sau.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **It marks the point at which the thinking block's token usage should be added to the cumulative usage total.**: Token dùng được báo qua trường usage, không phải mục đích của chữ ký.\n- **It indicates that the thinking block has been redacted for policy compliance and its content should be discarded.**: Khối redacted thinking khác khối thinking có chữ ký.\n- **It signals that a fallback model has taken over generation for the remainder of the response.**: Sự kiện chữ ký không biểu thị đổi model.\n\n**Tham khảo:**\n\n- [platform.claude.com — streaming](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/streaming%5C%22)", "references": [{"title": "platform.claude.com — streaming", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/streaming%5C%22"}]}, {"no": 146, "id": 1328, "type": "single", "select": 1, "question": "A junior engineer asks why Claude appears to produce text piece by piece rather than generating the entire response instantly. \n\nWhich explanation best matches how Claude generates output?", "imageMissing": false, "options": [{"key": "A", "text": "Claude retrieves the entire response from a precomputed lookup table by matching the prompt's embedding to a database of response embeddings and returning the nearest full text."}, {"key": "B", "text": "Claude generates tokens in a random order, then applies a learned reordering function to arrange them into a coherent response before returning it."}, {"key": "C", "text": "Claude autoregressively predicts the next token based on the prompt and previously generated tokens, repeating the process to build the full response."}, {"key": "D", "text": "Claude generates the full response as a complete string in one forward pass through the model, then splits it into tokens only for transmission to the client."}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Claude autoregressively predicts the next token based on the prompt and previously generated tokens, repeating the process to build the full response.\n\nSinh tự hồi quy dự đoán token kế tiếp từ ngữ cảnh và các token đã sinh. Lặp bước đó tạo nên câu trả lời; streaming cho thấy tiến trình từng phần.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Claude retrieves the entire response from a precomputed lookup table by matching the prompt's embedding to a database of response embeddings and returning the nearest full text.**: Sinh văn bản không phải tra nguyên câu trả lời bằng embedding.\n- **Claude generates the full response as a complete string in one forward pass through the model, then splits it into tokens only for transmission to the client.**: Không sinh toàn bộ câu trả lời trong một forward pass rồi mới tách token.\n- **Claude generates tokens in a random order, then applies a learned reordering function to arrange them into a coherent response before returning it.**: Token không được sinh đảo thứ tự rồi sắp xếp lại.\n\n**Tham khảo:**\n\n- [platform.claude.com — glossary](%5C%22https%3A//platform.claude.com/docs/en/about-claude/glossary%5C%22)", "references": [{"title": "platform.claude.com — glossary", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/about-claude/glossary%5C%22"}]}, {"no": 147, "id": 1329, "type": "single", "select": 1, "question": "A support-ticket triage service sends the same 6,000-token system prompt and tool definitions with every request, followed by a unique customer message. \n\nRequests arrive in bursts roughly every 30 seconds throughout the day. \n\nThe team wants to cut input token costs on the repeated prefix without adding infrastructure. \n\nWhich change addresses this most directly?", "imageMissing": false, "options": [{"key": "A", "text": "Move the system prompt and tool definitions into each request's user message so that the fixed 6,000-token prefix is cached per message, cutting input costs across the 30-second burst cycle."}, {"key": "B", "text": "Mark the system prompt and tool definitions with a 5-minute ephemeral cache_control breakpoint; repeated requests then read the prefix from cache, avoiding the full input price."}, {"key": "C", "text": "Switch the tool definitions to a compact JSON schema with shorter property names and fewer nested objects, so the 6,000-token prefix shrinks and each request consumes fewer input tokens."}, {"key": "D", "text": "Reduce the max_tokens parameter on every request to the minimum needed for a short triage response, so Claude's completions stay brief and the blended token cost per call decreases."}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Mark the system prompt and tool definitions with a 5-minute ephemeral cache_control breakpoint; repeated requests then read the prefix from cache, avoiding the full input price.\n\nĐặt điểm cache ephemeral được hỗ trợ ở cuối tiền tố tools/system ổn định. Request trùng tiền tố trong thời gian cache có thể dùng lại; phần tin nhắn khách hàng thay đổi không nằm trong tiền tố đó.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Move the system prompt and tool definitions into each request's user message so that the fixed 6,000-token prefix is cached per message, cutting input costs across the 30-second burst cycle.**: Chuyển sang user message không tự bật cache.\n- **Reduce the max_tokens parameter on every request to the minimum needed for a short triage response, so Claude's completions stay brief and the blended token cost per call decreases.**: Giảm ngân sách đầu ra không giảm đơn giá tiền tố đầu vào lặp lại.\n- **Switch the tool definitions to a compact JSON schema with shorter property names and fewer nested objects, so the 6,000-token prefix shrinks and each request consumes fewer input tokens.**: Rút gọn schema có thể tiết kiệm token nhưng chưa tạo tái sử dụng tiền tố.\n\n**Tham khảo:**\n\n- [platform.claude.com — prompt-caching](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/prompt-caching%5C%22)", "references": [{"title": "platform.claude.com — prompt-caching", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/prompt-caching%5C%22"}]}, {"no": 148, "id": 1330, "type": "single", "select": 1, "question": "An engineer is building a research agent that needs to read dozens of files across a large repository to answer one question, without letting all that file content pile up in the main conversation's context. \n\nWhich design best achieves this?", "imageMissing": false, "options": [{"key": "A", "text": "Store all file contents in a custom MCP resource and have the main agent fetch a single combined resource URI instead of individual files"}, {"key": "B", "text": "Read every file directly in the main agent loop, but set effort to low so the extra file content consumes fewer tokens per turn"}, {"key": "C", "text": "Delegate the file exploration to a subagent, whose fresh context absorbs all the intermediate reads while only its final summary message returns to the parent"}, {"key": "D", "text": "Read every file directly in the main agent loop, then issue a manual /compact command immediately afterward to shrink the accumulated history"}], "correct": ["C"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Delegate the file exploration to a subagent, whose fresh context absorbs all the intermediate reads while only its final summary message returns to the parent\n\nSubagent khám phá giữ các lượt đọc chi tiết trong context riêng rồi trả phát hiện về. Context agent chính được dành cho quyết định thay vì đầy mã nguồn thô.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Read every file directly in the main agent loop, then issue a manual /compact command immediately afterward to shrink the accumulated history**: Nén sau khi đọc vẫn nạp mọi file vào agent chính trước khi tóm tắt.\n- **Read every file directly in the main agent loop, but set effort to low so the extra file content consumes fewer tokens per turn**: Effort thấp không làm ngắn nội dung file.\n- **Store all file contents in a custom MCP resource and have the main agent fetch a single combined resource URI instead of individual files**: Lấy một resource gộp vẫn đưa toàn bộ kết quả đó vào agent chính.\n\n**Tham khảo:**\n\n- [code.claude.com — subagents](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/subagents%5C%22)", "references": [{"title": "code.claude.com — subagents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/subagents%5C%22"}]}, {"no": 149, "id": 1331, "type": "single", "select": 1, "question": "A prompt written for a legal-document summarizer produces inconsistent structure across runs, and engineers on the team disagree about why. \n\nBefore tuning the prompt further, which practice would most directly reveal ambiguity in the current wording?", "imageMissing": false, "options": [{"key": "A", "text": "Ask Claude to explain its own instructions back in a separate call, treating the model's paraphrase of the prompt as a reliable substitute for a human comprehension check"}, {"key": "B", "text": "Show the prompt to a colleague who has minimal context on the task and ask them to follow it exactly as written, since confusion for a human reader tends to predict confusion for Claude"}, {"key": "C", "text": "Reduce the temperature to zero for the summarizer's requests, on the assumption that ambiguity in phrasing is resolved by lower-variance sampling rather than by clearer instructions"}, {"key": "D", "text": "Rerun the identical, unedited prompt against the model twenty times and keep only the most common resulting structure, treating majority voting as a substitute for locating the ambiguity"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Show the prompt to a colleague who has minimal context on the task and ask them to follow it exactly as written, since confusion for a human reader tends to predict confusion for Claude\n\nNgười đọc mới giúp phát hiện giả định chưa nói ra và chỉ dẫn mơ hồ. Yêu cầu họ làm đúng theo văn bản rồi sửa những điểm họ không thể hiểu thống nhất.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Rerun the identical, unedited prompt against the model twenty times and keep only the most common resulting structure, treating majority voting as a substitute for locating the ambiguity**: Chọn kết quả đa số không chỉ ra chỗ diễn đạt lỗi.\n- **Ask Claude to explain its own instructions back in a separate call, treating the model's paraphrase of the prompt as a reliable substitute for a human comprehension check**: Model diễn giải lại không thay thế kiểm tra hiểu độc lập.\n- **Reduce the temperature to zero for the summarizer's requests, on the assumption that ambiguity in phrasing is resolved by lower-variance sampling rather than by clearer instructions**: Giảm độ ngẫu nhiên không làm yêu cầu mơ hồ thành rõ ràng.\n\n**Tham khảo:**\n\n- [platform.claude.com — claude-prompting-best-practices](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices%5C%22)", "references": [{"title": "platform.claude.com — claude-prompting-best-practices", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices%5C%22"}]}, {"no": 150, "id": 1332, "type": "single", "select": 1, "question": "A summarization service parses the response text as JSON. For very long transcripts, the JSON string is occasionally cut off mid-object and the parser raises a decode error. Investigating, the engineer finds stop_reason is \"max_tokens\" on every one of the failing calls. \n\nWhat should the defensive parsing logic do?", "imageMissing": false, "options": [{"key": "A", "text": "Lower max_tokens further so Claude is forced to produce shorter, safer completions"}, {"key": "B", "text": "Catch the decode error, check stop_reason for max_tokens, and treat the response as incomplete"}, {"key": "C", "text": "Ignore stop_reason and retry parsing with a lenient JSON parser that tolerates trailing commas"}, {"key": "D", "text": "Treat every JSON decode error as a transient network issue and resend the identical request"}], "correct": ["B"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Catch the decode error, check stop_reason for max_tokens, and treat the response as incomplete\n\nLý do dừng cho biết quá trình sinh chưa hoàn tất, không phải một tài liệu hoàn chỉnh bị sai cú pháp. Bắt lỗi parse, nhận diện cắt ngắn rồi thử lại với ngân sách phù hợp hoặc tác vụ nhỏ hơn.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Ignore stop_reason and retry parsing with a lenient JSON parser that tolerates trailing commas**: Parser nới lỏng không khôi phục được phần nội dung chưa được sinh.\n- **Lower max_tokens further so Claude is forced to produce shorter, safer completions**: Giảm giới hạn làm tăng nguy cơ cắt ngắn.\n- **Treat every JSON decode error as a transient network issue and resend the identical request**: Gửi lại y nguyên bỏ qua nguyên nhân giới hạn đầu ra đã thấy.\n\n**Tham khảo:**\n\n- [platform.claude.com — handling-stop-reasons](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/handling-stop-reasons%5C%22)", "references": [{"title": "platform.claude.com — handling-stop-reasons", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/handling-stop-reasons%5C%22"}]}, {"no": 151, "id": 1333, "type": "multiple", "select": 3, "question": "During testing, an agent occasionally calls a create_ticket tool while omitting the required priority field. \n\nWhich of the following are appropriate ways to handle this within the conversation, according to recommended tool-use error handling? (Select all that apply)", "imageMissing": false, "options": [{"key": "A", "text": "Add strict: true to the tool definition so input is validated against the schema before your handler"}, {"key": "B", "text": "Automatically terminate the session and require the user to start an entirely new conversation"}, {"key": "C", "text": "Return a tool_result with is_error: true naming the missing field so Claude retries with it supplied"}, {"key": "D", "text": "Improve the tool's description so the priority-field requirement is stated more explicitly"}, {"key": "E", "text": "Log the omission silently and proceed with ticket creation using a null priority value"}, {"key": "F", "text": "Rewrite the schema to make priority optional so it can never be reported as missing again"}], "correct": ["A", "C", "D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Return a tool_result with is_error: true naming the missing field so Claude retries with it supplied; Add strict: true to the tool definition so input is validated against the schema before your handler; Improve the tool's description so the priority-field requirement is stated more explicitly\n\nTrả lỗi nêu rõ priority để Claude sửa lời gọi. Strict tool use theo schema có thể ngăn thiếu trường; mô tả rõ hơn củng cố yêu cầu. Ba cách lần lượt hỗ trợ phục hồi, phòng ngừa và hướng dẫn; mô tả không thay thế kiểm tra dữ liệu.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Automatically terminate the session and require the user to start an entirely new conversation**: Khởi động lại cả phiên là không cần cho lỗi tham số có thể sửa.\n- **Log the omission silently and proceed with ticket creation using a null priority value**: Dùng null âm thầm vi phạm ý nghĩa trường bắt buộc.\n- **Rewrite the schema to make priority optional so it can never be reported as missing again**: Cho trường thành tùy chọn là bỏ hợp đồng yêu cầu priority.\n\nĐã sửa đáp án nguồn: PDF chỉ đánh dấu một phương án, nhưng đề và đối chiếu từng lựa chọn cho thấy có nhiều phương án đúng. Xem báo cáo kiểm tra đáp án đi kèm.\n\n**Tham khảo:**\n\n- [platform.claude.com — handle-tool-calls](%5C%22https%3A//platform.claude.com/docs/en/agents-and-tools/tool-use/handle-tool-calls%5C%22)\n- [platform.claude.com — strict-tool-use](%5C%22https%3A//platform.claude.com/docs/en/agents-and-tools/tool-use/strict-tool-use%5C%22)", "references": [{"title": "platform.claude.com — handle-tool-calls", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/agents-and-tools/tool-use/handle-tool-calls%5C%22"}, {"title": "platform.claude.com — strict-tool-use", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/agents-and-tools/tool-use/strict-tool-use%5C%22"}]}, {"no": 152, "id": 1334, "type": "single", "select": 1, "question": "A prompt concatenates two source documents as plain, undifferentiated text, and Claude's responses sometimes misattribute which document a fact came from. \n\nWhat restructuring best fixes this attribution problem?", "imageMissing": false, "options": [{"key": "A", "text": "Insert a page-break control character between the two documents, such as a form feed, and prepend a short system note that instructs Claude to treat the page break as a document separator for attribution."}, {"key": "B", "text": "Prefix each document with a numbered markdown heading (e.g., \"# Document 1\") and then include a prompt instruction for Claude to attribute facts based solely on which heading they appear under."}, {"key": "C", "text": "Convert both documents into a single CSV file where each row holds one paragraph and the left column labels the source document, so Claude can read the tabular data and attribute facts to the correct source."}, {"key": "D", "text": "Wrap each document in its own tag with nested  and subtags, placed inside an outer tag, thereby providing clear boundaries and metadata."}], "correct": ["D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Wrap each document in its own \n\nDùng ranh giới từng tài liệu và metadata nguồn để gắn dữ kiện với tài liệu gốc. Khi hiển thị ví dụ thẻ như văn bản, cần escape đúng để không mất nội dung.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Insert a page-break control character between the two documents, such as a form feed, and prepend a short system note that instructs Claude to treat the page break as a document separator for attribution.**: Ngắt trang không cung cấp mã nguồn ổn định hay ranh giới có cấu trúc.\n- **Prefix each document with a numbered markdown heading (e.g., \\\"# Document 1\\\") and then include a prompt instruction for Claude to attribute facts based solely on which heading they appear under.**: Tiêu đề đơn giản kém rõ hơn cấu trúc nguồn/nội dung lồng nhau được đề xuất.\n- **Convert both documents into a single CSV file where each row holds one paragraph and the left column labels the source document, so Claude can read the tabular data and attribute facts to the correct source.**: Dồn thành CSV có thể làm mất cấu trúc và là bước chuyển không cần thiết.\n\n**Tham khảo:**\n\n- [platform.claude.com — claude-prompting-best-practices](%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices%5C%22)", "references": [{"title": "platform.claude.com — claude-prompting-best-practices", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices%5C%22"}]}, {"no": 153, "id": 1335, "type": "single", "select": 1, "question": "A subagent is defined to automatically spawn further subagents to divide up its own workload, and those in turn may spawn more. \n\nWhat governs how deep this nesting can go, and how can a team stop a specific subagent from spawning any children at all?", "imageMissing": false, "options": [{"key": "A", "text": "Nesting defaults to three levels below the main agent and can be changed with the `CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH` setting; omitting `Agent` from a subagent's tools (or adding it to `disallowedTools`) prevents that subagent from spawning children."}, {"key": "B", "text": "Nesting is unlimited regardless of execution mode, because there is no built-in depth limit, and to prevent a specific subagent from spawning children, the team must remove the `Bash` tool from its tools list to block the execution of child-spawning commands."}, {"key": "C", "text": "Nesting is capped at two levels only when the subagent runs in the foreground, because foreground execution limits nesting to two levels, and to prevent a subagent from spawning children, set its `permissionMode` to `plan` to restrict it to read-only and prevent spawning."}, {"key": "D", "text": "Nesting has no depth limit as long as each subagent runs in the background, because background execution bypasses the configured depth cap, and to prevent a particular subagent from spawning children, set its effort level to low, which prevents it from spawning children."}], "correct": ["A"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Nesting defaults to three levels below the main agent and can be changed with the `CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH` setting; omitting `Agent` from a subagent's tools (or adding it to `disallowedTools`) prevents that subagent from spawning children.\n\nTrên các phiên bản SDK mới được tài liệu nêu, độ sâu mặc định là ba tầng và chỉnh bằng biến môi trường đã cho. Bỏ khả năng dùng Agent của một subagent sẽ ngăn nó ủy nhiệm tiếp. Cần kiểm tra phiên bản triển khai vì bản cũ có mặc định khác.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Nesting has no depth limit as long as each subagent runs in the background, because background execution bypasses the configured depth cap, and to prevent a particular subagent from spawning children, set its effort level to low, which prevents it from spawning children.**: Chạy nền không xóa trần độ sâu; effort không phải quyền sinh agent.\n- **Nesting is capped at two levels only when the subagent runs in the foreground, because foreground execution limits nesting to two levels, and to prevent a subagent from spawning children, set its `permissionMode` to `plan` to restrict it to read-only and prevent spawning.**: Plan mode không phải cơ chế trực tiếp loại tool Agent.\n- **Nesting is unlimited regardless of execution mode, because there is no built-in depth limit, and to prevent a specific subagent from spawning children, the team must remove the `Bash` tool from its tools list to block the execution of child-spawning commands.**: Bỏ Bash không loại khả năng ủy nhiệm bằng Agent.\n\n**Tham khảo:**\n\n- [code.claude.com — subagents](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/subagents%5C%22)", "references": [{"title": "code.claude.com — subagents", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/subagents%5C%22"}]}, {"no": 154, "id": 1336, "type": "multiple", "select": 3, "question": "A support agent built on Claude has access to a customer database tool and forwards conversation transcripts to a third-party analytics vendor for quality monitoring. \n\nTranscripts routinely contain customers' full names, emails, and account numbers. \n\nWhich of these actions should the team take to prevent unnecessary PII exposure? (Select all that apply.)", "imageMissing": false, "options": [{"key": "A", "text": "Compress the transcripts before sending them, since compression is treated as equivalent to redaction for the purpose of protecting personal data"}, {"key": "B", "text": "Review which fields the analytics vendor's quality-monitoring use case genuinely requires before deciding what to include in each transcript export"}, {"key": "C", "text": "Apply the same PII minimization to data logged internally for debugging, not just to data sent to the external vendor"}, {"key": "D", "text": "Ask Claude to verbally warn the customer at the start of each chat that their data might be shared externally, then proceed without further changes"}, {"key": "E", "text": "Send the full unredacted transcripts as-is, since the analytics vendor's contract already covers general data handling and confidentiality obligations"}, {"key": "F", "text": "Redact or mask personally identifiable information in the transcripts before they leave the system, sending the vendor only the fields it actually needs"}], "correct": ["B", "C", "F"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Redact or mask personally identifiable information in the transcripts before they leave the system, sending the vendor only the fields it actually needs; Apply the same PII minimization to data logged internally for debugging, not just to data sent to the external vendor; Review which fields the analytics vendor's quality-monitoring use case genuinely requires before deciding what to include in each transcript export\n\nXác định trường dữ liệu cần cho giám sát, rồi che hoặc bỏ dữ liệu cá nhân không cần khi xuất và khi ghi log nội bộ. Hợp đồng hay lời thông báo không tự làm giảm dữ liệu bị lộ.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Send the full unredacted transcripts as-is, since the analytics vendor's contract already covers general data handling and confidentiality obligations**: Hợp đồng bảo mật không biện minh cho việc gửi định danh thô không cần thiết.\n- **Compress the transcripts before sending them, since compression is treated as equivalent to redaction for the purpose of protecting personal data**: Nén là biến đổi có thể khôi phục, không phải che dữ liệu.\n- **Ask Claude to verbally warn the customer at the start of each chat that their data might be shared externally, then proceed without further changes**: Cảnh báo bằng lời không xóa trường thừa hoặc bảo vệ log.\n\nĐã sửa đáp án nguồn: PDF chỉ đánh dấu một phương án, nhưng đề và đối chiếu từng lựa chọn cho thấy có nhiều phương án đúng. Xem báo cáo kiểm tra đáp án đi kèm.\n\n**Tham khảo:**\n\n- [strandsagents.com — observability](%5C%22https%3A//strandsagents.com/latest/documentation/docs/user-guide/observability-evaluation/observability/%5C%22)\n- [pydantic.dev — logfire](%5C%22https%3A//pydantic.dev/docs/ai/integrations/logfire/%5C%22)", "references": [{"title": "strandsagents.com — observability", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//strandsagents.com/latest/documentation/docs/user-guide/observability-evaluation/observability/%5C%22"}, {"title": "pydantic.dev — logfire", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//pydantic.dev/docs/ai/integrations/logfire/%5C%22"}]}, {"no": 155, "id": 1337, "type": "multiple", "select": 3, "question": "A fintech company is deploying a multi-tenant Claude-powered advisor that reads account data for one customer per session and can place trades through an internal API. \n\nWhich combination of practices best supports authentication, authorization, and confidentiality across tenants? (Select all that apply.)", "imageMissing": false, "options": [{"key": "A", "text": "Require a fresh authorization check on the backend before executing any trade action the agent requests, rather than trusting the agent's own judgment alone"}, {"key": "B", "text": "Issue one shared service credential for the trading API that every customer session reuses, to simplify credential rotation"}, {"key": "C", "text": "Screen inbound account notes and support messages for injected instructions before they are returned to Claude as tool results"}, {"key": "D", "text": "Scope each session's tool access so it can only read and act on the data belonging to the authenticated customer for that session"}, {"key": "E", "text": "Log full account numbers and portfolio balances in plaintext application logs so support staff can search history freely"}, {"key": "F", "text": "Let a session continue reading a different customer's data mid-conversation if the agent decides it is contextually relevant to the current advice"}], "correct": ["A", "C", "D"], "yourAnswer": [], "result": "unanswered", "explanation": "**Nội dung đáp án theo khóa nguồn:** Scope each session's tool access so it can only read and act on the data belonging to the authenticated customer for that session; Screen inbound account notes and support messages for injected instructions before they are returned to Claude as tool results; Require a fresh authorization check on the backend before executing any trade action the agent requests, rather than trusting the agent's own judgment alone\n\nGiới hạn tool theo khách hàng của phiên và kiểm tra quyền lại tại backend trước mỗi giao dịch. Sàng lọc chỉ dẫn chèn trong ghi chú không tin cậy là lớp phòng vệ bổ sung trước việc vượt ranh giới; không thay thế phân quyền.\n\n#### Vì sao các phương án khác không phù hợp?\n\n- **Issue one shared service credential for the trading API that every customer session reuses, to simplify credential rotation**: Một thông tin xác thực dùng chung không giới hạn chưa tạo phân quyền theo khách hàng.\n- **Log full account numbers and portfolio balances in plaintext application logs so support staff can search history freely**: Log tài khoản nhạy cảm dạng rõ làm giảm bảo mật.\n- **Let a session continue reading a different customer's data mid-conversation if the agent decides it is contextually relevant to the current advice**: Nhận định của agent không cấp quyền đọc dữ liệu khách hàng khác.\n\nĐã sửa đáp án nguồn: PDF chỉ đánh dấu một phương án, nhưng đề và đối chiếu từng lựa chọn cho thấy có nhiều phương án đúng. Xem báo cáo kiểm tra đáp án đi kèm.\n\n**Tham khảo:**\n\n- [code.claude.com — secure-deployment](%5C%22https%3A//code.claude.com/docs/en/agent-sdk/secure-deployment%5C%22)\n- [modelcontextprotocol.io — security_best_practices](%5C%22https%3A//modelcontextprotocol.io/docs/tutorials/security/security_best_practices%5C%22)\n- [platform.claude.com — mitigate-jailbreaks](%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks%5C%22)", "references": [{"title": "code.claude.com — secure-deployment", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//code.claude.com/docs/en/agent-sdk/secure-deployment%5C%22"}, {"title": "modelcontextprotocol.io — security_best_practices", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//modelcontextprotocol.io/docs/tutorials/security/security_best_practices%5C%22"}, {"title": "platform.claude.com — mitigate-jailbreaks", "url": "https://practice-cert.maithienan.com/practice/ccdv-f/%5C%22https%3A//platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/mitigate-jailbreaks%5C%22"}]}];
